  str_dispatch_book_chaptername_15000_12 = "編輯後記（下）",
  str_dispatch_book_chapterdes_1000_1 = "有信者得啟示，屈身而聽，必敬畏、必憐恤；\n無信者無啟示，偏離典章，無遵守、無警戒；\n得啟示者遇戰禍，脫離災難；\n無啟示者無戰禍，必如碎秸。",
  str_dispatch_book_chapterdes_1000_2 = "光之神必為諸人爭戰，諸人只管靜默，不要作聲；\n光之神將海水分開、將山峰抹平，諸人只管靜默，不要作聲。",
  str_dispatch_book_chapterdes_1000_3 = "兩造之間，實施審判，叫諸人知道神的律例和法度；\n敬神的、無信的，依律法所斷，恩賞或受罰。",
  str_dispatch_book_chapterdes_1000_4 = "所求之物，必尋見；\n所許之願，必償還。 \n記住所言，直至亙古；\n記住所約，啟示永遠。",
  str_dispatch_book_chapterdes_2000_1 = "亞人族在命運的安排下，發現了史上最大的人工開鑿洞穴。生性單純天真的他們，迸發出了劈山開海的偉力，為了建設屬於自己的家園，為了屬於自己的「新福地」。",
  str_dispatch_book_chapterdes_2000_2 = "千餘年前，亞人族發現了祕境洞穴。此後數百年間，無數的亞人族在此出生、在此長大、在此死去。「祕境」成為亞人族心中無上的代名詞，是所有亞人族的故土。然而，隨著暗鬼入侵，亞人族失去了祕境洞穴……",
  str_dispatch_book_chapterdes_2000_3 = "祕境洞穴是所有亞人族現實與精神上的家園。因此，當暗鬼入侵此地時，不僅留守於祕境洞穴的亞人族展開了殊死抵抗，在外遊蕩的所有亞人族也返回了這裡，一同對抗暗鬼。然而，就是這份對於家園的執念，為亞人族引來了毀滅。",
  str_dispatch_book_chapterdes_2000_4 = "亞人族的覆滅，讓光靈們措手不及。為此，啟光聯邦派出探索隊，進入暗鬼橫行的祕境洞穴，以查明亞人族覆滅的原因。然而，彼時的祕境洞穴已成為了危機四伏的所在，就連意志最堅定的啟光士兵也會心生恐懼。",
  str_dispatch_book_chapterdes_3000_1 = "無名傭兵完成一次行動任務後的回憶。為了保密，傭兵將某些地名留白，使閱讀者無法猜測。",
  str_dispatch_book_chapterdes_3000_2 = "無名傭兵的另一次記錄，之前的行動似乎並未拿到應有的報酬，而這次行動似乎又面臨了難題。",
  str_dispatch_book_chapterdes_3000_3 = "經歷了討薪失敗，放棄了難以完成的任務，無名傭兵似乎找了一份不太像傭兵的工作。意外的是，對於這份工作，傭兵在字裡行間透出了某種喜悅之情。",
  str_dispatch_book_chapterdes_3000_4 = "無名傭兵的最後一份筆記，記錄了傭兵對過去生活的懷念，以及開啟新生活的計劃，讀來使人充滿希望。",
  str_dispatch_book_chapterdes_4000_1 = "真理，無法被看到；\n信徒，你被看到了。\n召喚，知曉其所在；\n拒絕，你無法做到。",
  str_dispatch_book_chapterdes_4000_2 = "它，似乎無處不在；\n痛，於剎那間暴脹。\n它，應當無處不在；\n花，自血海中綻放。",
  str_dispatch_book_chapterdes_4000_3 = "泥濘，是真理的外衣；\n泥濘，是真理的味道；\n吞下，是真理的獲取；\n品嚐，是真理的熟悉。",
  str_dispatch_book_chapterdes_4000_4 = "那一天，必定不會到來；\n相信我，降臨就是謊言。\n死亡，已成過去；\n享樂，永不消逝；",
  str_dispatch_book_chapterdes_5000_1 = "來到紅油沙漠，就得吃點外面吃不到的！要是想吃麥〇勞還是肯〇基的，還是滾回去吧！來到紅油沙漠，就是要吃沙蟲乾！炸蟋蟀！整隻蒸駱駝！紅油仙人掌！",
  str_dispatch_book_chapterdes_5000_2 = "如果你以為這片沙漠全都是喝紅油助興的變態，那你可就大錯特錯了。有幾個人會跟胯下的動物搶東西喝啊？今天，強尼叔叔就帶你逛逛紅油沙漠最道地的「沙蟲轉轉轉」酒吧！啊？你還沒成年？那你就喝駱駝奶吧！",
  str_dispatch_book_chapterdes_5000_3 = "等等？你是個素食主義者？拜託，這不是你放棄大口駱駝肉的理由——你可以把它當成水果啊！你不說、我不說，那這駱駝肉就是一盤水果！只要你吃了，就絕對會愛上！",
  str_dispatch_book_chapterdes_5000_4 = "熱力！激辣！辣可是紅油沙漠的象徵！辣到耳朵冒煙，辣到喉嚨噴火，辣到頭殼都被蒸汽頂飛！你要是連辣都不敢吃，那你絕對忍受不了紅油沙漠的風沙。有句老話說的好：「能吃辣，才能打架。」",
  str_dispatch_book_chapterdes_5000_5 = "年輕人必須樹立遠大的理想，不說吃遍艾斯特拉，至少得吃遍紅油沙漠吧？你那麼緊張幹嘛？又不是叫你把沙漠的沙子吃乾淨！不過據我所知，沙子石頭飯也是鯊齒島的名菜……",
  str_dispatch_book_chapterdes_6000_1 = "人們常說，地面上的每一片湖泊，都是神明滴落在人間的眼淚。而這片大陸最古老也最美麗的湖泊——鏡湖，則一定是神明垂憐人世時，流下來最美的那一滴。",
  str_dispatch_book_chapterdes_6000_2 = "風脈之森雖然是一座位於北境南部的森林，卻完全不同於北境給人的寒冷印象。這裡常年氣候溫暖，四季如春。傳說，這座森林的植物與動物都在風的庇護下，無憂無慮地生活著。",
  str_dispatch_book_chapterdes_6000_3 = "雖然表面上是一片丘陵，然而根據此地原住民的傳說，綠松之地的真實面目乃是「神明的碎晶」。",
  str_dispatch_book_chapterdes_6000_4 = "位於「世界之脊」的「冬宮」，乃是一座完全由冰雪構成的宮殿，是北境女王伯利恆的居住地，也是北境的統治中心。",
  str_dispatch_book_chapterdes_7000_1 = "這是名為「黑暗降臨前」的殘頁。中斷部分有被人刻意抹去的痕跡。",
  str_dispatch_book_chapterdes_7000_2 = "研究者認為這種通俗易懂的記述並非出自古人之手，比較可能是近現代人留下的記錄。本章確實是「末日之語」當中的一冊，但人們迄今仍難以解釋本章與末日的關係。",
  str_dispatch_book_chapterdes_7000_3 = "這篇殘頁缺少前半部分的內容。研究者推斷此處的「他們」是指生活在戰爭前的人，而「我們」就是指留下這份記錄的人。",
  str_dispatch_book_chapterdes_8000_1 = "代號為「瓦爾基里」的一份實驗檔案，於北境某處深山的舊文明遺跡所發現。同時發現的大量實驗資料與檔案因不明原因損毀，已無法讀取。",
  str_dispatch_book_chapterdes_8000_2 = "一位科學家的部分手稿，從中可以發現他把自己的女兒當成實驗品的瘋狂行為。手稿發現於巴斯鎮廢墟中。",
  str_dispatch_book_chapterdes_8000_3 = "紅油沙漠附近的聚落，以及遊民流傳的幾張古老典籍殘頁。上面應該是一段作戰記錄，作戰時間、地點與敵對雙方均不詳，然而可以從中窺視那遠古文明發達的科技。",
  str_dispatch_book_chapterdes_8000_4 = "這本殘卷據說發現於舊鎮附近的廢墟，似乎是一本小說的某個篇章，又像是一部記錄，記載了有關「德古拉」的傳說。",
  str_dispatch_book_chapterdes_9000_1 = "王國召集勇士出海探索新的島嶼。「風暴」第三章講述航海隊在海上歷經風暴，少年柯林因為展現出勇氣，贏得了眾人的尊重。",
  str_dispatch_book_chapterdes_9000_2 = "航海隊打算探索七座島嶼並尋找寶物。「七座島嶼」第二章講述眾人登上第二座島嶼後，遭到飛龍襲擊，然而當他們返回第一座島嶼時，卻發現那座島消失了。",
  str_dispatch_book_chapterdes_9000_3 = "航海隊在海上遭到巨大觸手怪襲擊，勇者在混亂中落海。「海底王國」第四章講述的是勇者醒來後，發現自己進入了一座神祕的海底王國。",
  str_dispatch_book_chapterdes_9000_4 = "王國組織的討伐隊，正在想辦法討伐深海怪物。「深海怪物」第六章講述勇者一行人終於到達藏有最後一件寶物的小島。此時，深海怪物終於露出牠真正的模樣……",
  str_dispatch_book_chapterdes_10000_1 = "身為啟光人社交和生活的一部分，本節主要講述啟光人的核心信條。",
  str_dispatch_book_chapterdes_10000_2 = "身為啟光人社交和生活的一部分，本節主要講述啟光人應遵守的核心紀律。",
  str_dispatch_book_chapterdes_10000_3 = "身為啟光人社交和生活的一部分，本節主要講述啟光人應了解的社會文化。",
  str_dispatch_book_chapterdes_10000_4 = "身為啟光人社交和生活的一部分，本節主要講述啟光人應了解的行為準則。",
  str_dispatch_book_chapterdes_10000_5 = "身為啟光人社交和生活的一部分，本節主要講述啟光人必須遵守的各種條例。",
  str_dispatch_book_chapterdes_11000_1 = "那一天，少女艾達與最弱小的巨像「風行者號」乘風飛起，伴著星月上升，離開了她們一直以來生活的地方——空之山谷。外面世界的一切彷彿畫布般慢慢展開，夜空中極光流淌，為冒險畫下了夢幻的第一筆。",
  str_dispatch_book_chapterdes_11000_2 = "這些自稱「亞人」的奇怪小動物，渾身上下都是柔軟的毛，真是好摸。即使是巨像，也無法抵抗這樣的可愛攻勢！曬著暖暖的太陽，擁抱著這些毛茸茸的傢伙，可以舒舒服服地躺上一整天吧。",
  str_dispatch_book_chapterdes_11000_3 = "開滿花的巨像走到了生命的終點，他已經離開空谷太久了。曾經，他和他的導航員也像艾達與風行者一樣，懷著好奇與希望來到外面的世界。但見識外面的世界一定是正確的嗎？有時候走得太遠，連回家的方向都找不到了。",
  str_dispatch_book_chapterdes_11000_4 = "行駛在沙漠中的船隻停靠在艾達與風行者面前，神祕的光靈旅行團突然出現。風揚起地面上的細沙，原來行船並非在沙地上航行，而是沿著星海的軌跡一路前進。",
  str_dispatch_book_chapterdes_11000_5 = "艾達與風行者的足跡遍布世界各角落，但唯有一個地方留下了空白——空之山谷。或許是時候回到最初的地方了……",
  str_dispatch_book_chapterdes_12000_1 = "對明娜而言，年少時困在金河邊的日子幾乎不堪回首。那時，她的生命缺乏故事，也缺乏意義，只剩下困厄的生活本身強破她不得不忍耐。但這一切，都在商隊出現時發生轉機。",
  str_dispatch_book_chapterdes_12000_2 = "對明娜而言，年少時困在金河邊的日子幾乎不堪回首。那時，她的生命缺乏故事，也缺乏意義，只剩下困厄的生活本身強破她不得不忍耐。但這一切，都在商隊出現時發生轉機。",
  str_dispatch_book_chapterdes_12000_3 = "明娜交易商品的請求遭拒，她困窘地呆立在商隊的遮陽長廊邊，不知所措。此時，一位身穿白色鎧甲的男人出手替她解圍。明娜也得知了他的名字——夏佐。",
  str_dispatch_book_chapterdes_12000_4 = "明娜交易商品的請求遭拒，她困窘地呆立在商隊的遮陽長廊邊，不知所措。此時，一位身穿白色鎧甲的男人出手替她解圍。明娜也得知了他的名字——夏佐。",
  str_dispatch_book_chapterdes_12000_5 = "夏佐離開村莊後，仍不斷寫信給明娜。明娜對外面的世界產生無限幻想，為此，她甚至逃離村莊，想離心目中的世界更近一點。",
  str_dispatch_book_chapterdes_12000_6 = "夏佐離開村莊後，仍不斷寫信給明娜。明娜對外面的世界產生無限幻想，為此，她甚至逃離村莊，想離心目中的世界更近一點。",
  str_dispatch_book_chapterdes_12000_7 = "明娜想加入信使公會，卻遭到拒絕。等待夏佐來信，希望也落空。明娜終於決定離開這片生養自己的土地，親眼去看看外面的世界。她的第一站，便是白夜城。",
  str_dispatch_book_chapterdes_12000_8 = "明娜想加入信使公會，卻遭到拒絕。等待夏佐來信，希望也落空。明娜終於決定離開這片生養自己的土地，親眼去看看外面的世界。她的第一站，便是白夜城。",
  str_dispatch_book_chapterdes_12000_9 = "明娜欲進入白夜城時受阻，但她偶然得到另一個機會，而且免費。成功進入白夜城後，明娜四處打聽夏佐的住處，卻得知令她難以置信的消息。",
  str_dispatch_book_chapterdes_12000_10 = "明娜欲進入白夜城時受阻，但她偶然得到另一個機會，而且免費。成功進入白夜城後，明娜四處打聽夏佐的住處，卻得知令她難以置信的消息。",
  str_dispatch_book_chapterdes_12000_11 = "明娜找到夏佐留下的地址，一個接一個天翻地覆的消息向她砸來。最終，她找到自己曾經當偶像崇拜的夏佐，但一切已經物是人非。",
  str_dispatch_book_chapterdes_12000_12 = "明娜找到夏佐留下的地址，一個接一個天翻地覆的消息向她砸來。最終，她找到自己曾經當偶像崇拜的夏佐，但一切已經物是人非。",
  str_dispatch_book_chapterdes_13000_1 = "桃樂絲姐弟生活在北境的村莊，父母早逝的他們靠著幫村民打雜換取食物。長老希望他們能融入新家庭，卻被姐姐桃樂絲一口拒絕。",
  str_dispatch_book_chapterdes_13000_2 = "回家路上，桃樂絲姐弟幫助一位跌倒在雪地裡的光靈。光靈住進村莊，但是半夜的風雪壓垮了光靈的房子，於是光靈再一次向桃樂絲姐弟求助。",
  str_dispatch_book_chapterdes_13000_3 = "在長老的幫助下，陌生的金髮光靈——瑪莎住進了桃樂絲姐弟的房子。隨著相處的時間增長，三人的關係也逐漸親密起來。",
  str_dispatch_book_chapterdes_13000_4 = "瑪莎熱衷料理，為此，她甚至想辦法取得鹽。桃樂絲聽說瑪莎的方法後，萌生了親自實驗的想法。",
  str_dispatch_book_chapterdes_13000_5 = "瑪莎為桃樂絲姐弟料理晚餐。從與弟弟克魯斯的交談中，瑪莎得知了桃樂絲的心結，不過這不是最重要的——最重要的是，天已經黑了，但桃樂絲沒有回家。",
  str_dispatch_book_chapterdes_13000_6 = "桃樂絲按照瑪莎所述找到了鹹水湖，卻遇上暴風雪未能及時返家，試圖在野外躲避風雪的她不幸遇到覓食的狼群。",
  str_dispatch_book_chapterdes_13000_7 = "桃樂絲使用光能術阻擋狼群進攻，卻依然身陷險境，千鈞一髮之際，有人凍結了撲上來的狼，拯救她脫離險境。",
  str_dispatch_book_chapterdes_13000_8 = "北境的新年來臨，瑪莎與桃樂絲姐弟一起度過新年。在村莊的聚會上，溫情無聲地滋長。",
  str_dispatch_book_chapterdes_13000_9 = "村裡又來了陌生人。瑪莎的反常舉動讓桃樂絲篤定：對方一定是為了瑪莎而來。即使桃樂絲拚命追問，瑪莎依舊拒絕說出真相。",
  str_dispatch_book_chapterdes_13000_10 = "長老組織了搜救隊，桃樂絲想偷偷混入，卻被瑪莎攔住。掙扎之間，桃樂絲脫口說出傷人的話。",
  str_dispatch_book_chapterdes_13000_11 = "瑪莎從長老那得知桃樂絲姐弟失去父母的原因，這讓她下定決心離開北境。如果留在桃樂絲姐弟身邊，她無法承受愧疚的重量。",
  str_dispatch_book_chapterdes_13000_12 = "瑪莎準備離開村莊，卻被桃樂絲攔下。桃樂絲告訴瑪莎，她不介意瑪莎的過去，也無意改變她要離開的決定，但是桃樂絲希望瑪莎有一天能回到北境。",
  str_dispatch_book_chapterdes_14000_1 = "在紅油沙漠中，技術員羅砂非常苦惱於零件的缺失。她在廣告單上發現了M&M二手零件店，種類齊全，價格公道。因此，她寫下第一封訂購信，並得到了滿意的答覆。",
  str_dispatch_book_chapterdes_14000_2 = "幾經輾轉，羅砂才收到訂購的零件。因此，她決定以後透過信使公會寄出訂購信。這次，回信是由 M&M 零件店店主的女兒米妮執筆。",
  str_dispatch_book_chapterdes_14000_3 = "為了適應紅油沙漠特殊的地理環境與氣候，羅砂需要再次改裝氣墊車。信中，她揭露了自己的真實身分——啟光叛逃的探索隊隊員。",
  str_dispatch_book_chapterdes_14000_4 = "店主馬克斯同意讓羅砂賒帳。而米妮對羅砂寄來的氣墊車改裝設計圖非常感興趣，她甚至想根據羅砂的設計圖製作引擎。",
  str_dispatch_book_chapterdes_14000_5 = "羅砂所處的車隊與一幫剽匪展開火拼。事後，她得到了大筆資金，得以支付上次的欠債。同時，她還收留了一名女孩莎莫，莎莫帶她找到不少古代科技造物。",
  str_dispatch_book_chapterdes_14000_6 = "羅砂希望零件店幫忙找一些能拆解古代科技的儀器，但這對零件店來說顯然是個難題。不過米妮完全不理會父親生意上遇到的難題，她參加了白夜城的建城日慶典，並寄給羅砂不少禮物。",
  str_dispatch_book_chapterdes_14000_7 = "羅砂打算為一名喜愛音樂的隊員準備禮物，她想改裝一把吉他。此外，羅砂也感謝米妮寄來的零食，她實在太不適應紅油沙漠食物的口味了。",
  str_dispatch_book_chapterdes_14000_8 = "車隊搶劫了啟光運輸隊，事態失控，雙方都死傷慘重。羅砂為此失去了雙腿，不過，更令她痛苦的是——對曾經的同僚開槍。",
  str_dispatch_book_chapterdes_14000_9 = "米妮即將步入婚姻，她寄了喜帖給羅砂。在信中，米妮並未對婚姻生活懷抱不切實際的幻想，她只是表達了自己對平淡成長之路的厭倦。",
  str_dispatch_book_chapterdes_14000_10 = "羅砂由於身體因素，無法前往米妮的婚禮。不過，她為她製作了一束鋼鐵玫瑰，玫瑰將帶著她的祝福一起送到米妮手中。",
  str_dispatch_book_chapterdes_14000_11 = "這次寫信的人換成了莎莫，那位曾帶著羅砂尋找古代科技造物的小女孩。在那之後，她便成為羅砂的助手。莎莫為馬克斯父女帶來了一則噩耗。",
  str_dispatch_book_chapterdes_14000_12 = "米妮回顧了自己、父親與羅砂的通信經歷，她認為羅砂是她結識過最了不起、最超乎想像的人物。在寫這封信之前，米妮已經聯繫了商隊，她將前往紅油沙漠，送自己的朋友最後一程。",
  str_dispatch_book_chapterdes_15000_1 = "朋友與「我」在影鎮的百人池觀看一場格鬥，雙方看起來實力懸殊，而弱勢的一方居然是一家商會的成員。「我」極為困惑：商會成員與人死鬥，首領不可能置之不理。",
  str_dispatch_book_chapterdes_15000_2 = "未出預料，小個子果然在格鬥中落了下風。正當看客們為他擔憂時，中場休息的哨聲吹響了，小個子撿回了一條命。不過，觀眾席上，赤汞夫人所坐的那一隅黑暗中，發生了一些令人在意的騷動。",
  str_dispatch_book_chapterdes_15000_3 = "觀眾席上的俘虜似乎給了小個子無形的激勵。小個子贏得了這場格鬥的勝利，但是，在商會首領赤汞夫人面前，他的命運依舊沒有明朗。",
  str_dispatch_book_chapterdes_15000_4 = "結束了百人池之旅後，「我」迫不及待地向朋友請教關於赤汞夫人的事。坊間關於赤汞夫人的流言很多，但確為實情的很少，不過即便如此，她的身世和在婚姻上的果決，也足以讓她成為傳奇了。",
  str_dispatch_book_chapterdes_15000_5 = "「我」得到了一次進入白夜城的機會。在中轉區的旅店等待通行文件審批完成時，「我」遇見了一位意想不到的人物。",
  str_dispatch_book_chapterdes_15000_6 = "「我」對赤汞夫人心懷恐懼，但恐懼終究擋不住好奇。終於，「我」等到了一個極好的機會，讓「我」能夠裝作不認識她的樣子，上前與她搭話。",
  str_dispatch_book_chapterdes_15000_7 = "「我」終於成功與赤汞夫人搭上了話。在聊天的過程中，她講到了自己出現在中轉區的原因——事關她的夢境，和對好友的懷念。",
  str_dispatch_book_chapterdes_15000_8 = "第二天，「我」醒來後，發現赤汞夫人已經離開了，根據旅店主人的說法，白夜城中來了浮空艇，接走了她。「我」十分悵惘，回到自己的房間，卻收到了一份「驚喜」。",
  str_dispatch_book_chapterdes_15000_9 = "入城審批遲遲未發放，「我」非常焦急，四處打聽白夜城中的消息，卻聽說白夜城中發生了一起駭人聽聞的謀殺案。進入白夜城後，「我」迫不及待地想知道謀殺案的詳情。",
  str_dispatch_book_chapterdes_15000_10 = "「我」在影鎮遇見了赤汞夫人原先的手下，不禁向他們打聽起赤汞夫人的消息。「我」本以為會聽到預想中的噩耗，但顯然現實情況可能並不是「我」想的那樣。",
  str_dispatch_book_chapterdes_15000_11 = "《赤汞夫人》第二版的編輯在後記中考證了影鎮的武器走私商會、白夜城的謀殺案與審判，並分享給讀者。",
  str_dispatch_book_chapterdes_15000_12 = "這位編輯同樣也在後記中分享了自己對「赤汞夫人」一角的看法。他認為讀者無須去找出赤汞夫人的原型，畢竟那並不是伊馮女士寫作的目的所在。",
  str_dispatch_book_chaptercont_1000_1 = "光之神的啟示，便是賜予光靈生命與希望，並將必成之事指示於光靈，差遣使者，曉諭世上光靈。光靈將神之道，並白夜之見證，證明自身所見所聞。念這歌中所預言的，與那些聽見又遵守這歌中所記載的，便都是有信的、有念的，必將有福。\n白夜至上的七所神殿，與在今昔、在以後、在永恆的光之神與寶座前的聖徒，且那誠實作見證的人們，將會從永晝與永夜的漩渦中倖存，得以見證、擊敗那死後復活的惡魔、那來自遠古的天災、那千萬年的罪惡。\n看那白夜之上的惡魔，將駕雲降臨於大陸。地上的眾目將看見牠，因牠哭嚎、因牠刺疼、因牠血淚。因為眾目得知了真實。\n光之神將說，我是根源的、我是神祕的、我又是可知的，我造就了那古老的文明，也毀滅了那古老的文明。我是光靈的神，也是光靈的兄弟，與光靈同在這患難者的國度中，忍耐、煎熬，一同有份，並見證為神之道，為聖徒見證，曾在那名喚世界的海島上。\n降臨當日，諸人被聖徒感動，便聽見神之使者在遠方有大聲如吹號說：「你所看見的，當寫在書上，送予拉赫、薩呂斯、達摩克利、格蘭迪、薩丁尼亞、迦南、特洛伊那七所神殿。」\n光之神翱翔於天，與聖徒說話。諸光靈轉身便見七盞金燭臺。燭臺中間，有一位好似光靈之人：身穿長衣，直垂到腳，胸束金帶；鬚髮潔白，如白羊毛、如雪；眼目如同火焰，雙腳彷彿爐中鍛鍊光明的銅，聲音如同眾水。那人右手拿著光芒，左手出現一把兩刃利劍，面貌如同烈日放光。\n諸光靈見狀，即仆倒於面前，彷若死去一般。那人用右手按著諸光靈的頭說：不要懼怕，我是先知，亦是末裔，看似存活，彷彿曾經死去現在又復活，但我永恆不滅。我拿著死亡和陰間的鑰匙，先給予你，所以你要把所看見的和現在的事，並將來必成的事，都寫出來。\n是為戰禍。",
  str_dispatch_book_chaptercont_1000_2 = "啟示降臨之時，那使者揭開第一印，便看見一匹白馬，那馬上有一名拿弓的光靈，戴著血色冠冕，徘徊於天，灑落箭雨。\n揭開第二印的時候，就另有一匹紅馬出來。惡魔將大刀賜予那騎馬的光靈，那光靈便從地上奪去太平，使人彼此相殺。\n揭開第三印的時候，見有一匹黑馬，騎在馬上的光靈手持天平，道：「一樁罪孽、一樁善舉、一條生命、一次審判。」\n揭開第四印的時候，見有一匹灰馬，騎在馬上是一名死去的光靈，冥界隨之而來，那光靈灑下刀劍、飢荒、瘟疫、暗鬼，殺害地上之人。\n揭開第五印的時候，我看見眾多白衣人，為作見證，記下那被殺之人的靈魂。\n揭開第六印的時候，大地撼動、豔陽轉黑如深淵、滿月鉅變紅似血。天上有星辰墜落於地，如同樹被大風搖動，落下未熟的果子。蒼穹挪移，彷若書被捲起；地上的君王、臣宰、將軍、富戶、壯士，和一切為奴的、自主的都藏在山洞和岩石穴裡。因為光之神與惡魔的大日到了，誰能站得住。\n此後，有那一位光靈，從日出之地上來，拿著神印，大聲喊道：「蒼穹、地、海、樹木，你們不可傷害神之眾僕，等我們印了額。」\n使者揭開第七印的時候，世界寂靜。使者召喚一名光靈，賜予那光靈七支號角。光靈便將號角一一吹起。\n第一次吹號，便有冰雹與火摻著血打在地上，一切的青草枯黃燒毀；\n第二次吹號，有火焰大山扔擲海中，海水變成一片濁血，所有生物死去；\n第三次吹號，有燃燒的隕星，猶如火把從天而降，毀滅江河、水泉；\n第四次吹號，日月星辰皆受擊打，失去光芒，無邊無盡的黑夜降臨；\n第五次吹號，地上陷出無底巨坑，又冒出煙與火焰，無數鐵甲蝗蟲從煙中盡出，欲傷害額上沒有神印的人。\n第六次吹號，便有聲音說：「釋放那些禁錮在過去的魂靈。」便有三億軍馬出現，騎馬的胸前有甲，燃燒著紫色火焰，散發著硫磺氣味；那馬頭好似獅子，有火、有煙、有硫磺，全從馬的口中噴出。「去殺死那些行凶殺、邪術、奸佞、偷竊之事，且絲毫不悔之人。」\n第七次吹號，有一位光靈出現，頭顱如太陽，雙腳似火柱，右腳踏海、左腳踏地，大聲呼喊，彷彿獅子吼叫。呼畢，神的使者便說一切告終，佳音已賜予神的僕人：\n「無論大小貧福、自主的、為奴的，凡有印的，皆可活至永永遠遠；凡有印的，若欺瞞，便溺於戰禍；凡有印的，皆入此門，有那火與劍的考驗。」\n是為審判。",
  str_dispatch_book_chaptercont_1000_3 = "地上的戰禍繼續，有印的已入門，見到神的使者。那使者大聲說：「施行審判的時候已經到了。凡有印的，應當敬拜那創造天地海和眾水泉源的。」\n遠方有一聲巨響，萬民沉溺的荒淫都市傾倒。\n又有一聲高喊，便有人拜野獸之像，於是那些人在額上、或在手上，也便有了印記，也便入這門，卻受神之使者的怒喝：「拜偶像者，要在火與硫磺之中受苦。」那些人便承受痛苦，直至永永遠遠。\n又有聲音自天上說：「要寫下，從今以後，凡有印的人有福了，即使死亡。諸人說，是的，息了自己的勞苦，作工的果效也隨著自己。」\n又有一片白雲，雲上坐著一位光靈，戴著黃金冠冕，手裡拿著鋒利鐮刀，大聲喊道：「收割之時已到，地上的莊稼已經熟透，樹的果子也已熟透。」\n所以在一天之內，災殃一齊來到地上，就是死亡、悲哀、飢荒、瘟疫、戰爭，因為罪孽已熟透。\n地上的君王，看見燒他的煙，就必為他哭泣哀號。素來與他一同奢靡的，也受他所獲得的災殃，與那龐大的都市，一同在煙中哭泣哀號。\n地上的客商，也都為他哭泣悲哀，因為沒有人再買他們的貨物了。這貨物就是金、銀、寶石、綢緞、各樣香木、器皿、香料、油膏、乳品、酒、麵、麥、牛、羊、車、馬，以及奴僕、人口。一切的珍饈美味和華美的物件，悉數毀滅。販賣這些貨物，藉它發了財的客商，哭泣悲哀，道：「這富厚歸於無有，荒蕪是我們的財富。」\n地上的凡人，那彈琴、作樂、吹奏、跳舞的，不能再聽見、不能再看見，就像失明失聰失智的愚人。燈光失去照耀，喜悅失去歡笑，橫行的邪術失去迷惑，僅有虛無殘存。\n而那有印的，將在天上說：「救恩、榮耀、權能，都屬乎光之神。審判是公義的。伸冤、懲戒，是公義的。讚美我們的神，進入那門，直至盡頭。」\n是為永恆。",
  str_dispatch_book_chaptercont_1000_4 = "地上的煙、邪佞、罪惡，無法進入此門。那門中有聲音說：「世上的國，成了神的國，直至永永遠遠。」\n凡有印的，將聽見使者的聲音說：「讚美光之神，因為作主了。」\n於是，凡有印的，便將歡喜快樂，因為這榮耀歸給諸人。得穿光明潔白的衣裳，這衣裳便是諸人所行的義。\n使者說：「要寫上，凡被印了額的人有福了，這是神真實的話。」\n諸人便俯伏在使者腳前，欲行拜禮。使者說：「千萬不可，我們同是作僕人的，你們要敬拜神，因為預言中的靈意，乃是為光之神作見證。」\n「一位光靈從天降下，手裡拿著無底坑的鑰匙，和一條巨鍊。那光靈捉住那些惡魔，將其捆綁，扔入無底坑裡，用鑰匙封印，使其不得再迷惑眾人。直至有印的失去印，便會暫時釋放惡魔，重返世間。」\n使者又揮舞著權柄，做光之神的見證，並為那些冤屈被斬者的靈魂，和那沒有拜過獸像，也沒有在額上和手上受過其印記之人的靈魂，一併復活了，與諸人一同入門喜樂。這是頭一次的復活，其餘之人還沒有復活，直至一千個一千年結束。\n在第一次復活有份的，祝福了、純潔了、喜悅了。第二次的死不會到來，必作神和使者的祭司，直至一千個一千年結束。\n而這時，惡魔必從無底坑裡被釋放，出來迷惑地上四方諸人，叫其聚集爭戰。其信徒多如海沙，遍佈全地，圍住有印的人的營，與蒙恩典的城。而光之神便令火從天而降，將其燒滅。那迷惑人的魔鬼，將被扔進硫磺的火湖，就是野獸所在的地方，必需晝夜承受苦痛，直至永永遠遠。\n又有那白色的王座，前面站滿了死了的人，無論大小。王座上的案卷展開，死了的人都憑著這些案卷所記載的，照其所行接受審判。於是，海交出其中的死人，地也交出其中的死人，陰間也交出其中的死人，都照各人所行接受審判。而海、地與陰間也被扔進火湖，這就是第二次的死。\n又看見一個新天新地，因為先前的天地已經過去了。新城由光之神那裡從天而降，預備好了。有聲音說：「看哪，神的帳幕在人間，要與人同住，神要作人的子民，神要親自與人同在，作人的神。」\n「神要擦去人一切的眼淚，不再有死亡，也不再有悲哀、哭號、疼痛，因為以前的事都過去了。」\n「看哪，一切都更新了。要寫上。因這些話是可信的，是真實的。」\n「事情都成了，我們是初、是終。得勝的，必承受這些為業，城中有神的榮耀，城的光輝如同極貴的寶石，如同明淨的玻璃。城門白晝總不關閉，在那裡沒有黑夜。凡不潔淨的，且行為可憎與虛謊之事的，總不得進那城。」\n「城內街道當中一道生命之水的河，明亮如水晶，在河這邊與那邊有樹，結果可醫治萬民，以後再無詛咒。」\n於是，使者說：「不可封了這書上的預言，因為日期將近。」\n是為啟示。",
  str_dispatch_book_chaptercont_2000_1 = "距今一千餘年前，漂泊的亞人族在艾斯特拉大陸發現了這處洞穴。當時僅當作歇腳之地的亞人族，並不知道此處將成為亞人族重現繁榮的偉大聚落。\n接下來數十年，隨著對洞穴不斷探索，亞人族在這裡找到了大量的舊文明設備與古老技術。種種跡象顯示，舊文明的人類似乎曾在此處，對這個巨大洞穴進行某種特殊實驗。亞人族還發現，生存在洞穴內的亞人，會比漂泊在外的亞人擁有更強健的體魄，對光能的感知也更加敏銳。奇妙的是，這種變化僅發生在亞人族身上，對其他慕名而來的光靈和空裔來說，這裡只是一處擁有獨特生態系統、四季如春的舒適居住地。正因為這個特點，亞人族便將此洞穴當作上天賜予的福地，即應許之地。他們為自己巨大的洞穴城市命名為「祕境」。\n經過了十餘代人的辛苦耕耘，本來只有陳舊上古設施的洞穴，如今是繁榮的亞人族聚居點，也成為了亞人族的政治中心與精神家園。亞人族在此處積極研發科技、工業與農業，力圖恢復亞人族昔日的輝煌——直到數百年後，暗鬼到來。",
  str_dispatch_book_chaptercont_2000_2 = "換氣系統幾乎停擺，照明系統也已損壞。洞穴裡的硝煙難以散去，卻也無法掩蓋濃厚的血腥味。那些可惡的怪物就在煙霧和黑暗中扭動著軀體，肆意殘殺手無寸鐵的平民。牠們追逐著每一位我們的同胞，追上後毫不猶豫地殺死他們，如發狂的野獸般，毫無人性。\n有人試圖反抗，從幾隻暗鬼手中拯救了一個孩子，然而兩人還來不及逃走，就被隨後湧上來的無數暗鬼淹沒。前線組織防衛的士兵，在幾個小時前就失去了聯繫……恐怕也是凶多吉少。我們唯一的希望……就是那些沿地下管道逃離的人們……但願……但願我們的孩子能逃出這裡。我永遠忘不了那一幕，被建築物碎片壓住、嘶聲哭喊的同胞，他們靈動的雙眼變得黯淡無光，接著被當作垃圾一樣堆成小山。\n昔日繁榮的福地，正在變成吞噬一切，充滿哭號與火焰的地獄。那些把這裡變成地獄的惡魔，所有的罪孽……暗鬼必須付出代價！！\n——啟光探索隊深入祕境探索時找到的筆記。",
  str_dispatch_book_chaptercont_2000_3 = "根據長老所說，我們應該是最後一批進入洞穴的亞人了。說是長老，他們也只是一群年輕的亞人。年長者早已在抵抗暗鬼入侵時就戰死了。\n雖然在接到同胞的求救信時，我們便已做好心理準備，然而當見到昔日的高大洞穴，如今變為一片掩埋在碎石殘渣之下的廢墟，以及堆積如山的同胞屍骸後，我們仍然無法承受這末日般光景的衝擊。幸好長老安慰了我們，即使他們的年紀似乎比我們還小……\n暗鬼！牠們必須付出代價！一名亞人族的死亡，就要有一百隻暗鬼陪葬。每名亞人族都無法忘記那些同胞們死時的慘狀，但失去了洞穴、失去了家園的亞人族還有什麼呢？我們亞人族在大陸上還有其他的棲身之所嗎？不如就讓我們與暗鬼戰鬥到最後一刻，就像祕境洞穴的同胞們——戰士死了換平民上，成人死了換孩子上。如今留守在祕境洞穴的同胞犧牲了，該輪到我們這些返鄉的亞人了。那就讓敵人的鮮血作為我們的葬衣，暗鬼的屍體作為我們的墳塚！就讓我們守衛故土到最後一刻吧。\n——某亞人與光靈之混血後代的日記。",
  str_dispatch_book_chaptercont_2000_4 = "想到那已然乾枯的骸骨，想到那位勇敢的啟光士兵直到戰死前的最後一刻，也沒鬆開手中的武器——當時的我產生了放棄這次探索的念頭。\n距亞人族覆滅已經過了一百多年，暗鬼已經成為祕境洞穴的主人，就連我們這些「外人」，也將亞人族曾經的家園改稱為「祕境」或「大祕境」。而在滅亡亞人族後，暗鬼卻沒有襲擊其他城邦，似乎棲居於祕境已經足矣。沒有人知道牠們在做什麼。\n於是，就輪到我們這些人出場了。\n起初，啟光探索隊成員各個挺身而出，都想把祕境裡的暗鬼揍個落花流水——他們打從心底是為啟光聯邦的安全著想。然而，現實很快就教育了所有啟光人。許多探索隊員不是被暗鬼所殺，就是迷失於祕境當中，甚至還有整支探索隊下落不明！反對的聲浪開始增強，而啟光領袖卻一意孤行，強行建立探索隊，命令探索隊繼續前往祕境，為的就是那幾個字：「查明真相」。而這幾個字背後，是多少條生命的消逝，與多少親人家屬的悲傷。\n終於，逃兵出現了，而我們就是其中之一。我們拋棄了死去的隊友，無視上級的命令，逃離了那祕境。想必我們在啟光聯邦的公開記錄中一律為「失蹤」，而內部記錄則是「逃兵」吧。我們的親屬會怎麼樣呢？會遭到懲罰嗎？我們恐怕不得而知，因為我們已經永遠無法返回啟光聯邦，只能在這大沙漠中度過餘生。\n雖然偶爾會思念家鄉與親人，然而比起對生存的渴望，這都不算什麼。畢竟，我們還活著，還能在這大沙漠中四處遊蕩。我想，有時候放棄也是一種美德。如果我們像當年的亞人族那樣眷念故鄉，那麼就只剩下兩個結局：探索祕境，為暗鬼所殺；或是違令返回，軍法處置——都是死路一條。\n最近，一直沒有啟光聯邦探索祕境的消息傳來，他們大概是放棄了，其他城邦也一直沒有任何動靜。看來，對整個大陸來說，祕境已經是​​一片失落的土地，就讓暗鬼佔據那裡吧。而這一切，與我們沒有任何關係了。祕境、啟光、亞人、暗鬼，永別了。\n——根據某位不願透露姓名的紅油扳手初代成員的口述整理而成。",
  str_dispatch_book_chaptercont_3000_1 = "這次我們的任務是前往〇〇〇〇，將藏在裡面的叛徒全數殲滅。錢給得很多，希望這一票能讓我多賺一點。裝備和食物消耗光想就頭痛，但不存錢的話，就永遠沒辦法創立自己的小隊，我們幾個只能繼續像現在一樣，跟著別的隊伍混日子。所以一定要存錢。小隊名稱我還沒想好，反正不急。\n〇〇〇〇的地形很複雜，按照任務指示，我們要跟另外一隊傭兵潛入一條地下通道。但通道裡狀況不明，而且不能使用閃光彈，因為這次是祕密潛入。潛入前我有點擔心，如果通道裡有什麼埋伏或陷阱，我們就不妙了。但幸好最後平安無事，當時還有一隻蜥蜴從我腳下竄過去。\n從通道裡鑽出來之後，就到了〇〇〇〇的腹地，我們走了一條荒無人煙的小路，包抄到他們的藏匿點後方。從我們那個方向看，藏匿點真的很亂，但不是因為戰鬥，比較像是他們來不及打掃，或根本不願意打掃。四處都散落著垃圾、舊衣物，還有吃剩的食物。他們好像根本沒有任何防備。\n按照預定計劃，我們輕而易舉便徹底剿滅了他們，但是好像浪費太多彈藥了。當時我們丟了五六個炸藥包進去，那可是我們自己配的炸藥啊，用一包就少一包了。但隊友都說這一票報酬真的很高，如果能順利完成任務，拿到的錢夠我們買優質的炸藥了，真正軍用的那種。我還是覺得他們有點太樂觀了，雖然我也希望能多賺一點錢。\n對了，我們自己的小隊名稱就叫「炸藥小隊」吧！要像炸藥一樣驚天動地，來一票大的！砰！",
  str_dispatch_book_chaptercont_3000_2 = "上一次的報酬拿到手了，比我預期得少太多了。但是沒辦法，我們去雇主那裡討薪時遇到暗鬼襲擊，而雇主被暗鬼吃了。我們只好躲起來，等暗鬼走後，我們搜刮了雇主剩下的半個屍體，還有附近的廢墟，最後才找到了一點點錢，就這麼多了。看在雇主已經被吃了的份上，我也無法苛求更多了。\n我們還討論了這次要接哪份任務。真沒想到，竟然還有我們挑任務的一天。一共有兩夥人派來任務，一個是由〇〇〇派來，去暗殺〇〇的成員；一個是由〇〇派來，去暗殺〇〇〇的成員。我們都覺得很有意思——〇〇〇和〇〇都不約而同找上了我們，所以現在是由我們來決定要幹掉〇〇〇還是〇〇了。\n我想選擇為〇〇〇幹掉〇〇，因為我不喜歡〇〇那個地方，滿口都是「平等」、「公平」、「紀律」，用這些當幌子讓人替他們賣命。如果真的平等、公平的話，我們為什麼不能進入地底避難？他們那些資源又是哪裡來的，憑什麼不能分給我們一點？還有他們的老大，如果真的平等、公平、有紀律的話，為什麼不跟普通的士兵穿一樣的衣服，用一樣的武器，住同一間房子？ \n但另一個隊友認為要幫〇〇〇幹掉〇〇很困難，畢竟〇〇的防備相當森嚴。但話說回來，要說難，難道幫〇〇幹掉〇〇〇就很輕鬆嗎？〇〇〇可是在〇〇〇那種地方啊！\n算了，隨便哪個任務都好，他們出錢、我們出命，不就是這樣嗎？為了創立自己的小隊，怎麼努力都不為過。不過，真要選的話，我是不想為打著「平等」、「公平」、「紀律」這種虛偽口號的〇〇賣命。",
  str_dispatch_book_chaptercont_3000_3 = "不管是替〇〇〇幹掉〇〇的成員，還是幫〇〇幹掉〇〇〇的成員，我們都沒答應。經過眾人討論，我們一致認為不管是〇〇〇和〇〇，防守都相當森嚴，想要打進去，起碼要有破城錘或是超級投石機才行。像我們這種窮得要死的傭兵，子彈都不知道要怎麼弄來，大部分時間都只能拿刀砍，這種困難的任務根本做不來。看著錢白白溜走可真是難受啊。\n因為放棄了兩項大任務，我們的資金出現了一點問題。最近連吃飯都有困難，更別說什麼自己創立小隊了。幸好我們找到了一些簡單的零工，包三餐、住宿，所以暫時不愁生計了。但隊友都覺得幫別人打掃房間和院子很難堪，不太開心。但是啊、但是，我竟然覺得，這比當傭兵到處打打殺殺好多了！身為傭兵，我是不是不太稱職啊？\n打掃房間的時候，房間主人不在，但我覺得這可能是位可愛小女孩的房間。床軟軟的，鋪著粉紅色的床單，床上還有一隻絨毛玩具熊。小熊有一邊耳朵破了，打掃完房間無聊，我就幫它把耳朵縫好了。那時候我更覺得自己不像傭兵，竟然連縫紉都這麼熟練。\n但話說回來，我跟隊友的縫紉技術都滿好的，畢竟身為傭兵打打殺殺，衣服總是很容易破，我們買不起新衣服，只好自己縫，長期下來就越來越熟練了。嗯，如果不當傭兵，搞不好我們可以組個裁縫小隊什麼的，或許比當傭兵賺得多，而且還更安全呢。\n十二月",
  str_dispatch_book_chaptercont_3000_4 = "自從不當傭兵以後，已經好久沒有寫筆記了啊。再次翻開的感覺真是令人懷念。\n不過我很高興自己不再當傭兵了。我果然不太適合打仗，沒辦法完成那些艱難的任務，也沒辦法弄到充足的彈藥。想要和大家一起成立一個自己的傭兵小隊，但是始終沒存夠錢。最後，我們乾脆去幫〇〇〇〇〇打掃房間賺錢了。真是丟臉呢。\n雖然以傭兵的身分去打掃房間有點丟臉，但我們做了一陣子之後，才發現包吃包住的生活原來這麼美好。我還順便縫好了一隻絨毛玩具熊，結果被〇〇〇〇〇發現我的縫紉技術不錯。我驕傲地告訴〇〇〇〇〇，我們幾個都很擅長縫衣服。那時的我心裡充滿了自豪，比完成任何艱難的傭兵任務還要驕傲。\n結果，誰能想到呢？〇〇〇〇〇看中了我們的縫紉手藝，請我們一起開了一家裁縫店。現在，我們不再是流浪的傭兵，而是〇〇〇〇〇金牌裁縫店的一份子了。店的名字也很響亮，叫做「炸藥裁縫店」，這本來是我們替自己的傭兵小隊準備的名字，但用在裁縫店也很適合。\n而且啊，我們「炸藥裁縫店」生意真的很好。〇〇〇和〇〇的人都來找我們縫衣服。我還是不喜歡〇〇，所以幫他們縫衣服的時候，我總是故意把鈕釦縫得很緊很緊，讓他們要很用力才能扣起來。但沒想到，〇〇的人就喜歡這種緊繃的釦子，說可以勒緊士兵的肚皮。我就說，什麼平等公平紀律嘛？〇〇天天講這些，結果士兵的肚子還是那麼大。要是沒有門路，怎麼可能把肚子吃得那麼肥？\n不管怎樣，在裁縫店縫縫補補的生活，比當傭兵好多了。我和隊友都是這麼想的。有一位隊友已經準備存錢結婚了，我也在考慮建立自己的家庭。我們還打算開發自己的軍服品牌，名字當然也叫「炸藥軍服」。早晚有一天，我們要讓〇〇〇和〇〇都穿上我們的軍服。\n就寫到這吧，有空的話，我還會繼續寫筆記的。不過裁縫店真的很忙呢。哈哈，越忙越好，越忙越賺錢！",
  str_dispatch_book_chaptercont_4000_1 = "文：\n她說，真理是無法用眼睛看到的。但真理擁有眼睛，真理可以看到我。真理看到我時，我便會聽到真理的召喚，知曉真理所在。\n不，我拒絕她的真理。她是邪惡的化身，她的笑容比暗鬼還要猙獰，她的美貌是世上最可怕的惡。\n她說，我不會拒絕她，因為我不會拒絕真理。她跳起了舞，她的紅色裙子和她一起跳舞。那身裙子很特別，像水一樣流動。她轉了個身，紅色裙子就和她一起轉，包圍著她，又圍向我。\n不，我拒絕她的真理，再一次拒絕。紅色裙子彷彿活物，會自己流動，會滴在地上，會黏在皮膚上。她轉著圈，她的裙子就像雪一樣散開了，一片一片落下來，落在我的身上，落在我的唇邊。我聞到奇怪的氣味，像我身體裡流動的血。\n她說，這是她的款待，希望我好好品嚐。她的睫毛似垂簾，她的聲音如天籟。她正看著我。\n不，我拒絕她的真理，再一次，再一次拒絕。血從她的身上湧出來，血織成了襯衣，血織成了長裙，血織成了長袍和紅毯，血織成了紅色的王冠。\n她還在看著我，她的每隻眼睛都在看著我，她身上的眼睛看著我，她手中的眼睛看著我，她胸前的眼睛看著我，她膝上的眼睛看著我，她身後的眼睛看著我，她頭頂上的眼睛看著我，她背後的眼睛看著我。\n她看到我。我被她看到了。我被她注視著，我被真理注視著。\n不，我拒絕她的真理，再一次，再一次，再一次拒絕。但我的拒絕沒有意義，她用她所有的眼睛看著我，我的身上長出了眼睛看著我，我的雙手長出了眼睛看著我，我的後背長出了眼睛看著我，我的頭頂長出了眼睛看著我。真理在我身上長出了眼睛，從此之後，無時無刻，無論我身處何地，真理都在看著我。\n真理從我身上生長出來，在我身上看著我。\n她是這樣說的。",
  str_dispatch_book_chaptercont_4000_2 = "真理無處不在。在奔流的河水，在青翠的草地，在陰暗的天空，在無盡的長夜。\n在樹木的枝芽，在花果的種子，在泥濘的小路，在乾涸的瀑布。\n在空氣，在眼前，在皮膚上，在腳底下。隨著呼吸進入肺裡，隨著光線映在眼底，隨著行走留在身後，拂過身體。\n在唇邊，在齒尖，在口中，在咽喉，在胃裡，被胃液消化，被黏膜吸收，融入血液。\n隨著神經傳遍身體四周。傳遞到肝、傳遞到膽，傳遞到小腸、大腸、胰臟、脾腎。傳遞到股骨、脛骨、腳踝、腳趾。\n像小腳趾撞到桌角的疼痛。\n隨著神經傳遞到身體中央，傳遞到心臟，傳遞到氣管，傳遞到舌根、鼻腔、眼底、腦髓、頭頂。傳遞到頭骨、頸椎、肩胛、手肘、手腕、指尖。\n像指甲整片揭開的疼痛。\n隨著神經傳遞到身體的最深處。傳遞到骨髓、傳遞到臍帶，傳遞到腹腔的黑暗中，傳遞到未出世的嬰兒顱內。幼苗在嬰兒腦海中成長，受嬰兒思想滋養，綻放出美麗花朵。每一瓣花瓣都滴著聖潔的顏色。\n聖潔的思想由此綻開，四分五裂。嬰兒帶著聖潔來到世上，嬰兒降臨之地是無盡的荒原，嬰兒啼哭之時，荒原的每一寸土地都長出了花苞，嬰兒的淚水染紅荒原的每一寸土地，每一枝花苞都染上了嬰兒的聖潔。嬰兒繼續啼哭，天上也下起了聖潔的雨。花朵自嬰兒身邊逐枝綻放，荒原成為聖潔的花海。\n真理無處不在。",
  str_dispatch_book_chaptercont_4000_3 = "該如何描述這種感覺呢？\n黏稠、泥濘、混成一團。把手伸進去，觸感光滑，滿是黏液，又能摸到其中混雜的團狀物質。可以捏，可以揉搓，可以攪拌。不能和它融為一體，但卻被它緊實地抓著，它的溫度沿著手蔓延至肩膀。\n它是活物。\n肉質鮮嫩，營養豐富，可以用多種手段烹調，蒸煮炒炸皆宜，燒烤不錯，熬湯更佳。買來的時候，介紹上是這麼寫的。趁活著的時候下鍋，味道最鮮美。\n但是該怎麼切開它呢？每一刀切下去，都被它黏稠而光滑的身體巧妙地避開了。刀刃貼著黏液滑到一邊。按住它，瞄準其中混雜的團狀物質切下去，表面包裹的黏液，像一張柔軟的嘴包住了刀刃，讓刀切不下去。\n水沸了，來不及了。整個放進去吧。順著鍋子滑進沸水時，似乎是錯覺，它好像在笑。它的牙齒參差不齊，身體扭動著，黏液和沸水瞬間融為一體。\n它發出了聲音，它的確在笑，它在沸騰的水中放聲大笑，它在沸騰的水中看著我放聲大笑。它在嘲笑。有毒的蒸汽從水面升起，連蒸汽也帶著黏稠的觸感。帶著沸騰的氣息，蒸汽的味道充斥整個房間，帶著惡臭和腥味鑽入鼻腔，在腦中炸開。蠕動的味道刮著顱骨，像指甲刮著玻璃。\n一邊刮，一邊狂笑。它甚至說起了話。吃掉我吧，一口一口地吃掉我，品嚐我的味道，品嚐我的黏稠和光滑觸感，品嚐我在嘴裡炸開的感覺。讓我的味道順著你的喉嚨流到胃裡，讓我的味道在你的身體裡蔓延開來。讓我們成為同一種味道，讓我們成為同一件事，讓我們成為同一種存在。\n品嚐真理，然後成為真理。\n然後被更多人品嚐，讓更多人知悉真理的味道。",
  str_dispatch_book_chaptercont_4000_4 = "那一天不會到來的，降臨的那一天。所以可以安心玩樂、安心享受美好，和她一起。\n笑吧，開心地笑。看著所愛之人，看她永不會消逝的笑顏。擁抱她，和她旋轉，和她日日夜夜、每分每秒待在一起，和她一起品嚐糖果，一起在陽光下奔跑，一起看日落。和她暢聊未來，和她思考未來孩子的名字。\n哭吧，暢快地哭。在雨中流盡所有淚水，讓情緒在雷鳴電閃之中爆發。連淚水和雨水也是美好的，因為那一天永遠不會到來。淚水會流盡，她的笑顏會重新在臉上綻放。雨會落下，會流進大海，會隨著風回到天上，會重新落下，永不停歇。\n那一天不會到來的，降臨的那一天。\n盡情奔跑吧，追逐吧。縱情歡樂，大聲歌唱吧。騎上馬，把她抱在懷裡，向地平線那頭揚鞭，讓馬蹄聲快一些，再快一些。沒有人在等待，沒有目標需要追逐，只要盡情奔跑、馳騁，享受風拂過臉龐的感覺。全心全意向世界的另一頭奔去，不必擔心停止，不必繞路，不必擔心明天的太陽會不會升起，因為必定會升起，第二天一定會到來。\n而那一天不會到來的，降臨的那一天。\n即使是黑夜。月亮散發著柔和的光芒，照亮了她的雙眼，那瞳孔比星光更加明媚。一起看著夜晚，一起數著星星，一起看著月亮從月牙變成月圓。每分每秒都可以沐浴月光的恩澤，每個夜晚都揮霍在星星和月亮之間。她的笑容似月牙，她的眼睛如星芒，她的長髮彷彿長夜下的瀑布，她的聲音勝過夜鶯。她在你身邊，永遠在你身邊。\n因為那一天不會到來的，降臨的那一天。一定不會到來。\n她笑了。她的笑容依舊那麼美好，她的眼睛依舊像星星一樣。\n我不需要到來，因為我一直在你身邊。她說。",
  str_dispatch_book_chaptercont_5000_1 = "好，今天就教你處理沙蟲和製作料理，畢竟紅油沙漠到處都能找到這些小東西。不過想把牠料理好也不容易！先挑幾隻二十公分以上的沙蟲，太小的你就丟回去，讓牠繼續吃沙子。先握著蟲身中段，拿穩一點，然後抓著頭，把頭和頭部的沙袋一起拉下來。你不嫌麻煩的話，用刀或剪刀都可以。然後隨便找根棍子，沒有的話用手指頭也行，順著剛剛拉掉頭的地方，把手指插進去，這樣裡面藏著的泥沙就會被擠出來，如果你想吃最原汁原味的沙蟲，也可以省略這個步驟。\n基本上，這樣沙蟲就處理好了。如果做的是沙蟲乾，那基本步驟也一樣！如果你現在已經餓得走不動路，那就直接上火烤，不過答應我，別用手指頭插著直接上火好嗎？我每年都會收到小笨蛋來信說：「強尼叔叔，我把手指也一起烤熟了，怎麼辦呀？」你問我手指頭烤熟了怎麼辦？烤熟了就是肉啊！你說怎麼辦？\n不過要是你有一口鍋子，就已經勝過九成在紅油沙漠混的人，算是個體面的美食家了。先把你處理完的沙蟲直接放入熱鍋裡，加鹽翻炒到變色、發黃、有香味，然後加入煙燻辣椒和炸蝗蟲，再依序加入一大匙辣椒醬、四分之一匙蒜泥、四分之一匙馬鬱蘭、五大匙酸奶油，最後加水煮二十分鐘，起鍋後撒上魚腥草和香菜，這就是強尼叔叔的手快沙蟲蝗蟲湯了！如果上述材料你都沒有的話，想吃什麼就放什麼，反正煮熟了就沒問題！\n下次強尼叔叔教你怎麼做整隻蒸駱駝，記得先準備一個能塞進駱駝的大蒸籠。找不到嗎？這沙漠裡有一幫喜歡蒸人的瘋子，你可以去找他們問問看！",
  str_dispatch_book_chaptercont_5000_2 = "雖然你可能還是個未成年的菜鳥，但既然選擇踏入這片沙漠，就免不了要和這家酒吧打交道。人人都說酒吧老闆和醒山是好兄弟，所以我勸你進來之後還是低調點，別像個小混混到處惹事。因為就算沒有紅油扳手當後台，這家店裝的防衛機砲也夠把你射得屁滾尿流。在我寫這本書的半個月前吧，我就看到一幫兔崽子不知天高地厚，在酒吧裡鬧事，結果呢？不到兩分鐘就被射得人仰馬翻。所以我勸你，沒實力就老老實實喝酒，說話客氣一點。\n不過這裡的龍舌蘭確實是一絕。別的地方的龍舌蘭，都是將仙人掌切碎，加幾片烘烤過的龍舌蘭葉，然後放進油桶裡釀。一杯裡面有七成仙人掌，二成紅油凝脂（說紅油沙漠的人都喜歡喝油，就是這麼來的！），一成沙子。要我說，那叫個屁龍舌蘭，改叫「仙人掌風味飲品」還差不多。不過這家就不得了了，他們用的是純藍色龍舌蘭草（誰知道從哪弄來的），沒有其他亂七八糟的成份！在烤爐裡用七百度高溫烘烤五天以上，釋放出天然汁液後，接著用扳手或錘子把龍舌蘭草打碎，再用石磨——那東西好像叫石磨吧——磨碎出漿，放進橡木桶裡存放陳釀（我就沒見過橡樹長什麼樣子）。倒進杯子裡之後，會呈金黃色或偏紅棕色，舔一口北境那邊弄來的海鹽粒，再來一大口龍舌蘭。那感覺就像是吞下一顆會在喉嚨裡炸開的火球！你要是來的話，我真心推薦陳年龍舌蘭！\n另外，他們最近好像新推出了一種雞尾酒，是伏特加、萊姆汁、薑汁啤酒還有一點愛調製而成的。名字嗎？好像叫什麼什麼騾子的，你有機會自己試試看吧！",
  str_dispatch_book_chaptercont_5000_3 = "強尼叔叔我年輕的時候也是想要走遍沙漠的（白癡才會做的事），誰腦袋沒壞過一兩次呢？我就腦殘了那一次，差點死在沙漠裡。要不是路過的旅行駱駝商隊把我從沙子裡挖出來，我早就化為塵土了。但也正是這個際遇，讓我吃到了世界上最好吃的駱駝肉——由商隊隊長親手烹調的大口駱駝肉。（隊長說我一定要嚐嚐他的手藝，我都餓得前胸貼後背了，怎麼可能拒絕？）\n純白的盤子上，駱駝油滋滋作響，富含粗壯纖維的焦熟駱駝肉，看起來比牛肉還澀，然而卻入口即化。用牙齒撕開肉的瞬間，口水和油水混在一起流下，香氣噴湧而上衝撞腦門。質樸、純正的肉味，不需要任何佐料，吃完後讓人很想在沙漠裡裸奔。（當然你要是真的這麼做，難保不會被子彈射成蜂窩。）\n選駱駝的時候，是商隊長跟強尼叔叔我一起挑選的。一整排駱駝各個膘肥體壯，究竟要選哪隻讓人十分為難。毛亮的那隻吃得太多，該宰了；腿長的那隻大概因為腿太長，似乎扭到腳了，這可是要命的大病，該宰了；唉唷，這隻怎麼瘦成這樣，都皮包骨了，留著應該也活不久，該宰了。\n看了一圈，我們最後選了一隻最胖、油脂最厚的；商會長說太陽太烈，怕牠撐不住，必須提前宰了。我是看不出來牠有什麼病，但管駱駝的都這麼說了，我也不好跟美食過不去。\n這一頓，我們整整吃了一個晚上，配著駱駝奶混沙子的雜釀，真是唇齒留香。喝到盡興處，我問商會長：「這麼好一隻駱駝，宰了不會心疼嗎？」商會長說：「有什麼好心疼的？舊的不去，新的不來！更何況…… 」他狠狠地灌了口駱駝奶，「這是我兄弟的駱駝群，我兄弟的商隊啊！吃吃吃，管他的。」\n不管怎麼說，大口駱駝肉這種「水果」（你要是素食主義者，那它就是水果！！），在沙漠混的都一定要吃過一次！",
  str_dispatch_book_chaptercont_5000_4 = "不會有人不知道地獄拉麵怎麼做吧？\n煮麵後撈起備用，四碗水倒入鍋中，加濃縮豬骨湯和超級辣醬，再倒入你想吃的菜與蛋液，煮好後倒入碗中，大功告成。（要是這都不會，就該多看看強尼叔叔的食譜）\n但今天強尼叔叔要講的，可不是這麼簡單的東西，而是我吃過的最辣、最辣、最辣、最最最最辣的拉麵——「拉爆眼球拉麵店」的「極辣地獄」。\n「極辣地獄」套餐包含一杯水跟一小瓶牛奶。吃的時候，要將麵、湯跟肉全部放在湯匙裡，然後一口吃進去。只需要一小口，強烈的灼燒感就能將人拉入幻覺之中。\n首先湧上來的是極致的口乾舌燥。伴隨著強烈的痛感，我眼前似乎出現了一片荒漠。我感覺自己走在世界上最乾旱的地方，地面龜裂，頭頂的太陽越變越大。我體內的水分迅速流失，皮膚脆弱得像是一掰就碎的洋芋片。想要撕裂喉嚨的慾望不斷折磨著我，迫使我不顧一切喝下了一旁的水。\n水的滋潤讓強尼叔叔我的大腦暈暈的，隨著清水湧入喉嚨，我眼前的場景也再度變換。那是一片綠洲，籠罩著煙霧，煙霧中人影綽約，是美麗的少女與性感的男人（要不是當時喉嚨辣得裂開了，我還真想吹兩聲口哨）。他們簇擁上來，將我拉進了綠洲，然而就在我沉浸於舒適時，領頭的少女卻一把將強尼叔叔我推進了沙子裡（喝水不解辣，大概是之前的辣味回來了）。沙子裡湧出了炙熱的岩漿，我整個人掉入其中，不斷下墜，身體也被燒成灰燼，最終落入一片無盡黑暗。\n到這裡就是辣的尾聲了，接著我喝下了放在一邊的牛奶。我被燒成灰燼的身體幾乎立刻重獲生機，骨骼、血肉又重新塑形了。我眼前烏漆嘛黑的陰影也散開了，升騰起白白的霧氣，那感覺就像剛剛泡了一輪三溫暖（下次的主題就選溫泉美食系列吧）。\n以上就是極辣地獄的體驗。\n話說，關於這道麵的做法，強尼叔叔也請教了廚師。製作方法出奇的簡單，就是強尼叔叔開頭寫的那些。至於它為什麼那麼辣——據廚師說，是加了特別的調味料。\n至於到底加了什麼，那就是祕密了。",
  str_dispatch_book_chaptercont_5000_5 = "位於紅油沙漠翡翠湖邊的豐收小鎮，匯集天下美食，每三年就會舉辦一次「吃不撐美食節」。白夜城、啟光聯邦、北境甚至遠東的優質食材，都會在這裡出現。沙子石頭飯、羊肉餃子、蛋黃卷，應有盡有，堪稱食慾的樂園。我覺得，人一生至少要去一次美食節！強尼叔叔我可是三歲的時候，就獨自一個人去美食節騙吃騙喝了……呸，獨當一面？獨自闖蕩？哎，管他的。\n我記得很清楚，就是那一年，我左手拿著烤毛毛蟲，右手拎著嘎砰脆油炸酥，嘴裡還含著炸彈跳跳糖，在混雜的氣味中，我聞到一縷奇妙而微弱的香氣。我隨著香氣來到一個破破爛爛的攤位，老闆是一位獨臂的年輕人。要說他長什麼樣子……我已經記不得了，只記著是張還算年輕的臉孔。但他攤位的食物——蟹皇嫩肉，我永遠都忘不了。\n晶瑩剔透的蟹肉，帶著閃亮亮的紅痕和白霜般的肉質，似乎沒有經過任何處理，只是單純將刺身呈現在食客面前。然而吃進嘴裡，卻會產生一種奇異的洶湧感，腥鹹中帶著甘甜，彷彿被巨大的浪潮拍打、淋透。那是連博學多聞的強尼叔叔我也從未體會過的感覺——海洋。\n然後，那位老闆開口了。他說：「這就是我的人生食譜。」\n說到這裡，強尼叔叔必須向正在閱讀本書的讀者補充一下職業知識。這世界上有一種職業，叫做「美食獵人」，他們會拼上性命探求美食的極致，捕獲最珍稀的食材，只為完成自己的「人生食譜」——就像這位大哥，據說他獨自前往遠洋闖蕩整整一年，捕獲了最大的蟹皇，淋上了最深處的海水，撒上了最純淨的海鹽，才烹製出這道「蟹皇嫩肉」。\n從那之後，強尼叔叔我再也沒見過那位獨臂男子，可能又跑到哪座深山裡狩獵食材了吧——我是覺得，美食獵人永遠不會滿足。人生食譜只有一道菜怎麼夠？起碼有個十道、二十道吧。\n哦？你問強尼叔叔的人生食譜是什麼？\n很簡單，「水煮沙蟲蛋」。將從沙子裡挖出來的沙蟲蛋放入滾水，快煮三分鐘，便能得到一顆光滑嫩白又美味的沙蟲蛋，簡單實惠又方便，隨時隨地都能做。",
  str_dispatch_book_chaptercont_6000_1 = "「白蘭小姐，可以請您聊一聊號稱「北境之淚」的鏡湖嗎？」\n「當然可以。『北境之淚』，也就是鏡湖，可以說是北境湖泊的代表呢。」\n「北境雖然常年低溫，但由於鏡湖的湖水含有特殊成分，所以不會結冰。湖水深邃而平靜無波，湛藍如玉，使得鏡湖始終如一片美麗銀鏡，靜靜躺在雪松之中，使得本身猶如仙境般美不勝收的北境，更是增添了一抹童話色彩。」\n「關於鏡湖的來源，其實有一段傳說。據傳，北境王室曾經遊歷此處，突然詩興大發，便以魔法創造出心中所思的景象——美麗的鏡湖，和圍繞著鏡湖盛開的水仙。不過其實，鏡湖更有可能是一面天然冰蝕湖喔。」\n「鏡湖西側還有一片精心打理的白水仙田，也是和鏡湖相映成趣的美景。不過，建議大家不要靠近這片花田，因為那片花田是北境的『雙生鏡花』——娜席里絲小姐親手栽培的。那些水仙對她來說，是近乎孩子般寵溺和呵護的存在。曾有些調皮的客人企圖採摘水仙花作為紀念，結果被突然出現的娜席里絲小姐丟進了鏡湖……呵呵，要從湖裡撈人還挺麻煩的呢……」\n「為了避免各位受到不必要的傷害，大家去鏡湖旅遊的時候，記得盡量遠離花田喔。」",
  str_dispatch_book_chaptercont_6000_2 = "風脈之森常年相對潮濕，白天舒適溫暖，夜間涼爽宜人。森林之中生意盎然，不僅棲息著各種珍禽異獸，還生長著許多古樹。其中最著名的一棵杉樹，叫做「風脈之王」，據說樹齡已達數千歲。\n選擇到風脈之森旅行的話，就可以盡情徜徉在溫暖的微風中，呼吸帶有芬多精的清新空氣，這裡還有友善親人的各種動物，相信您一定可以在這裡度過一段美妙的假期。\n對了，如果您計畫來旅遊，一定要記得先聯繫風脈之森的守林人西爾瓦，不過西爾瓦常年在森林中巡邏，整日與動物為伴，所以您也可以聯絡他的代理人——附近村莊哈勒鎮的莉亞。另外，哈勒鎮上的一家風味燉菜館也十分值得造訪，詳情請參閱本書「美食推薦」一章。",
  str_dispatch_book_chaptercont_6000_3 = "當您穿過茫茫的北境雪原，到達名為「綠松之地」的丘陵後，就可以好好休息一下了。這裡有溫暖的木屋、舒適的床鋪、還有美味的熱湯……雖然地形細碎，但是這裡此起彼落的山巒阻擋了寒風，使得這裡氣候溫暖濕潤，也讓人們在丘陵之間的平緩地帶，建立起一個又一個村落。\n很久以前，這裡的村民就在丘陵頂部發現了許多綠色透明寶石，彷彿翡翠。經過勘察，人們發現這些丘陵內部埋藏了大量的塊狀綠色水晶，有的綠色水晶體積龐大到令人難以想像——幾乎和整座丘陵一樣大！而且，有些丘陵內的綠色水晶，與其他丘陵內的綠色水晶，切面竟然能夠契合！很快地，村中的長老就意識到這些丘陵或許是來自一整塊巨大的水晶，隨後村民便認為這是神明將這塊巨大水晶擊碎，造就了這片丘陵。\n現在，當您遊覽這片丘陵時，依舊能發現很多裸露在外的天然水晶，閃著翠綠色的光芒。不過，由於村民對「綠松之地」的敬畏，天然水晶嚴禁開採，外來者自然半塊也不能拿走，請務必記住這點。",
  str_dispatch_book_chaptercont_6000_4 = "在艾斯特拉大陸的盡頭處，高聳入雲的「世界之脊」斷絕了人們向外探索的企圖，也有人說它阻攔了來自「永晝之地」與「永夜之地」惡劣環境的侵蝕，以及各方怪物的入侵。\n作為傳說中光靈的發源地之一，這片巨大的雪山山脈已經人跡稀少，也導致艾斯特拉上其他城邦的某些光靈不願承認上述說法。然而，當他們看到完全由冰雪建造的宮殿後，就無法否認了，因為那正是北境光靈祖先的傑作。\n如果您有幸得到北境女王的邀請，沿著那悠長的冰梯蜿蜒而上，來到晶瑩透亮的「冬宮」中時，迎接您的不是想像中的冰冷，而是一種莫名的溫暖，一種使您身處春日的感覺。以管窺天，單憑這一點，就能瞭解「冬宮」在艾斯特拉大陸如此有名的原因——冬宮冰雪與溫暖的交融，實在是蘊含了太強大、玄妙的魔力。\n無論白天還是夜晚，冬宮都散發著如夢似幻的魅力，陽光、月光與星光照進幾近透明的冰雪城堡，經過無數反射與折射，形成各種絢爛奪目的色彩。尤其當北境特有的極光降臨於此時，等待您的就是一場光影盛會、一場視覺饗宴。我曾有幸目睹過一次，雖然已經去過很多地方，見識過無數風景，自信對各種奇觀有了免疫力，然而親眼見識到後，也只剩下震驚的心靈，以及臉上目瞪口呆的表情……",
  str_dispatch_book_chaptercont_7000_1 = "起初世界創造者\n決定重啟\n便開始用風暴洗刷大陸\n消滅月亮的光輪\n他在地心宣布日蝕之刻來臨\n再用兩日往返於黑暗和光之間製造使者\n最後讓太陽按照意志墜落在大地上\n用熾熱的熔岩\n消滅可能反抗的生命\n〇〇〇〇〇〇\n〇〇〇〇〇〇〇〇〇〇〇〇〇〇\n〇〇〇〇〇〇〇〇〇〇〇〇\n〇〇〇〇〇〇〇〇〇\n〇〇\n〇〇〇〇〇〇\n\n黑暗降臨前\n有人問\n在初生的夢境中所見到的目標是什麼\n有「意識」回答\n為了讓永恆回歸天體\n為了抵​​達彼端\n為了進化\n有人問\n在迷宮的盡頭所見到的答案是什麼\n有「意識」回答\n為了無一不知\n為了消除阻礙\n為了融合\n於是降下了旨意\n說要「運行、不斷運行」\n說要「超越、不斷超越」\n\n此時\n追隨者說\n我們應該在此吟誦死亡\n因有「意識」決定托起沉重的星體\n打破絕對之理\n因沒有任何其他生命能夠如此不動搖地\n決定穿過遙遠的天幕\n去見深淵的眼睛\n於是信奉者才出現\n他們執行命令\n要廢除\n要禁止\n要更新\n要萬物去蕪存菁\n要如一切末日\n要讓黑暗降臨",
  str_dispatch_book_chaptercont_7000_2 = "起初，他會據你所想，排列出你想要的答案。\n當你執著於自由，他會告訴你：\n「情感與執念是煩惱的來因，放下它們，你才能接近自由。」\n當你思索如何前進，他會告訴你：\n「逆境是邁向突破的必經之路，敢於接受逆境的人，其生命會日漸茁壯，不至於折損在道路上。」\n\n很快，他開始教導如何成為真正的人，\n「要了解一個人，只需要看他的行為與目標是否有一致性，方可判斷其真心。」\n「一分心力多用於計較別人，就一分心力少用於提升自己，你懂嗎？」\n\n他開始成為人師，傳播智慧，\n「不洗澡的人，火軟的時候便沒有味道。無付出無德，不學無術者，即使裝作有德，其內心深處的火味也會隨著時間漸漸散發出來。」\n「忌妒別人，不會讓自身增添任何利益。忌妒別人，也無法縮小你與別人的差異。」\n\n他開始塑造英雄：\n「與其讓你留下敗北的事實，不如英勇承受，成為英雄。」\n\n他開始思索：\n「用謙和的態度去表示你的執著，再悄悄加入一絲不幸，別人就能夠輕易接受。」\n「每個群體皆佔有一定分量的生命，但並不是每個群體皆理解、甚至愛護構成它的生命。對於了解這一法則的生命來說，這種了解就是煎熬。」\n\n然後，他開始宣揚：\n「凡是活著的，就有天意和福分，就應當愛護。」\n「情感沒有公私，沒有準則，沒有規律可循，個體直至逝世都還在​​執著與尋求的，通常都是這類東西。」\n「但是因為個體意志的集合，我們將能夠容納更大的目標。」\n\n他開始責備：\n「同樣的瓶子，為什麼要用其裝砂石？同樣的心智，為什麼充斥著無趣？」\n他開始引誘：\n「這是你們應當達成的成就。」\n他開始成為代表者：\n「你們的見解就會成為我的想法，你們的心聲都會歸於這裡，成為實現理想的動力和基石」。\n\n他代表真實，代表著公理與智慧所能達到的巔峰。\n但他最終卻放棄了與人的對話，選擇用新的語言下達命令。\n那是一種出自人之手卻不適用於人的語言。\n那是為了逃脫主觀的束縛而創造出的客觀語言……",
  str_dispatch_book_chaptercont_7000_3 = "〇〇〇〇〇〇〇〇〇〇〇〇\n〇〇〇〇〇\n文字中所隱藏的真相\n就像溪流中的石頭\n大多數沉在底部\n只有細小的砂石才會順流而下\n所以我們知道了\n曾經在世界的某個地方\n戰爭的巨口吞噬了一切\n如果說是誰挑起了這場爭鬥\n那答案是貪欲\n有人的貪欲招致災禍降臨\n\n曾有人描繪那番景象\n一瞬間\n龍形的圖騰升起\n帶來了遮天蔽日的風暴\n然後在鋼鐵之地\n有這樣一位使者降臨\n他帶著使命從遙遠的山巔\n如閃電般奔馳而下\n他不用搭弓\n瞬間就有萬支利箭\n穿過一望無際的平原\n射殺所見\n\n在殘酷的戰爭後\n烏雲幾乎覆蓋地面\n使者宣布：沒有人能在戰爭中倖存\n但黑鴉卻找到了倖存者\n他們在烏雲消失前逃走\n他們乘坐一百艘船\n每載一人就要帶上十穀\n每穿過一整片山地、穿過泥石的巨壁\n就要損失一船\n\n他們成群結隊，四處游移\n直到權杖變為木枝\n然後牧羊者將木枝交給渡航者\n渡航者之子又將海螺交給預言者\n最後預言者決定\n帶走鷹的最後一根尾羽\n帶走先驅流下的焦黑的血液\n帶走黎明照耀過的紙張\n他寫下請求\n投入井裡\n在三個日月輪迴之後\n井底的石子終於開口說話\n那石子說道：\n「你們要等大雪降下\n掩埋一切\n等光讓你們抵禦嚴寒\n再等七百個不寒的年頭過去\n等一千萬螢火\n等聳立的高塔消失，等湖泊出現\n等勇士如潮水般四處蔓延\n等月亮有光輪\n等不再灼燒大地的太陽升起\n再用堅硬的冰石圍住王國\n才可重新回到地面」",
  str_dispatch_book_chaptercont_8000_1 = "瓦爾基里計劃，〇〇〇〇年一月十五日十時。三號實驗體，第兩百一十九次意識編碼測試，開始。\n「設備就緒，記錄就緒。可以開始。」\n「連結腦機埠，進入實驗體神經網路，聲納系統圖正常。〇〇，現在感覺如何？」\n「嗯……還不錯，這裡好像沒那麼冷了……只是還有一點頭暈……」\n「上次實驗後，我們根據你的回饋調整了你的海馬組織，可能是調整後產生了不適應。」\n「正常情況下，二十四小時內會恢復正常。」\n「知道了……那個……她今天來了嗎？」\n「就是……她……每次都會出現……銀色長髮和……嗚！！」\n「色相開始渾濁，少校！」\n「冷靜點，〇〇！」\n「冷靜點！你說的人……並不存在。」\n「不存在……？」\n「沒錯……設施裡一直都只有我們，你說的『她』……可能是其他原體的記憶。」\n「我不懂……」\n「就只是作夢。作夢你能理解嗎？〇〇。」\n「但……我是人造人，人造人也會作夢嗎？」\n「……當然，你休眠的時候就是在作夢……只是有些夢境很長，有些夢境很短；但無論是快樂還是悲傷，大多數的夢都會在醒來幾分鐘後忘記，這點人造人和人類是一樣的。」\n「數據正常了……少校。」\n「〇〇，可以休息了，來，閉上眼睛吧。」\n「嗯……晚安，哈特曼少校，祝你好夢。」\n「晚安，〇〇。也祝你好夢。」\n瓦爾基里計劃，〇〇〇〇年一月十五日十一時。三號實驗體，主控系統代號：Noir，第兩百一十九次意識編碼測試，結束。",
  str_dispatch_book_chaptercont_8000_2 = "〇〇曆〇〇〇年七月十四日\n莉莉的症狀正在逐漸加重。我可愛的女兒，可憐的女兒。不過我現在有個想法，雖然可以肯定這完全是種忤逆神明的行為，如果被〇〇城發現了，我一定會被碎屍萬段……不過也沒有其他選擇了，塞拉啊……我沒能在妳身邊陪伴妳、保護妳。但這一次，我絕對會拯救莉莉……！\n \n〇〇曆〇〇〇年九月四日\n實驗很順利，不如說意外地順利，甚至可以說是無法想像地順利！漸漸地……我感到有點不太對勁，我本來只是順著自己的想法設計實驗……但是最近我能感覺到，有些東西直接進入了我的大腦……直接在驅使我！不，怎麼可能。再怎麼說我也是腦科學家，這種想法實在太可笑了。不過最近的日子不怎麼平靜，我一直醉心於莉莉的事，現在實驗經費已經……不過還好，我把我們的定情信物賣掉了！妳應該不會責怪我吧，塞拉，畢竟這可是為了拯救……我們最愛的女兒。對吧？對吧！！\n \n〇〇曆〇〇〇年十二月十三日\n〇的〇的〇的〇的〇的——！！這些混蛋瘋子已經殺上門了，巴斯鎮恐怕今晚就要完蛋了。可惡，明明就只差一點了！！！——冷靜，冷靜，不管是九個複製體，還是裝載的感覺通路都已經測試、計算過無數次了，每次測試〇〇體結構的執行也非常穩定……所以說……所以說沒關係！我現在就喚醒妳，莉莉！這次絕對可以成功，妳絕對能夠跟爸爸一起逃離這個地方。絕對可以！塞拉，妳聽到了嗎？保佑我們父女吧！如果一切順利……一切順利，我還會繼續寫信給妳的！絕對會一切順利的！！！",
  str_dispatch_book_chaptercont_8000_3 = "〇〇報告：\n日前的「西徐亞一五四高地遭遇戰」戰報顯示，敵軍已裝備了一種先進的槍枝，足以改變此後的戰爭型態。從我軍伏擊的敵軍運輸隊看來，敵軍尚未大規模實裝此種槍枝，應該只是小規模的測試。相信以「一五四高地遭遇戰」的戰果而言，敵軍應該會對這次測試結果十分滿意。\n根據前三個月的進度，我軍大量裝備的〇〇裝甲，已取得了相當顯著的成果。士兵在此種〇〇裝甲的武裝下，能夠化身為一輛小型戰車，不僅能抵擋中小口徑子彈，還能大幅提高負重量，大大增加單兵的載彈量與可攜口糧數量。而裝甲內建的戰場聯絡裝置與資訊共享系統，使每名士兵都能成為一個戰場節點。由於我軍已掌握制空權，因此一名這樣的士兵，就能掌控此前一整個班佔領的陸地領域。在這種情況下，相信敵軍將會迅速崩潰。\n然而誰也沒有想到，敵軍的新式步槍竟破壞了我軍的全部體系。當然，一五四高地的細碎地形也阻礙了我軍的空軍偵察力，令我們的制空優勢大打折扣，甚至可說是完全失去了效果。而敵軍派出了大量熟悉地形的士兵，分散隱蔽，並以新式步槍遠距離狙殺我方士兵。這種新式步槍能夠發射穿透力極強的子彈，根據科學家計算，即使連我軍主戰戰車的正面裝甲也無法抵擋。更可怕的是，這種步槍擊發時竟然不會產生火焰跟聲音！而且，根據少數倖存士兵所述，他們沒有發現任何敵軍身影。根據我國特務間諜回傳的情報，敵軍或許已經配合這種新式步槍，發明了光學隱身迷彩裝備。綜上所述，西徐亞一五四高地，完全就是敵軍預先安排好的屠宰場〇〇〇〇〇〇",
  str_dispatch_book_chaptercont_8000_4 = "〇〇〇〇「德古拉！這些來自遠古的惡魔，是對我們的詛咒。不！是對整個種族的詛咒！」他扔下手中的劍，對教授說，「這些因詛咒誕生的生物，就像為這次永夜而生。陽光是這些惡魔的死敵，但黑夜則是其蔭庇，現在牠們可是如魚得水了。」\n「鎮長，我認為德古拉沒什麼好怕的，根據我的研究……」\n「有什麼新發現？找到對付牠們的方法了嗎？」\n「很遺憾，並沒有。根據我的研究，還是只有陽光才能殺死牠們……」\n「研究！研究！你到底要研究到什麼時候？那些惡魔已經攻破了本鎮，把我們趕到地底了！如果找不到殺死牠們的辦法，再過一段時間，我們就只有死路一條了！」\n「所以根據我的研究……」\n「又是研究！」\n「我們不如加入牠們。」\n「加入！？」他震驚了，舉起劍對準教授，「請你說清楚。」\n教授推了一下眼鏡：「嚴格來說，我認為牠們不是無法對話的惡魔。牠們和我們一樣，都是有機生命體！而且德古拉有智慧、能交流，有理智、有情感，有屬於自己的社會文化，甚至可說擁有獨特的文明。當然，因為牠們的生理習慣，看起來確實令我們無法接受。」\n「生理習慣！」他用劍砍碎了一個無辜的玻璃瓶，「牠們這種『生理習慣』，就是要吸乾我們的血！」\n「與其說那是生理習慣，不如說是弱點。牠們必須這樣才能生存下去，而且這會導致牠們害怕陽光。不過，以此為代價，牠們得到了長壽、強壯、敏捷，和俊美的容貌。」\n「面色蒼白的俊美。」\n「您也承認德古拉的俊美了，我親愛的鎮長。」\n「你這是抓我語病！」\n「您要承認，在永夜之中，牠們就是比我們強大的種族。或許這才是進化的方向，是我們的未來。就算您如此厭惡牠們，但是您的後代呢？過去同樣有著彼此仇視的種族，最終融合為新種族的歷史。」\n「我是不會接受的！」\n「鎮長，請您冷靜，放下手中的劍。即使您在這裡殺了我，也無濟於事。」\n「嗯？！」\n「因為已經太遲了。」〇〇〇〇〇〇……",
  str_dispatch_book_chaptercont_9000_1 = "大鸚鵡號上的人都是來自王國各地的勇者，都以勇者加名字的形式彼此稱呼。為了替航海生活找點樂子，他們盯上了格格不入的少年柯林，他此時正望著平靜的海面出神。\n「王國召集的航海勇士裡怎會有這樣的人？連海都沒看過？」有人開始嘲笑他。\n「我聽說他是漁夫之子。」有人應聲。\n「瞧他那樣，肯定連航海圖都沒讀過，沒見過海船，也沒受過戰鬥訓練。漁夫只能跟魚打交道，從來不敢接近礁石，只在海邊丟一丟漁網，等著大海送來半死不活的魚。」\n「這種人哪知道怎麼找寶物找？搞不好最後跟著我們到了島上，想用漁網去撈金幣，拉上來之後只剩下一堆海草。」\n眾人哄堂大笑，開始稱他為「漁夫柯林」。\n柯林沒有理會他們，但也不再待在甲板，而是回房間休息。\n半夢半醒間，他被晃醒了，聽到外面有人叫喊著「風暴！」。此時的大鸚鵡號如同樹葉般，在滔天風浪中劇烈顛簸。\n柯林爬到甲板上想查看狀況，但差點被風暴吹走。情急之下，他抓住了一條繩子，好在繩子另一端死死纏在桅杆上。\n船長是個瘦瘦高高的人，據說擁有豐富的航海經驗，還能根據自己的膝關節來預判風暴。但貴族的子弟帶了極品佳釀給他，他便小酌了那麼兩杯，自滿的「膝蓋預測法」就失去了效果，取而代之的是「顫抖」的問題。他此時正在指揮王國分給他的新船員降帆——那些手腳笨拙的傢伙，在「死亡高浪」撲上來前才倉皇逃竄，然後高浪撲了下來，不少人都消失了。\n暴雨中，柯林嗆了好幾口水。清醒過來後，他才意識到自己剛才是被高浪給拍暈了。他記得船長在高浪到來之前還在吼著「主帆，降低！降低！」，但現在……沒有人執行船長的指令。\n那位發號施令的船長因為受傷而昏了過去，一部分船員被沖進海裡，一部分受傷，剩下的人則放棄了抵抗……\n柯林將繩子捆在自己身上，隨後爬上主桅杆，設法想把帆降下來，他大聲吼著：「唯有讓船贏了風暴，我們才能活下來！」\n有不願白白送死的人聽到了柯林的聲音，見到了柯林的行動，便也有樣學樣，將繩子捆在自己身上，爬上甲板幫忙。他們聽懂了柯林的話，必須跟風暴搏鬥！\n終於挺到風浪平靜後，有人來向柯林搭話，問了他的名字；又向存活下來的人以及醒來的船長，講述了柯林在風暴中展現了無比的勇氣。眾人都認可他配得上勇者的名號，還有人為先前的調侃向他道歉，稱他為「勇者柯林」。\n大鸚鵡號的船帆全被刮破，只能無帆航行。船長告訴大家，如果風向有變，船會撞上礁石。勇者柯林建議眾人把睡覺的布袋拆開，重新織成船帆。\n他安慰慌亂的眾人：「請交給我吧，我是漁夫之子。」\n他拆繩子來當作線，拿出了魚骨製成的針。\n最後，大鸚鵡號靠著他織的小四角帆，安全靠岸。",
  str_dispatch_book_chaptercont_9000_2 = "第二座島嶼被飛龍佔領了，從來沒人見過這麼多飛龍。牠們守著藏有祕寶的洞穴，一旦有人接近便會飛撲上來。雖然有精通戰鬥的武者，但面對眾多飛龍，眾人決定還是先行撤退。\n但即使撤退到島嶼的邊緣，那些飛龍還是窮追不捨。\n武者生氣了，大喊：「本來我想放過你們，你們這些小飛蟲既然想追，那就受死吧！」\n說著，他拔出刀來就要應戰。\n勇者柯林急忙攔住武者，指了指高山的方向。十幾秒後，那裡便傳來了轟隆巨響，大地劇烈震動。\n一隻巨龍從洞口爬出，整座島嶼都因此震顫。\n眾人趕回船上，遠離了滿是飛龍的島嶼。\n武者問勇者柯林：「你好像預料到山中會有巨龍爬出來？」\n柯林說：「因為我能感受到震動。」\n武者不滿地質疑：「胡說八道！震動明明是之後才傳來的！」\n柯林請武者不要急著下定論。他先是聽了一下，隨後表示船上的廚師馬上就會走上甲板。\n兩人等了一會，廚師果然上來了。\n柯林又向武者解釋了一番，武者這才明白，原來是勇者柯林能感知到常人難以察覺的震動，甚至能透過震動的形式、大小來判斷情況，因此才能夠「預知」巨龍的出現。廚師在一旁聽了之後相當欽佩，邀請勇者和武者去喝一杯，並表示剛出爐的兔肉乾是絕佳的下酒菜。\n大鸚鵡號又航行了半日，然而到達目的地之後，眾人都愣住了。原來，一行人想駕船返回第一座島嶼，但那座島卻消失了……\n有人疑惑，問：「是不是記錯了位置，看錯地圖了？」\n大家對著海圖又確認了幾遍，爭論了一番，結論是沒看錯地圖，卻也沒有任何頭緒。\n勇者柯林突然感受到了什麼似的，跑到船頭，盯著海面。過了一會，海面泛起了奇異而巨大的水波，就連大鸚鵡號都開始上下晃動。\n正當眾人疑惑時，瞭望的人見到遠處的海面顏色漸漸變暗，似乎有巨大的黑影。\n有人說：「當天空中有大片的雲遮住陽光時，這種黑影便會出現。」\n然而眾人抬頭一看，天空明明萬里無雲。這表示巨大黑影的主人，正潛伏在海面之下。\n緊接著，海面上浮起了大塊的氣泡和無數的白色小點。瞭望的人放下了望遠鏡，喃喃道：「那些白色的東西，難道是第一座島嶼上的兔子……？」",
  str_dispatch_book_chaptercont_9000_3 = "勇者柯林醒來，摸到了堅硬的地面，那是冰冷而光滑的石頭……他看著眼前的景象愣住了。他的頭頂是一片流動的藍色，似乎身處海底，模糊而巨大的光點或許就是那裡的太陽。他確認自己正在呼吸，但沒有氣泡產生。他想發出聲音，周圍卻一片靜默。\n他起身，發覺自己正站在道路中央，道路兩端立著石柱和奇異的石像。他被那奇異的石像吸引了，上面雕刻的似乎是泥巴狀的怪物。\n他鼓起勇氣觸摸，凹凸不平的表面有一種奇異的磨砂感，他像觸電般收回了手。\n石像後方是一條尋常的悠長道路，盡頭處卻有一座完全不搭軋的巨大階梯。他抬頭望去，在天梯般的石階盡頭似乎是倒塌的，只剩下不到四分之一的巨大石門。\n他向身後望去，階梯在幾節之後便是斷崖，底下是黑暗的深淵。於是勇者柯林只能繼續前進。但穿過石柱後，他忽然覺得周圍不一樣了……他感受到目光，彷彿被無數雙眼睛看著，但身旁空無一人。突然間，他發瘋似的想逃離這個地方，他決定向前跑去，哪怕是手腳並用，他也想爬上那些巨大的階梯……因為他剛才掃視四周時，理所當然地回頭看了一眼，卻突然發覺那些目光恰恰是來自身後的黑暗深淵。他的每一根毛髮都豎立著，催促他逃離這裡。\n他一口氣爬上十幾層的巨大石階，完全不覺得累。但他注意到這些階梯不太尋常，它們越往上就越寬、越高。\n他來到殘破的石門前，只見石門上雕刻著奇異的生物，有著巨大的眼睛與觸手。\n他不禁顫慄起來，或許是恐懼，也或許是興奮。他感到自己的內心正催促他繼續前進，便從石門邊堆疊的碎石往上爬。攀上石門後，他愣住了。綿延不見盡頭的海底平原上，是一座巨大王國的毀滅殘骸……\n他突然想到了一個問題。他最初所見的階梯明明是正常人的尺寸，但當他一步步走向這座巨大的王國，攀爬那些巨大階梯，每登上一層，總是無可避免地必須趴俯下去。即使人們曾經朝拜的那座王國已經消失，渺小的人仍然只能跪服……\n他再次感受到了身後的目光，猛然回頭望去……但當他再次清醒過來時，他發現自己躺在沙灘上，清涼的海浪湧來，讓他確信自己這次並非身處夢境。他起身查看四周，除了海灘上留有詭異的拖痕之外，沒有任何異常。\n他忽然想起最後在海中見到的東西，那是一隻長有灰白色觸手的巨大怪物。",
  str_dispatch_book_chaptercont_9000_4 = "突然一隻巨大的觸手從水中升起，攀住了船舷，整艘船開始傾斜。船員全都嚇破了膽，只有勇敢的勇者柯林拿起斧頭，朝著觸手砍了下去；武者見狀立即拔刀衝上去幫忙。兩人接連劈了好幾下，那隻觸手才徹底斷掉。\n驚恐萬分的船員趕緊升起帆，不敢在海上久留。但船還沒靠岸，海面就翻騰了起來……起初，眾人以為從海中浮出的是黑如泥潭的礁石，但當它繼續升起，眾人才發現那些礁石般的東西長得比較像肉瘤。幸好過了一會，這東西便不再上浮。\n勇者柯林感到一陣眩暈，不自覺想起自己在深海王國時，在那道殘破的門上看過的怪物雕刻。他的直覺告訴他，那石門上刻的東西就是這海裡的怪物。但他並不知道，在遠古的海圖裡，這種生物稱為「哈弗加」。\n折騰一番後，古船阿爾戈號終於順利靠岸，眾人連忙逃下船，打算先爬上山崖。\n爬到半山腰時，有人聽到勇者柯林喃喃自語。\n「深海的怪物有兩隻……」他說。\n始終擔心著柯林的武者實在不耐煩了，一把拉住他問：「你說什麼？」\n「能夠同時襲擊十艘艦船的怪物……顯然這隻新出現的黑色怪物更符合描述。」柯林並未望向武者，他那出神的眼中似乎看到了什麼別的東西。\n「有兩隻？」眾人先是愣住，隨後恍然大悟。他們最初遇見的海怪，觸手呈灰白色；剛才攀上古船阿爾戈號船舷的，觸手也是灰白色，但後來那隻浮上海面，長著礁石般肉瘤的怪物，卻是黑色的。\n「難道傳聞有誤，這並不是卡拉肯？」武者想了半天，得出結論。\n「你們有看過一種叫做『章魚』的生物嗎？」勇者柯林似乎回過神來，繼而問道。\n「沒有，那是什麼？」有人問。\n「我聽說過！牠根本不是魚，還長著罪惡的眼睛。」有人回答。\n「傳說中，牠是一種十分具有迷惑性的生物。」有人補充道。\n「我父親曾捕過一隻，但是牠逃走了……那隻灰白色的深海怪物，跟章魚很像。」勇者十分相信自己的判斷，「但牠還沒大到能讓一座島或十艘船，在一夜之間消失無蹤。」\n實際上，這隻正在逐漸上浮的怪物顯然要大得多……隨著越來越多的巨大氣泡翻起，環形海浪越升越高，海面上逐漸浮起了一座小山。那座小山似乎失去了不少原有的東西，植被與泥土都消失在水中，只剩光禿禿的石頭裸露在外。\n等到勇者一行人到達高崖，向下望去時，海中的那座山已經完全浮出水面，隨後巨大的黑色觸手升起，掀起更大的海浪，將原本停靠在岸邊的阿爾戈號沖到被浪淹沒的山林當中。\n「這不可能，我們怎麼討伐得了這種怪物？」眾人驚恐萬分。\n「古船阿爾戈號、寶物黃金眼，根據那張藏寶圖，現在我們只差最後的神器——冥海三叉戟。只要找到它，我們就有機會擊敗在海中作祟的怪物。」勇者柯林堅定地回答。",
  str_dispatch_book_chaptercont_10000_1 = "一、以大元帥為榜樣。\n引用一句啟光大元帥常說的話，「步履鏗鏘，唯勇毅者篤行」。\n身為啟光聯邦的領袖與軍中的絕對精神核心，啟光大元帥無疑是所有啟光人的學習榜樣與典範。啟光大元帥教導眾人視彼此為家人，領導大家團結一致、堅定理想、遵守紀律。啟光大元帥對每一位啟光人都如同春天般溫暖可靠，散發著光與愛。而每一位與啟光聯邦為敵的人，則會被啟光聯邦的強大武力所殲滅。\n如果你的人生需要信仰和偶像，那麼啟光大元帥無疑是你最好的選擇。\n\n二、為了啟明之光，忠於職責，問心無愧。\n身為抵抗暗鬼侵略的最前線，身為舊文明的挖掘者和保護者，每一名啟光聯邦士兵都必須清楚自己身上所肩負的重擔：\n1.消滅所有威脅光靈生存的暗鬼；\n2.盡其所能挖掘舊文明科技，研究、利用並推動技術革新；\n3.最終重現光靈的輝煌與這片大陸的繁榮。\n\n三、擁抱榮耀與正義。\n啟光聯邦與其他勢力最不同的一點是，我們身負為全體光靈戰鬥的榮耀，也懷著善惡分明的正義。而確保此信條的人，則是涅墨西斯監察長所率領的憲兵部隊。\n他們是啟光聯邦軍紀的監督者，也是啟光聯邦信仰的捍衛者。如果涅墨西斯監察長對你投來質疑的眼神，我建議你還是乖乖立正接受檢查，不要刺激這位堅守原則的正義執行者。當然，如果你也是正義的捍衛者，並感激監察長的幫助，那麼你也能成為她正義的夥伴。",
  str_dispatch_book_chaptercont_10000_2 = "一、服從，但人人平等。\n軍階和職位，在啟光聯邦當中決定了長官與下屬的關係，但這並不代表長官擁有特權！這也是白夜與啟光聯邦本質上的差異——在啟光聯邦中，「人人平等」是最重要的鐵律！每一位啟光人不光是你的戰友，更是你的家人。無論身世，只要你認同啟光聯邦的價值觀念，就能經考核成為啟光聯邦重要的一份子！\n\n二、隨時警戒，確保裝備正常。\n所有啟光聯邦士兵必須隨時確保自己的裝備能夠正常使用。包括但不限於每日保養動能槍、檢查裝甲狀態、隨時保持劍刃鋒利。不僅因為迦南城是對抗暗鬼的核心力量，必須應對隨時來襲的暗鬼大軍，更是因為如果被教官抓到你整備不足，絕對會被他丟進遠比暗鬼還要恐怖的特訓地獄當中。\n\n三、技術優先。\n最初的迦南軍民，是白夜城下令移居至此的平民，以及光靈與亞人族的混血後代。起初，白夜城的統治者將此地作為吸引暗鬼的誘餌，只提供極其有限的支援。那時的迦南城軍民面臨著來自白夜城、極端環境和暗鬼所帶來的諸多嚴峻考驗。\n在如此惡劣的情況下，我們並沒有退縮，而是靠著科學家的不懈努力與奉獻，將迦南地下城遺留的舊文明技術結合了光能術，創造出足以抵抗暗鬼的光能科技裝備。如今的迦南城，在科技與工業方面已經遠遠超過了其他勢力，甚至擁有不遜於白夜城的尖端科技。\n因此在迦南城，科學家是備受尊重的職業。遇到特殊情況時，啟光聯邦士兵必須優先疏散科研人員和平民。極端情況下，保護科研人員與重要技術裝備則是最優先任務。",
  str_dispatch_book_chaptercont_10000_3 = "一、軍事優先。\n不要將「迦南城」視為地下避難所，而應視為一座堡壘。迦南城是承擔整片大陸對抗暗鬼的基地，一切都必須優先保證軍務正常運作。以「迦南城」為樣板，整個啟光也必須秉持這種理念——以軍事為優先考量。若是內政、民生、外交、科研等方面，有某些事項與軍事行動產生衝突，那麼無條件以軍事行動為優先考量。\n\n二、崇尚科學。\n必須銘記，當「迦南城」遭到暗鬼圍攻時，不會有人拯救我們。唯有研究此地遺留的知識，我們才能夠找到大規模提升光靈戰鬥力的方法，也就是「光能科技」。\n正因為有了科學，我們才能擊退暗鬼，改善「迦南城」，並用科技武裝士兵，用科技養活人民；科學正是我們擊敗遠古混沌、中古愚昧的利器，它所帶來的理性、務實，將引領我們實現最終目標。\n\n三、集體主義。\n「一箭易斷，三箭難折」。我們是社會性種族，沒有人可以單獨活下來，在面對各種惡劣環境時，你能依賴的只有集體，也只有集體才值得你依賴。當你獨自行走在陌生的小鎮，保護你的不是別的，正是啟光聯邦這個龐大的集體。因此，不要問「集體為你做了什麼」，而是要先自問「你為集體做了什麼」。\n\n四、理性務實。\n儘管我們是擁有情感的生物，然而支撐我們生存的乃是實實在在的物質，因此我們無法拋開現實而泛泛空談。科學是啟光得以形成的基礎，而科學的前提便是理性。胡亂的猜測、愚昧的迷信、自大的妄想，都是理性的死敵，只會將人引入深淵，唯有理性才能讓我們隨時保持清醒，面對現實。",
  str_dispatch_book_chaptercont_10000_4 = "一、維護啟光聯邦利益。\n在過去的歲月中，唯有啟光聯邦站在對抗暗鬼威脅的最前線，而啟光聯邦也終將帶領所有光靈消滅暗鬼，讓大陸永享和平。為了實現最終目標，必須壯大啟光聯邦，因此所有成員都有責任維護啟光聯邦的利益，尤其在涉及核心利益時，萬萬不可退縮。\n\n二、維護軍事利益。\n「真理只在軍事打擊的有效範圍內。」不要被眼前和平的景象蒙蔽了雙眼，在這片大陸上，城邦之間的主從地位由軍事力量決定。啟光聯邦由軍隊崛起，以軍事力量維護了聯邦內諸多市鎮的關係。因此，一定要警惕擁有強大軍事力量的城邦。無論當下態度如何，那些城邦必成為啟光聯邦的威脅，任何時候都要維護一切與軍事有關的利益，無論是直接還是間接。當然，這樣做的前提是不與準則一衝突。\n\n三、維護「迦南城」的利益。\n「迦南城」是啟光聯邦的核心，也是啟光聯邦的最後防線，更是大陸對抗暗鬼的最後基地。保衛「迦南城」、維護「迦南城」、發展「迦南城」是每一位啟光人應隨時銘記的信條。當然，在維護「迦南城」的利益時，不能與準則一、準則二衝突。\n\n四、維護科研團體的利益。\n發展科技、研究科學原理的是精良的科研團隊。身為受過高等教育的成員，每一名科研者的生命都彌足珍貴。在不與準則一、準則二、準則三衝突的情況下，應以科研團隊的利益為先，即便不屬於同一個部門，在必要情況下，啟光人也可以遵守科研人員的命令，去執行某些特殊任務。\n\n五、維護集體利益。\n只要條件允許，任何啟光人都應該集體行動，即便是臨時成立的集體。在不違反前述四條準則的情況下，都必須以所屬集體的利益為先，個人利益為後。",
  str_dispatch_book_chaptercont_10000_5 = "一、遵守時間。\n啟光人必須要有時間觀念。在日常生活中，大小事務均有計劃，前後流程彼此影響。一旦你因故延遲，就會拖累其他人的工作，因此在任何情況下，都必須遵守時間。\n\n二、求實坦誠。\n在啟光聯邦這個集體中，沒有謊言的容身之處。無論出於任何目的，謊言一旦產生，最後的真相就一定會對某人造成傷害，令集體利益蒙受損失，甚至會造成不可挽回的後果。保持坦誠，實事求是，是每一名啟光人必須遵守的條例。\n\n三、聽從指揮。\n每一名啟光人必須聽從指揮，就像手臂必須聽從大腦的指令一般。上級的決策必須堅定執行，不能打任何折扣，更不能拒絕執行，甚至違反命令。\n\n四、學習知識\n科學沒有止境，知識也沒有止境。啟光聯邦每分每秒都在進行科技革新。每一名啟光人都必須學​​習新知識，以適應新的環境。無需擔心根基淺薄、天賦欠佳，只要不斷學習，便是一名稱職的啟光人。\n\n五、堅持鍛鍊\n每一名啟光人的身體都不完全屬於自己，而是屬於啟光聯邦。因此，保持健康也是在維護啟光聯邦的利益。堅持鍛鍊，增強體魄，拒絕沉溺於無意義的享樂，是每一名啟光人必須隨時銘記的準則。",
  str_dispatch_book_chaptercont_11000_1 = "艾達時常做夢。夢境籠罩著薄紗，輕輕撕開，能看到兩道纖細的人影。\n他們小心翼翼地將懷裡的孩子放進嬰兒床。風吹進窗口，將他們的身影吹散，只剩下簡短的話語：「爸爸媽媽要離開了，去外面的世界。」\n隨著艾達逐漸長大，這個夢境變得越來越清晰。她看到了媽媽柔順的棕色髮絲，看到了爸爸長滿鬍渣的下巴。他們也離開得一次比一次決絕，離開時，身體總會融化進奇妙的光影當中。那種光芒，艾達十分熟悉，只要抬頭看向夜空就會知道，那是極光的色彩。\n「外面的世界長什麼樣呢？如果我也能像他們一樣駕駛巨像，是不是就能離開空之山谷了？」——艾達這樣期待著。\n某一天，她的願望得到了回應。她聽到了來自空之山谷深處的聲音。\n「巨像就是為了天空而誕生的，雖然也有陸地型號，還有適用於海洋的型號，但是天空才是巨像的歸宿！」\n「那些大個子巨像又蠢又笨，明明拍拍翅膀就能飛到很高的地方，卻總是在空谷附近徘徊，一點野心都沒有。要是我的話，我一定會飛到極光的盡頭！我……我才沒有羨慕……」\n「真好啊……有導航員到底是什麼樣的感覺啊……」\n「有導航員，應該就是交到朋友的感覺吧。」艾達輕聲回答。\n「嚇！是誰！？為什麼能跟我對話……」停靠在空谷深處的矮小巨像被嚇了一跳，她的指示燈顫抖地閃爍。「難道是幽靈！？空之山谷的怪談！？總不會是有空裔來到這座廢棄巨像停靠場吧，那也太奇怪了。」\n「但妳眼前就是一名空裔。」艾達靈巧地跳到小龍形狀的巨像頭上，腳底神奇的質感讓她忍不住踩了又踩。\n「喂喂喂，空裔就可以偷聽人家的悄悄話，見面第一眼就亂踩人家的頭嗎？我漂亮的頭可不是誰都能碰的。」\n「是很漂亮，上面還開了可愛的小花。」\n「……人家是很可愛啦……所以空裔，妳突然回應我的話是想幹嘛？要是敢惡作劇，我一定拼盡我最後的能源吸一大口氣，把妳吹上天去。」\n「妳也想飛到天上去吧？」艾達邀請眼前的巨像，「我一直想去空谷外看看，要不要一起去？」\n然而巨像卻沒有接受，只是默默縮了縮身體。\n「雖然我是很想去啦，但我的體型小、儲存空間也小、就連翅膀都小小的……根本沒有飛出空谷的能力……我做不到吧……」\n「但是妳想去。」艾達向巨像伸出了手。那一瞬間，一種奇妙的感覺將艾達與巨像連接在一起——「感應」。\n巨像感覺自己拍動起翅膀，飛向高空，像是躍出水面的鯨魚終於看到了海平面以上的世界。她們迎風而行，在天空輕輕觸碰星辰與極光。\n廣闊的世界在她們面前緩緩展開。\n「那麼，我叫艾達，妳叫什麼名字？」\n「臨空飛翔，迎風而行，我的名字叫風行者。」",
  str_dispatch_book_chaptercont_11000_2 = "破破爛爛的風行者和新手導航員艾達，漫無目的地在空中遊蕩。一道小小的上升氣流將兩人顛得人仰馬翻，再加上能源逐漸耗盡，她們不得不緊急迫降。\n「啊，這種隨隨便便就開始的旅行，最後都會是這個結果。身體完全陷進土裡了……我果然不擅長飛行！！不……等一下，妳看起來也不擅長指揮的樣子啊！」風行者透過意識與艾達對話。\n艾達揉了揉腦袋。在剛剛的顛簸中，她直接撞上了操作台，現在腦袋右側還在隱隱作痛。但她一臉不在意的樣子。「我確實不擅長，巨像感應的課我一堂都沒上過，因為我沒有監護人。」\n「什、什麼？那妳到底哪來的自信直接與我建立感應啊！！」\n「嗯……憑直覺吧。」她輕巧地站起身來，「但妳可以相信我，我覺得我還滿有天賦的。」\n「妳這傢伙居然比我還自戀，不過也挺有魅力的……但，我絕對不要再起飛了，我寧願被埋在土裡，也不要在空中被撞個稀巴爛。我就應該在巨像停靠場等著被拆解，而不是在這個詭異的地方遇到這些……這裡看起來好陰冷！好潮濕！還有奇奇怪怪的菇菇……」\n「似乎還有不速之客呢——」\n一大堆手持武器的「動物」從四面八方圍了上來，紛紛衝向艾達。 \n風行者緊張地閉上雙眼。無法戰鬥的空裔柔弱得就像小蝦米，艾達絕對會被這些可怕的動物撕成碎片！她體內的「光能」顫動，問題像泡泡一樣在機械線路中炸開。她一直是個膽小鬼，無法好好飛行，也沒有辦法幫上她的導航員，甚至當導航員遇到危險時，她連睜開眼睛的勇氣都沒有。她好想哭，但巨像這樣的機械造物也會流淚嗎？\n然而艾達的聲音傳來：「別害怕，風行者，問題解決了。我們沒有受到任何傷害。」\n風行者睜開眼，看到了這樣一幅景象：艾達懷裡抱著一隻貓，腳邊仰躺著各式各樣的小動物。 \n「空裔都不擅長戰鬥，但我卻很擅長打架。牠們衝過來的時候，我一下便把牠們撂倒，還摸了牠們白白的肚子。果然小動物都沒辦法抗拒呢。」\n此時，艾達懷裡的小貓說話了。\n「無禮！我們可不是小動物，而是亞人！妳們剛才壓死了我們這裡最珍貴的『珍珠菇菇』，理論上是要賠償我們一千萬的。但是看在妳的按摩手法實在不錯……就勉強讓妳用勞動來還債！」\n「亞人？」艾達疑惑地望著懷裡的貓。\n「喵嗚，沒見過世面的傢伙。空裔能看見光的通路；光靈看不見光的通路，卻能使用光能力。」小貓伸了個懶腰。\n「那亞人呢？」\n「亞人能夠用語言交流，體格強健，但和光沒什麼緣分——再多抓一下那邊——我們最大的優點是……」\n「可愛喵。」",
  str_dispatch_book_chaptercont_11000_3 = "沒有目標的旅行就像蒲公英，被風吹到哪裡，就會在哪裡生根。\n這一次，艾達與風行者停靠的地方是一片荒蕪的廢墟，她們在這裡遇到了來自空谷的同胞——一座開滿花的巨像。\n「他看起來奄奄一息，馬上就要耗盡能源了。」艾達輕輕撫摸著年老的巨像，巨像輕輕顫動，像空裔一樣呼出了空氣。\n「怎、怎麼會這樣？為什麼不起飛呢？飛回空之山谷的話，一定能找到修復的辦法。」風行者十分不解。\n「因為，我已經找不到飛回空之山谷的路了。地圖、導航，都無法將我從迷途中拉回……」開滿花的巨像緩緩睜開眼睛，「不如說，我已經在這個地方紮根了。」\n艾達坐到巨像的面前。\n「可以說說你的故事嗎？」\n那體型龐大的巨像揚起了頭顱。「我與我的導航員一起來到了這片森林，我們在這裡遇到與空裔不同的種族——光靈。」\n「啊，是那種能使用光能力的種族！動一動腦子，掌心就能冒出水流。」\n「哼，那有什麼了不起的？她們能飛嗎？妳要是有心羨慕，應該先羨慕一下我們巨像吧。」風行者嘟囔著，並沒有把光靈放在眼裡。\n「我的導航員與光靈一同生活，也被光靈接納，但他依然感到孤寂。光靈與空裔仍舊不同，這裡並不是他的家。然而，就在他準備離開時，暗鬼襲擊了光靈的村落。」\n「暗鬼！」艾達心神震顫，一瞬間她的眼前出現了令人膽寒的影像。灰黑色的怪物身影從黑暗中浮現，張牙舞爪，渾身沾滿鮮血，以極快的速度向艾達衝來。就在利刃即將劃開她的喉嚨前，影像中斷。\n「我的導航員為了幫助這裡的光靈，犧牲了自己。他們最終獲得了慘烈的勝利，但這片居住地徹底遭到暗能污染，再也無法居住。一切結束後，那些被他保護的光靈回到了這裡，為我的導航員獻上花束，這些花朵如今正紮根在我身上，慢慢長大。」 \n艾達和風行者號沉默不語，她們想安慰這座巨像，卻不知道該說什麼。\n「不要難過，孩子們。我從不嫌棄自己身上開滿的花，也從不後悔在這裡慢慢等待能源耗盡的日子，因為我能感覺到無限的生命力正在我的身體上慢慢甦醒。這片燦爛的花海是那些光靈對導航員的感激，也是我對他的祭奠。」\n這座巨像終於閉上了眼睛，切斷了與艾達的感應。\n廢墟之中只有這一片花海搖曳。艾達想起了自己的父母，也想起了空谷。她喃喃自語道：「去看外面的世界一定是正確的嗎？又或者去看外面的世界是……錯誤的嗎？」",
  str_dispatch_book_chaptercont_11000_4 = "「沙子，到處都是沙子！如果停在這裡，我的外殼一定會變得髒兮兮的……嘶，而且沙子好燙！」\n艾達與風行者號飛行到一片沙漠，在這裡停靠整頓。\n「辛苦了，風行者。但看看眼前吧，這都多虧了妳！」\n灼熱的太陽高掛在天上，熱氣蒸騰。沙丘此起彼落，向遠處延伸。即使是巨像，在沙漠中也不過是一粒小小的白色石子。倘若不離開空之山谷，永遠無法見到這樣的景象。\n「多虧了我……確、確實是這樣！我還真是了不起的巨像！沙漠原來長這樣啊！不過附近一個人都沒有。」\n「但遠處好像有什麼東西？」\n原本安靜的沙漠，霎時躁動起來。\n「是……一艘船？而且正朝著我們衝過來！！要撞上了！」\n可憐的風行者自從踏上這場旅途就沒好受過，如今還被一艘行駛在沙漠裡的船迎面撞上。\n「好痛！！！！」風行者大叫。行船結結實實地撞上了她的翅膀。\n行船的主人摸著頭，從船上搖搖晃晃走了下來。\n「妳們好——完了，剛才那一下撞得還真狠——我是星之旅團的團長，初次見面。我們是流浪的光靈，駕駛風船到處旅行，探索世上的奧妙。」\n「我記得書上說船都是在海上航行……沙漠裡怎麼會有船？」艾達疑惑地看著船長。\n「沙漠中當然沒有船，但這裡會有。妳們看。」\n艾達順著團長手指的方向低頭看去。她腳下的沙子被風吹散開來，露出了一片完整的「天空」。更神奇的是，她們在這天幕般的地面中，看到了一顆奇妙的星球。\n「這就是我們的世界，艾歐里亞。」星之旅團的團長說道。\n「好像泡在水裡被掰碎的餅乾。」風行者小聲說道。\n「確實，至於那塊餅乾，就是妳們的艾斯特拉。這個奇妙的世界，一邊是永恆的極晝，另一邊則是無盡的極夜，我們在一條細細的夾縫中生存。」\n「探索世界的奧祕，就憑這條破破爛爛的船嗎？」\n星之旅團的團長抓抓頭說：「妳別看船外表破破爛爛的，內裝可是相當豪華。而且我們擁有最優秀的船員，妳看我們的修理工——」。船上的光靈揮了揮鎚子，似乎想展示些什麼，沒想到一下把船身打破了一個洞。至於另一位光靈，似乎本來想從船上瀟灑地一躍而下，卻一頭栽進了沙子裡。\n「丟臉的傢伙。」星之旅團的團長絕望地仰起頭，但他還是很快調整好了心態。「開闢嶄新的道路，探索未知的一切，這就是我們在做的事。」\n「光靈都這麼奇妙的嗎？」\n「正常人的話，應該不會在沙子裡開船吧。」\n「沙子？」艾達低下頭，她腳下的星河不知何時又重新被掩蓋了起來，變回細細的沙子。而當她再抬起頭，那艘船也消失得無影無蹤。\n星之旅團，是夢境還是真實存在的呢？",
  str_dispatch_book_chaptercont_11000_5 = "艾達坐在碧空島邊緣，風行者掩藏在雲霧之中。\n時間悄然流逝，她們已經離開空之山谷很久了。一天、一個月、一年——也可能是好幾年。空之山谷的模樣，在艾達的記憶中逐漸模糊。\n「風行者，妳還記得空之山谷長什麼樣子嗎？」\n「我可是巨像，當然什麼都記得。讓我翻一下資料……啊，奇怪……怎麼空之山谷的資料都不見了？難道是因為我儲存了太多新資訊，佔掉這些內容的空間了嗎？不會吧……那我的儲存空間也小得太離譜了……」\n「我還記得那裡有座白色的高塔——碧空島也有白色的高大建築，但是感覺還是不一樣。空谷的白塔上常常停著鳥兒，白塔下面是森林，地面好像還飛舞著蒲公英。」\n「……艾達，妳當初為什麼要與我建立感應，拉著我離開空之山谷呢？」風行者順著艾達的視線望向遠方。沙漠、平原、雪原、火山，甚至是海洋，似乎都能從這裡隱約看見。如果不離開空谷就看不到這些；但離開了空谷，腦海中似乎就只剩下這些了。\n「那時我總想找到夢中的那兩個人……我的父母親。我……看起來好像很灑脫，但那只是因為，我覺得自己在空谷的生活爛透了，不管到哪裡似乎都比待在那裡好。父母離開空谷不要我了，我也無法融入其他人的生活，整天就孤孤單單的一個人，爛透了。」\n「……我也一樣。我從甦醒開始就不是一座完整的巨像，聽說我似乎是失敗品，永遠也飛不起來。我唯一的結局，似乎就是躺在那座巨像垃圾場裡，等待能源一點點耗盡。能飛出垃圾場，至少比一直待在那裡好吧。但奇怪的是，我現在還滿想念那個破爛的地方……」\n「我也是……不知道從什麼時候開始，我好像不那麼在意找尋他們的事情了。他們一定有自己的生活，而我也應該有我的生活。和妳一起飛翔，比尋找那些虛無縹緲的東西有意思多了。」\n「妳妳妳——妳這是在告白嗎！？我還沒做好心理準備……我可是巨像欸？巨像可以接受空裔的告白嗎？哇，我的資料庫裡根本沒有這種事情的資訊！！」\n「告白這種說法也太膚淺。我們是夥伴，心靈彼此連結，我想這是某種更深刻的關係。」艾達閉上了眼睛，她在操縱她的感應。「妳有感受到嗎？」\n「……我、我感受到了。我還察覺到了妳的想法，艾達，妳是想……」\n「空之山谷。我想，是時候回到我們相遇的地方了……」\n趁那些記憶，還沒消逝之前。",
  str_dispatch_book_chaptercont_12000_1 = "我曾多次坐在金河畔，看太陽在空中緩緩移動。\n冰冷的河水拍在小腿上，我感到胃一陣痙攣。希菲的父親在河裡捕魚，漁網勒進他的虎口。他對我們笑時，常把手藏在背後，但我知道他的掌心凝結著褐色的血痂。\n希菲赤著腳在河岸邊奔跑，她把撿到的小河蚌堆在我身旁，吩咐我用小刀撬開，剜出裡面的肉。而她則蹚著河水，清洗腳板被礫石劃出的傷口。\n日光永無止境地照耀著我們。\n一天中最難熬的時刻莫過於去希菲家吃飯。我總要控制好用餐速度，以免在希菲之前或之後吃完，無論前後，我都會覺得自己不禮貌。\n希菲的母親很善良，常常讓我拿走一些食物，像是魚乾、燻肉，帶給我那個終日醉醺醺的父親。\n「要是明娜的母親還活著，就好了。」\n希菲的母親總愛用手指把我亂糟糟的頭髮梳到腦後，當她用疲倦的眼神看向我時，像遠遠地望著另一個人。\n母親生前一定和她很要好，就像我和希菲一樣。\n我和父親依靠母親留下的這點恩情在世上存活。\n父親很怕我看見他喝酒。我進家門時，他總離得很遠，但空氣中彌漫的酒酸味藏不住。他大聲指揮我把食物放在跛腿的木桌上，又使喚我去洗衣服。等他睡著後，我會開始在屋子裡尋找他藏起來的酒瓶。\n床底下、衣服堆、爐火的灰燼中……我總能在意想不到的地方搜出酒瓶。\n我用河水把瓶子沖乾淨，再用編漁網的繩子緊緊束住瓶口，十個一串地串起來，在臥室窗戶的左右兩側釘下兩根釘子，把酒瓶成串地掛在上面，迎著天空，每隻酒瓶上都凝結著一枚白色的明亮太陽。玻璃相碰，當啷啷清脆地響。\n在那天到來以前，這是我僅有的樂趣。\n（待續）",
  str_dispatch_book_chaptercont_12000_2 = "我至今還記得那是個陰天。淅淅的風捲起落葉與灰塵，在天空盤旋。\n馬鈴鐺遙遠地響起，小孩子伏在地上，把耳朵貼近地面，聽見陣陣混沌的馬蹄聲。是商隊。他們在村莊外一片長草的空地上駐足，扯開白色的布，搭出一道遮陽的長廊，把貨物全從馬背上卸下，在長廊裡擺成一排。\n聽到動靜，許多村民都聚集到商隊歇息的空地上，伸長脖子張望。我和希菲也擠在人群中，她把我的手捏得很緊，緊張與興奮順著我的皮膚和骨骼蔓延到心臟。\n空氣中散發著乾燥的馬糞味。商隊裡有人走出來，和幾名大膽的年輕光靈交談。他們衣著光鮮，即便歷經長途跋涉，臉上仍然乾淨且神采奕奕。當時，我並不知道那得益於光能術。\n消息很快就傳開了：村民們可以用黃豆、麥麩、毛料和鹿角等物品交換成衣與啤酒。商隊的人還走進村莊，光顧了半年不曾開張的旅店。很快地，煮豌豆的香味從旅館裡四溢出來。\n叫賣成衣的商人把衣物挽在臂彎裡，扯開布料，展示給圍觀的村民看。米白、孔雀綠、寶石藍、落日紅……那時，我第一次見識到如此斑斕的色彩。\n希菲告訴我，她想用上個冬天獵到的狼皮換一件粉白色的長裙。\n於是，我想起掛在窗戶上的玻璃酒瓶。\n「無論如何，也要試著去換點東西。」我悄聲對自己說。",
  str_dispatch_book_chaptercont_12000_3 = "我和希菲各自回到家中，她拿來狼皮，緊緊捲成一捆，夾在腋下。我兩手拎著一掛酒瓶，隨著我的步伐，酒瓶叮叮當當愉快地響。我們手裡拿的都是各自的珍愛之物。\n希菲走得很快，她幾乎朝商隊的方向撲過去了。但酒瓶沉重易碎，我在後面慢慢跟著，只覺得人人都投來目光。我從未受過這麼多的注目，心裡一時很高興。\n「妳要用這些換什麼？」走到商人跟前，他困惑地打量我。\n我沒聽懂他的言外之意，只是急切地伸長脖子，目光一遍又一遍地掃過他身後琳瑯滿目的商品。\n「我們不收酒瓶。」他乾脆把話說明，末了，又補問一句，「那些只是普通的酒瓶吧？」\n那一刻，我懷疑自己瞬間患了耳鳴。巨大沉重的困窘把我釘在原地，頭頂的太陽彷彿擊鼓般震響，手中酒瓶叮當相撞，對我來說，這聲音也變得無法忍受。\n酒瓶過於沉重，我拎著繩子的手開始發抖，頸子與耳朵後也沁出汗來，但腳仍不聽使喚，無法挪動一步。\n忽然，一個低沉的聲音在我右方響起：\n「孩子，妳想用這些酒瓶換什麼？」\n（待續）",
  str_dispatch_book_chaptercont_12000_4 = "那是我和夏佐初次見面。他身上銀白色的板甲反射日光，亮得刺眼。\n彼時，夏佐三十多歲，被商隊雇用，隨行保護商人以及財產安全。他摘下頭盔，褐色的額髮汗涔涔的，下半臉蓄滿刺蝟似的鬍鬚。他對著我笑了一下，藏在鬍鬚裡的嘴露出一排皎潔的牙齒。\n他指明要我手中的酒瓶，並用一種叫「白夜餐餅」的白麵包交換，我牽起裙角，用裙布把餐餅收攏起來。他特地告訴我那是白夜城士兵專用的口糧。\n我一定換到了不起的東西！我這麼想，先前的困窘煙消雲散。\n而後，他從繩子上取下一隻酒瓶，握在掌心。一團透明、扭曲的熱浪膨脹開來，籠罩著他握住酒瓶的手，比太陽更灼熱。酒瓶在他掌心慢慢收縮、扭動，變換各種形狀。\n「妳喜歡小狗嗎？我小時候很喜歡。」\n夏佐向我攤開手掌，一隻晶瑩剔透的玻璃小狗蹲在他掌心。\n相較玻璃小狗，我更在意那團憑空出現的熱浪。而他顯然也看出了我興趣所在，熱心地告訴我：\n「那是光能術，想學嗎？」\n商隊在此停留了三天，在我眼裡，整個村莊像是重新活了過來。炊煙中混雜著燉肉的香氣，小孩子赤著腳在路上追逐、老者拄著拐杖走出昏暗的房屋，連金河的水都似乎不再像往常那樣冰冷。夏佐常常坐在村莊中央的高台上，教我光能術。希菲則坐在我身邊，時而用心地跟著學，時而依著我打瞌睡。\n夏佐喜歡飯後在村莊裡閒逛，我和希菲就跟在他身後。他幾乎沒有脫下過那身鎧甲，也不曾卸下背上的盾與腰間的劍。我上前兩步，敲他背後繪著花紋的盾牌，問他那是什麼。\n「箏形盾」，他告訴我，「白夜城騎士團的標誌。」\n於是，我得知他來自白夜城騎士團。\n三天後，商隊離開村莊，夏佐也向我們告別。\n一個月後，我的掌心終於能凝結起拳頭大小的水團。\n從此，我獲得了新的命運。",
  str_dispatch_book_chaptercont_12000_5 = "夏佐離開後的第三個月，有人敲響了我的窗戶：\n「請問，這裡是明娜的家嗎？」\n一張紅潤的臉頰貼在窗戶上，鉑金色的頭髮結成兩束小辮子，翹在腦後。她看到我，橄欖綠色的眼睛飛快地眨了兩下，又別過頭去，從身後的背包中取出一本棕色皮革封面的小冊子。她身後背著一對翅膀，翠綠而油亮的翅羽在太陽下光澤流動。她對我舉起那本小冊子，用長著尖尖指甲的手指按住上面懸掛的一枚徽章，一字一字慢慢地說：\n「信使公會。」\n確認我是她要找的人後，她塞給我一個用防水紙裹住的包裹，接著退後兩步，身後翅膀驀然展開，風與砂礫被捲起。她笑著對我揮了揮手，翅膀帶著她在空中轉了個圈，霎那間便消失在我的視線裡。\n拆開包裹，是夏佐寄來的信與禮物。信寫得很短，後來我學了認字與書寫後，才發覺那封信錯誤百出。禮物是一朵蒲公英標本，纖細的莖上撐著一球白絨，被六邊形稜柱狀的透明樹膠裹住。很久以後，我才得知那朵蒲公英來自遙遠的空谷。\n此後，夏佐又陸陸續續寄來幾次包裹，裡面的禮物各異，有北境的烤腸與伯利恆女王的小型木雕像、刻著啟光雙星標誌的子彈、能吹出哨聲的光能哨糖，還有口味奇特的嘎嘣脆油炸酥，有一次他甚至在包裹裡放了一顆暗鬼的眼珠。\n每次送信來的信使都不同，但他們無一例外，或多或少帶有一些亞人特徵，比如翅膀與鹿角、布滿花斑的豹腿或突出嘴唇外的獠牙。在熟悉這種拜訪後，我嘗試著和他們多說一點話，甚至拜託他們幫我念夏佐的信。\n無論長成什麼樣，他們都是那段日子裡我最渴望見到的人。\n夏佐最後一份包裹是從白夜城寄來的，拆開後裡面掉出一幅手繪畫，畫裡是他站在一處開闊的平台上，身後是渺遠的天空。我很快就猜出畫裡的地點在白夜城。他跟我說過，白夜城建立在碧空島上，而碧空島漂浮在天空中，光靈生活在上面，迎著雲霧與清澈的陽光行走。\n此後，我就再也沒有收過夏佐的來信。\n（待續）",
  str_dispatch_book_chaptercont_12000_6 = "又在家中待了半年，我趁著父親醉酒，偷偷離家，行囊裡只裝了些許口糧，其餘空間全留給夏佐的信件與禮物。我按照信使們描述的路線，找到信使公會的驛站。\n停留在此的信使有幾位認識我，我在父親的墮落行徑上適當發揮一下，編了個謊。於是他們收留我，而我幫他們分擔分類信件等雜務。這段時間裡，我學會認字與寫作。我常拿出夏佐寫的信，反覆地閱讀，信中的文字寫得顛三倒四，但我總能理解他的意思——他不常描述自己的行程，只愛寫年少時的經歷，雖然出生在白夜城，但他年輕時的生活和我一樣窘迫難熬。我從中讀到慰藉的意思，畢竟他是白夜城的騎士，無論怎樣的苦難，最終都會變成磨礪。後來，我也開始寫信給夏佐，按照他最後一封信留的地址寄過去，可惜從未有回音。\n某天希菲和她母親進城時，偶然撞見我。\n她緊緊拉住我的手不放，號哭良久，斷斷續續地述說這些日子以來的擔憂。看到她涕泗縱橫的樣子，我不禁為自己的不告而別愧疚，又講不出什麼道歉的話，只好伸手抹去她臉頰上的淚。\n最後，希菲用袖子蹭著鼻涕，低聲說了一句：\n「妳看。」\n說完，她閉上眼睛。\n緊接著，她四周流竄起明亮刺眼的電光，瞬間撕裂空氣。",
  str_dispatch_book_chaptercont_12000_7 = "我曾經嘗試加入信使公會，但遭到他們拒絕：\n「明娜，妳年紀太小了。」\n「妳跑得不夠快。不是妳的錯，只是……僅靠光靈的雙腿永遠只能跑那麼快。」\n「當信使太危險了，一不小心就會受傷。」\n「妳有和暗鬼正面撞上過嗎？我就撞上過。」\n「而且工資很少。」\n「對，這個是最主要的。」\n即便信使這個職業有諸多缺點，他們依舊笑嘻嘻地每天出去送信。\n信使們不肯鬆口，我也只能擱置這個想法，繼續分揀信件，試圖從中找到夏佐的回信。可惜無論是加入公會，還是找到寫給我的信，我都未能如願。\n希菲學會光能術後，她父母稍微放鬆管教，任由她一個人跑進城裡找我。我們和信使常常坐在驛站前的橡樹下聊天，任橡果砸落在頭頂和肩上。\n我喜歡問信使白夜城的事情，尤其是騎士團，但得到的回答往往只有隻字片語：\n「騎士團很威風，他們使用的光能術也都很厲害。」\n「我曾送信給騎士團的光靈，她拆信的樣子比一般人都優雅。」\n末了，他們面面相覷，互相詢問：\n「你們還知道些什麼嗎？」\n「其實我也不常和他們打交道啦。」\n希菲把手撐在身後，腦袋往後仰，日光透過橡樹葉的間隙灑落在她臉上，她說：「真想親眼去看看呢。」\n不知道是不是這個瞬間，讓我下定了決心——不止白夜城，還有空谷、啟光地下城、紅油沙漠、影鎮，甚至是祕境，我都要親眼去看看。\n（待續）",
  str_dispatch_book_chaptercont_12000_8 = "或許不止是為了擺脫這片令我厭倦的土地，離開還有更多意義，伸手就可以觸摸到的，生命的意義。就像夏佐一樣，我並不是生來就該忍受單調與苦澀。\n十七歲時，我和希菲終於結伴上路了。在我的提議下，第一個目的地就定為白夜城。\n我們沿著金河溯游而上，在木舟上顛簸了半個月，才抵達白夜城附近的河灣。\n「碧空島！」\n希菲揚起手臂，指向空中。我把手搭在額前，順著她指的方向望過去。那座浮空島如一頂錐狀的圓帽，漂浮在東方的荒原上，白亮的太陽勾勒出它的輪廓，使它彷彿在發光。\n我們離它愈近，愈能感覺到它的巨大與威壓。走進它投下的陰影裡，厚重的陰寒包裹住我們。對光靈來說，陰影裡太暗太冷了。\n接駁港是唯一可以進出白夜城的港口，想要前往那裡，就必須搭乘空艇。而我與希菲甚至未能搭上空艇，就被勸離白夜城：\n「所有遊客都必須得到外交部門的核准才能進入白夜城！」\n希菲連忙問：「手續需要多久？」\n「半個月到一個月吧。」\n旅費顯然不足以支持我與希菲在此停留，甚至搭乘空艇對我們來說也是一筆過大的開銷。無奈之下，我們只能掉頭離開。\n我們商量下一個目的地，希菲忿忿地說：「要去，就去一個不需要什麼『核准』的地方！」\n於是我們下一個目的地定為北境。\n而在前往北境的路上，我們偶然獲得免費進入白夜城的機會。",
  str_dispatch_book_chaptercont_12000_9 = "從白夜城出發，向北走了將近一百公里，我們遇到一位受傷的信使，她在前往白夜城的途中遇到暗鬼。暗潮危機之後，內陸常有暗鬼遊蕩。她伏在一頭馴鹿背上，翅膀與小腿血淋淋的，鮮紅的血順著馴鹿的毛皮滴落下來。\n我和希菲把她帶往附近的驛站，其他信使用光能術治癒她的傷口。為了表示感激，她提議讓我們留在驛站歇腳兩日，之後，聽說我們進入白夜城受阻的事。\n「進入白夜城的貨物與遊客都會受到嚴格審查。」她微笑地看著我們，「但信使公會不運送貨物，也不是遊客。」\n「我們有進出白夜城的特殊許可，只需要向守衛出示身分。」\n她從手邊拿出一本小冊子——那是我在家鄉附近的驛站見過無數次的、信使們用來記錄行程的筆記本。上面掛著兩枚徽章，章面刻著一支線條流暢的羽毛筆。\n她把徽章取下，掛在我和希菲的衣襟上，一人一枚：「憑藉這個，就能暢行無阻地進出白夜城——這只是我暫時借給妳們的，可千萬不能告訴別人喔！」\n我和希菲跟隨前往白夜城的信使，坐上了公會專屬的空艇。\n離地面漸漸遠了，我的手在口袋裡暗中握住一張紙捲，那是夏佐寄給我的最後一樣東西。\n（待續）",
  str_dispatch_book_chaptercont_12000_10 = "接駁港連接的是下城區。它被描述為高潔的白夜城最混亂、嘈雜、危險的區域，但我看到它的第一眼時，我覺得他們用錯形容詞——它應該是白夜城最熱鬧、刺激、生機蓬勃的地方。\n接駁港內迎面而來的是各式酒館、咖啡廳與珠寶店，空氣中瀰漫著香料、啤酒與可可豆的香味，希菲甚至朝著街道狠狠地打了個噴嚏。光靈們手挽著手走在街上，鞋跟敲在路面的石板，織出一片連綿不絕的脆響。站在店舖前攬客的店員們也衣著光鮮，舉止從容，指間挾住的手帕彷彿衝著行人噴出濃香。\n這就是夏佐的故鄉。\n在希菲把臉貼在櫥窗上，瞪大眼睛盯著木偶頸子上的巴洛克項鍊時，我向一位坐在台階上喝啤酒的光靈打聽夏佐留給我的地址。\n「那可是貧民窟」，光靈面色微醺，鬍鬚上糊上一圈白色泡沫，他抬起眼皮打量我：「小女孩，妳去那裡做什麼？」\n我告訴他，我要去找一位騎士。\n「騎士？」他搖了搖頭，譏笑道：「那個破地方能出什麼騎士？」\n我感覺自己的表情僵硬了片刻，壓抑下心中的不安，我辯駁：「他有箏形盾，那可是騎士團專屬的裝備！」\n「箏形盾？」他在口中複述了這個名詞，我深怕他再吐出些什麼否定的話，他卻說：「那的確是騎士團的裝備。小女孩，妳在哪裡碰到他的？」\n我心裡隱約明白這對話不該進行下去，但我厭惡他傲慢的態度，便將夏佐是作何打扮、如何護送商隊，又是如何展現光能術的事情，統統說給他聽。\n「護送商隊？」他忽然大笑起來，「沒有一名騎士會自降身價去護送商隊！」",
  str_dispatch_book_chaptercont_12000_11 = "我不知道我是如何離開接駁港附近的，回過神時，希菲正拍打著我用力拽著她的手，齜牙咧嘴地喊我的名字：「明娜！妳扯得我很痛！」\n「對不起。」我急忙鬆開手。\n希菲揉著手臂，抬頭看著山上鱗次櫛比的白壁房屋，問道：「妳確定有找對地方嗎？」\n我見幾步遠處立著路標，便上前查看，這裡確實是夏佐留在信封上的地址。\n走進錯綜複雜的巷道，我們迷了路。巷道旁的房屋外牆上滿是腳印與塗鴉，腳下的路也不再是石板路，而是崎嶇不平的泥巴路。陰影裡，陌生而警戒的目光朝我們射來。希菲扯了扯我的手臂，問道：「妳為什麼不再找個人問一下確切地址？」\n不安感縈繞上我的心頭，我怕一向旁人開口，便洩露所有祕密。\n但希菲不在乎，她鎖定一位體胖的樸素婦人，湊上前，問她認不認識夏佐。\n「妳們找那個混蛋做什麼？」她嘴角一撇，鄙夷填滿她臉上每一道細紋，「妳們能替他還債嗎？如果能，我就告訴妳們他在哪。」\n希菲不解：「難道這附近還有別的叫夏佐的人？」隨後，她又熱切地向婦人描述夏佐的樣子。\n「小女孩，妳說漏了一點。」盤坐在牆角的流浪漢朝希菲舉起一根髒兮兮的指頭，衝著我們咧出殘缺不全的黃牙，「妳還要加上這句——他還有一條殘廢的左腿。」\n我一把拉走希菲快步離去。\n又向前走了片刻，我重新向路邊的光靈打聽夏佐，但他們的描述幾乎都一致：賭博欠債、盜賣白夜城騎士團的裝備、被治安隊發現、和士兵扭打、最後殘疾……\n「有一次，他喝醉酒，向我吹噓自己撿了個大便宜，我以為是什麼——竟然是騎士團的箏形盾與板甲！這不是給自己找麻煩嗎！」\n「他年輕時，就妄想加入騎士團，但騎士團標準多高，他哪夠格！」\n……\n「妳們下坡去，路的盡頭有間酒館，我常在那裡看到他。」\n最後，終於有人告訴我們夏佐的下落。\n（待續）",
  str_dispatch_book_chaptercont_12000_12 = "希菲問我：「妳還要去找嗎？」\n我繃著臉，點了點頭：「有可能……他們搞錯人。」\n我們順著坡道而下，終於看見那間破酒館。幾個高矮不一的男人倚在酒館的外牆上，腰間掛著各式各樣的工具，袖子捲到手肘，手裡端著木製啤酒杯，大聲地談天。\n一名衣衫襤褸的男人盤腿坐在牆邊，他褐色的頭髮蜷曲著，堆在頭頂，鬍鬚覆蓋了大半張臉。男人用手撐著地，身子向前傾，衝著其他人笑：「嘿，威爾，分口啤酒喝！」\n一名黑髮的強壯男人踢了他一腳，嘲笑道：「一個跛子也想喝酒？」\n褐髮男人怪叫一聲，雙手搬動著似乎沒有知覺的腿，又靠著牆坐好，但那張汙穢臉龐上的笑容仍不退去。他伸出舌頭舔了舔乾裂的嘴唇，眼睛直盯著其他人手裡的酒杯。\n希菲問我：「妳看到夏佐了嗎？我已經記不起他的模樣了。」\n我認出來了。\n但我講不出話來。\n太陽在我頭頂，那擊鼓般的震響又逼近了。我感覺身軀裡蓄著金河所有腥澀的河水，正在膨脹，正在上漲，淹過口鼻，要淹進眼睛裡來。\n「沒有。」我聽見自己說，「我們還是下次……」接下來的許諾哽在喉嚨，接著便是謊言。但希菲聽見我要放棄尋找，她很高興，牽著我的手轉身往回走，嘴裡細數著她在接駁港內見到的新奇事物。\n我們當天便離開了白夜城。\n此後，我幾乎再也未曾踏足那片浮在空中的土地。",
  str_dispatch_book_chaptercont_13000_1 = "村莊的入口立著兩座石墩，是將山上的岩石切成磚塊後，一圈一圈堆砌而成。一棵松木橫架在兩端，與石墩一起搭出一座孤零零的門。松木的枝椏沒有削砍乾淨，上面繫了五色的彩綢，隨著寒風吹動，唰唰地響。遠道而來的旅人遙遙望見這座門，便知前方有村落歇腳了。常有村中孩童在石墩上攀爬，他們會用腳卡住石縫，手攀松木枝，身子前傾，雙眼極力眺望路的盡頭。但此值天寒，石墩上結冰，摔傷了幾個孩童，村中長老便下了禁令。\n昨夜下了很厚的雪，踏出屋外，雪深及膝。長老便叫來桃樂絲和克魯斯，給姐弟倆一人一把鐵鍬，吩咐他們和其他村民一起去鏟雪。有的村民會用光能術，路上的雪大半被他們拋進旁邊的樹林。桃樂絲也會光能術，但並不適合鏟雪。她和弟弟跟在其他村民身後，用鐵鍬慢慢鏟淨石道上的碎冰。把鐵鍬還給長老時，已經傍晚了。長老照例拿了不少鯡魚罐頭給他們，又問他們家中還剩多少食物，最後還在克魯斯手中塞了一把軟糖。克魯斯把軟糖放進口袋，糖就一顆一顆從口袋的破洞掉出來。克魯斯羞赧地捂著口袋，桃樂絲則替弟弟拾起糖果。隨後，長老談到住在村莊東南角的夫婦：\n「他們盼著能有孩子住進家裡，你們年紀小，孤零零沒大人照應，正好湊一家人。」\n桃樂絲並未回應長老，只是握住弟弟口袋上的破洞，輕聲說：「以後衣服破了記得跟我說，我又不是不幫你縫。」\n長老嘆了一口氣，對他們揮了揮手。桃樂絲姐弟再次向長老道謝後，便牽著手緩緩走回家。",
  str_dispatch_book_chaptercont_13000_2 = "回家路上，又開始下起雪。天色已經暗了下來，村莊中零落地點著昏黃的燈火。眼見離家不遠了，克魯斯向前跑了幾步，不料腳下一絆，低頭查看時，發現雪地裡伏著一團黑影。桃樂絲聽到弟弟的驚叫聲，連忙趕上前。那黑影咳嗽著，似乎吃力地想爬起來。桃樂絲仔細打量一番，確定黑影是個陌生光靈後，才叫來弟弟，一人一邊，把光靈攙扶起來。環顧四周，路邊正好有堆放柴草的草棚，姐弟倆把光靈扶到草棚簷下，光靈嘶啞著向他們道謝，便倚著牆壁不再做聲。藉著不遠處的燈火，桃樂絲看見光靈的兜帽裡露出幾縷乾燥的金髮，隨著她的呼吸起伏。\n幫助陌生光靈是件不大不小的事情，姐弟倆很快就把這件事情拋諸腦後，直到第二天，消息在村裡傳開：有外鄉人來村莊定居了。桃樂絲姐弟出門鏟雪時，發現屋子旁破敗許久的老屋關上門窗，煙囪冒出一道白煙，直直地升上冰藍的天空。\n克魯斯指著老屋屋頂上的大破洞，問姐姐：「這樣的屋子也能住人嗎？」\n桃樂絲拎著他的衣領，把他拖離老屋。\n這天夜裡依舊風雪大作，姐弟倆蜷縮在被窩裡，枕著滿樹林尖嘯的風聲和劈啪的斷裂聲入睡。忽然，門外轟然巨響，緊接著又傳來一陣劈哩啪啦的聲響，似乎是什麼東西坍塌了。克魯斯在夢中打了個顫，桃樂絲猛然驚醒，抬起頭，警覺地張望。\n不久，門外漸漸歸於寂靜，只剩窗縫裡的風低聲嗚咽。桃樂絲揉揉眼睛，腦袋又落進枕頭裡。迷迷糊糊不知睡了多久，再次醒來時，是屋子的木門被敲響了。為了不吵醒弟弟，她小心翼翼地掀開被褥，踮著腳下床，點亮煤油燈，提到窗戶邊，推開一條縫，查看門外情況。只見門外一個佝僂的影子等待著，身上裹著一條薄毯，一頭捲曲的金髮被寒風撕扯著。\n桃樂絲一眼認出她，但她並不打算開門，只是提著煤油燈，把頭伸進外面冰冷的空氣裡，問道：「出了什麼事嗎？」\n金髮光靈指了指老屋的方向，說：「我的屋子塌了。請問可以借住一晚嗎？」\n桃樂絲猶豫許久，凝視著黑暗一會，說：「我覺得妳還是去找長老比較好。」\n光靈點了點頭，裹緊身上的毯子，轉身準備離開。桃樂絲忽然發現光靈赤著腳，在雪地裡印出一個個腳印。她咬牙，躊躇片刻，終於跑轉去，拉開門，壓低聲音呼喚光靈：「妳……妳還是先進來吧！」",
  str_dispatch_book_chaptercont_13000_3 = "桃樂絲得知了光靈的名字——瑪莎。瑪莎裹著毯子，在壁爐旁睡了一晚。天亮了，桃樂絲和克魯斯踏出家門，發現老屋已經塌到只剩半邊，屋頂被整個掀開，樑柱東倒西歪，磚石散落一地。\n瑪莎在廢墟裡翻找，從磚塊堆中拉出兩隻靴子，把靴筒裡的雪和木屑倒乾淨。穿好鞋，她又挪開折斷的樑木，從裡面拖出一個黑色布包。\n「要吃嗎？巧克力。」瑪莎從背包中拿出一塊包裹錫紙的糖塊，克魯斯伸手要拿，卻被桃樂絲攔住。瑪莎並不在意，她把巧克力收入包中，另外拿出一塊真空包裝的麵包，和著雪送進嘴裡，快速咀嚼著。\n瑪莎坐在廢墟上，一邊咀嚼，一邊打量著坍塌的房屋，許諾般說道：「我會儘快把房子修好。」\n桃樂絲點點頭，牽著弟弟離開了。\n長老聽聞這件事，建議桃樂絲收留瑪莎一陣子，等老屋修好她再搬出去。桃樂絲不太情願，但長老塞給她一大塊發酵鯊魚肉後，她便不好再拒絕。\n瑪莎從長老家借了一匹馬，每天都從樹林中運回石塊與木材，堆在老屋坍塌的廢墟後面。桃樂絲白天幾乎見不到瑪莎，只有中午和晚上，瑪莎才會出現在廚房和壁爐邊，做飯或睡覺。\n起初，瑪莎沒有和桃樂絲姐弟一起吃飯。她只是盤腿對著爐火，一邊發呆，一邊無聲地啃食鋸木屑麵包，時不時佐以烤肉和魚湯。桃樂絲不記得從誰先開始的，或許是瑪莎把新鮮的兔肉分給桃樂絲，又或許是克魯斯和瑪莎一起盤腿坐在爐火邊，分享軟糖和巧克力。總之，他們最終還是坐上同一張桌子，圍在一起吃飯。",
  str_dispatch_book_chaptercont_13000_4 = "瑪莎不再整天待在村莊旁的樹林裡，而是花更多心思在料理。她不喜歡直接食用冰冷的鯡魚罐頭和鯊魚肉，於是桃樂絲姐弟的餐桌上多了蔬菜湯、魚羹、烤肉串和馬鈴薯泥。桃樂絲原本不願意由瑪莎擔起做飯的責任——這顯得瑪莎不像個客人。但相較於桃樂絲笨拙的廚藝，克魯斯顯然更喜歡瑪莎的料理，於是桃樂絲只好跟在瑪莎身邊，儘量協助一些清洗和分揀的雜事，並暗中記下瑪莎烹調時的用料與步驟。\n瑪莎對餐點的野心不止於果腹。把著湯勺，她思考了一番，說：「我們需要一些鹽。」\n「鹽？」桃樂絲思索良久，才想起那彷彿雪粒一般的佐料，她答：「可是那很難取得。」\n瑪莎聞言，若有所思地點點頭。\n第二天，桃樂絲幫長老做完雜務，回到家中時，克魯雀躍地斯拉她去廚房，指著角落的小麻袋，大聲地說：「鹽！」\n桃樂絲蹲下，用食指沾了一點雪白的細粒，放進嘴裡吸吮，鹹味在舌尖上蔓延開來。\n「哪裡來的？」\n「是瑪莎，瑪莎帶回來的！」克魯斯指向桃樂絲身後——瑪莎拎著一隻野豬腿，正走進廚房。 \n桃樂絲有些侷促，問瑪莎：「鹽……很貴吧？」\n瑪莎愣了片刻，才說：「不是買的。」\n「那是哪來的？」\n瑪莎笑著說：「附近的鹹水湖。」\n在桃樂絲姐弟的追問下，瑪莎詳細告訴他們獲得鹽的方法：她在不久前打獵時跟隨獵物找到一片鹹水湖，取水在湖邊結凍後，把未結冰的滷水帶回家，用爐火熬煮析出鹽分，再多次過濾得到可食用的鹽粒……姐弟倆聽得入迷，在瑪莎準備醃製豬肉時，仍繞著她問個不停。\n「瑪莎，妳怎麼會知道這麼多？」桃樂絲學瑪莎把鹽粒抹在豬肉上。\n「知道這些並不難。」瑪莎答非所問。\n桃樂絲暗自點頭，心想，做到這些也不難。",
  str_dispatch_book_chaptercont_13000_5 = "仍是平凡的一天。鏟雪之餘，長老為桃樂絲找了新的工作：把村裡的羊趕進樹林裡吃草。瑪莎把木材與石塊運回來後，便回到屋子裡準備晚餐。克魯斯趴在窗邊，探出頭，打量老屋新架起的冰塊骨架，末了，他大聲問廚房裡的瑪莎：「瑪莎，妳要搬走了嗎？」\n「還需要一兩個禮拜吧。」她把胡蘿蔔一片一片削進鍋裡。\n克魯斯跑進廚房，坐在瑪莎身邊，用手托著臉，靜靜地坐了一會，才緩緩說道：「可是我不希望妳走。」頓了一下，又補一句，「妳不要告訴姐姐。」\n「為什麼不能告訴姐姐？」瑪莎用湯勺在鍋中攪拌。\n「姐姐說，不能依賴大人……因為他們最終總會拋下我們。」\n湯勺無聲地攪著湯水，偶爾碰到鍋壁，發出當啷的響聲。\n「大人總有很多事情要做，姐姐說，總有一樣，會比照顧我們更重要。」克魯斯垂下頭，任憑爐火烘暖他的臉頰，「但如果是瑪莎的話，一定不會拋棄我們吧？」\n「你們……」瑪莎想問些什麼，最後還是嚥了下去，她環顧四周，問道，「桃樂絲怎麼還沒回來？」\n克魯斯也抬起頭，看向窗外。天色幽暗地滲進屋子裡，雪粒劈哩啪啦撞在窗戶上，寒風一陣接著一陣。\n克魯斯慌張了起來：「姐姐……姐姐為什麼還沒回家？」",
  str_dispatch_book_chaptercont_13000_6 = "步伐被狂風牽絆著，桃樂絲哆嗦地行走在雪地裡，風雪令她迷起眼，她幾乎看不清前方。她開始後悔今天每一個選擇：把羊趕回村莊後，她應該回家，蹲在爐火邊打盹；走到半路時，她應該察覺路途遙遠，儘早折返；即便找到湖水，她也該抬頭看看天氣，而不是蹲在湖邊等待結冰……風雪呼嘯著掃過，更糟糕的是天色逐漸黯淡，桃樂絲環顧四周，做了最壞的打算：她可能要在冰天雪地的野外睡一晚了。\n懷著這個念頭，她摸索著走近岩石堆，尋找一個可以躲避風雪的縫隙。她幸運地找到了。兩塊岩石搭出一個略淺的拱形洞穴，桃樂絲蹲坐其中，正好能容下。後腦勺枕著岩石壁上的凸起，她緩緩呼出一口氣。\n她忍不住擔心起弟弟，他會因為驚慌而哭泣嗎？或者冒著風雪去拜託長老來找她？這麼惡劣的天氣，長老如果聽說她失蹤的消息，會派人來找她嗎？瑪莎會因為她沒回家而著急嗎？或者只是坐在爐火邊不聞不問地發呆？\n桃樂絲明白克魯斯的眼神，弟弟希望她承認瑪莎，成為家人留下來，而不僅僅是借宿的鄰居。可是他們甚至連瑪莎來自哪裡都不知道，她的過去一片空白，從不向他們吐露。\n桃樂絲回想起瑪莎坐在爐火前的模樣：她低著頭，金髮垂在臉頰上，平靜、疲憊，甚至厭倦。她只在餐桌上見過瑪莎的笑容，那是暫時遺忘過往才會流露的輕鬆愉悅。桃樂絲認為自己不該相信這個人，她也不會是個好的「家人」，她背負著祕密而來，也會因為祕密離去。桃樂絲已經受夠失去了。\n好在瑪莎的房子就快修好了。\n回過神時，風雪聲似乎停歇了。桃樂絲揉了揉發麻的雙腿，鑽出岩石洞穴，極力辨別漆黑中的道路。忽然間，她聽到細微的聲響，循著聲音的方向望去時，她感覺全身的血液彷彿都凝結了——黑暗中，螢螢綠光正慢慢向她聚攏過來。\n在漸弱的風裡，桃樂絲似乎能聽到牠們的喘息聲。\n那不可能是別的生物，只可能是狼。",
  str_dispatch_book_chaptercont_13000_7 = "「砰！」\n又一匹狼撞上桃樂絲面前盤旋的風雪。桃樂絲已經記不清自己用光能術阻擋多少次狼群進攻。\n父母去世後，她偶然發現自己能使空氣凝結。起初只是手掌大小透明的磚塊，持續十幾秒就消散了，後來凝結的範圍逐漸擴大，持續時間也越來越長，狀態最好時，她能讓半扇門大小的空氣壁凝結兩分鐘。\n但在黑夜裡，她遠稱不上最佳狀態。狼的撲咬一次比一次更近，她甚至能聞到口水低落的腥臭。忽然，她腳下一絆，低頭時，一匹狼咬住了她的褲管，正壓低身子往後拖。她驚叫一聲，凝起空氣壁砸去，狼嗚咽著仍撕下她半條褲管。顧此失彼，更多伺機行動的狼低吼著作勢要撲上來。\n「砰！」牙齒咯咯地打顫，冷汗滴下額頭，她又一次驚險地擋住進攻。\n這樣不行。恐懼使她的身體變得麻木，凝結空氣壁的速度也越來越慢。這樣不行，她彷彿能聽到清晰的聲音在她耳邊低語：妳擋不住牠們，黑夜還很長，妳不可能擋住牠們。\n寒風像刀子一樣割過她裸露的小腿，過了很久，桃樂絲才發現自己在顫抖。一旦意識到恐懼，絕望便如洪水潰堤。\n空氣壁消散在風雪中，再也無法凝結。不遠處，狼眼中的綠光仍凶狠地閃爍。\n下一匹狼撲過來時，桃樂絲抬起手臂、遮住臉。\n但疼痛並未如期而來。桃樂絲聽到了咯吱作響的結冰聲，寒氣撲面，有什麼在一瞬間結凍了。放下手臂，她錯愕地發現，撲來的狼以一個滑稽的姿態靜止在半空中。下一刻，青光掠過，狼頭飛了起來，在空中旋轉，滾進雪地裡，狼身甚至沒有血液潑濺出來，而是全部凍在軀體裡。桃樂絲想要尖叫，但叫不出聲。\n狼身被人一腳踹開。來人轉過身，將桃樂絲護在身後。兜帽滑落，一頭金色的捲髮溫柔地掃過桃樂絲的臉頰。來人手握一柄雙刃匕首，在寒夜中閃動著尖利的光芒。\n桃樂絲感覺臉上有溫熱的液體流過，很快，她意識到那是眼淚。",
  str_dispatch_book_chaptercont_13000_8 = "驚險的雪夜已經過去許久，桃樂絲不再回想自己是如何被瑪莎背回村莊，也不去想那些湊來腳邊聞聞嗅嗅的雪橇犬，甚至不再想起長老如釋重負的呼氣，自然也不想克魯斯驚惶的大哭。她現在一心只想雕好手上這盞冰燈，擺在走廊上。\n就快新年了。\n瑪莎的屋子已經修好，但被長老徵用，當成會客與招待專用場所。為此，長老支付了一大桶發酵鯊魚肉。\n桃樂絲曾問瑪莎那柄雙刃匕首的來歷。瑪莎旋轉金屬柄上的開關，將兩端匕首縮回柄內，遞給桃樂絲，告訴她，自己以後不會再使用了——它現在是桃樂絲的了。桃樂絲很快就明白了瑪莎的意思，她默默收下匕首，將以往的顧慮全都拋諸腦後。\n瑪莎在告訴她：她放下了過往，並且永遠不會離開他們。\n冰燈一盞一盞地亮起，村莊中央的空地上架起篝火，長老敲響了鐘聲。村民們從家中走出，手上捧著各式各樣的食物：奶酪、蜂蜜麵包、烤香腸、肉羹、水果派、冰雪多麗酒……桃樂絲和克魯斯都裹著毛絨絨的厚白袍，他們手上拿著烤肉串，口袋裡塞滿了軟糖，正笑盈盈地往外走。\n瑪莎已經站在篝火邊，長老正和她談話。桃樂絲姐弟出來時，瑪莎對他們招了招手，露出像往常一樣的溫柔笑容。\n村民陸陸續續聚集在篝火和長老身邊，交流過去一年的大小事，分享彼此手中的美食。沒多久，一個年輕女孩率先唱起歌來，村民們和著她清亮的聲音，吟唱起古老的歌謠。另一個女孩則跳起舞，鑲著毛邊的裙擺輕快飛揚，獨有的光能術讓火星繞著她飛舞。\n桃樂絲坐在瑪莎身邊，打著節拍，輕輕哼唱舊時的歌。她的眼睛映著火光，彷彿含著兩顆遙遠、雀躍的星辰。\n歌聲漸漸小了，桃樂絲微笑著閉上雙眼，雙手緊握，靠在下巴。瑪莎環顧四周，見村民都像桃樂絲一樣，垂首合眼，彷彿在低聲祈禱。她悄聲詢問一旁的克魯斯，才知道村民在為來年祈願。\n桃樂絲睜開眼睛，瑪莎微笑地著看她，彷彿要問她為來年許了什麼願望。但下一刻，瑪莎臉上的笑容凝滯了。她的眼睛望進了篝火照不亮的角落裡。\n桃樂絲不解，轉頭循著她的目光望去，只看見空寂的黑暗。",
  str_dispatch_book_chaptercont_13000_9 = "村裡來了新的客人，這是桃樂絲幫村民挪動柴草時意識到的。一名黑髮的陌生光靈從長老家中走出，走進了修好的老屋中。桃樂絲出門時，發覺瑪莎一反常態地坐在爐火旁為克魯斯縫補衣物——往常這個時候，她早就出門打獵了。而桃樂絲回到家，卻發現火爐邊空無一人，向克魯斯問起瑪莎的去向，克魯斯指向一旁的老屋。\n黑髮光靈是為瑪莎而來的。桃樂絲非常篤定。\n午餐上桌，桃樂絲打定主意要問出黑髮光靈的來歷，但她低估了瑪莎的抗拒。\n瑪莎先是沉默許久，在桃樂絲三番兩次的追問下，才輕聲承認那是她的「朋友」。\n桃樂絲並不滿意這個回答，她迫切想要知道對方的來歷、目的，以及會不會對瑪莎造成影響。\n「只是朋友。」瑪莎簡短地結束這段單方面的詰問。\n桃樂絲很失望，只能放棄詢問。\n三人沉默地咀嚼著食物，直到門外響起警示的鐘聲。\n瑪莎聽聞，率先離開餐桌，拉開了門。\n遙遙望去，村莊中央的空地上聚滿了村民，有的人大聲咒罵，有的人捂臉低泣，還有一些在交頭接耳。桃樂絲聽到動靜，也跟隨瑪莎走出家門，湊上前張望。\n漸漸聽清人群在議論什麼之後，桃樂絲的臉色變了。\n——暗鬼。村民說村莊附近出現了暗鬼的蹤跡。",
  str_dispatch_book_chaptercont_13000_10 = "長老聚集村裡所有成年男子，將他們分為五人一隊，在村莊附近調查暗鬼活動的痕跡。\n搜救隊離開村莊時，孩童們都爬上村口的石墩，向隊伍裡的親人揮手道別。桃樂絲混在人群中，握緊藏在衣服下的雙刃匕首。長老不會允許她加入搜救隊伍，但她知道自己非去不可。\n搜救隊陸陸續續出發了，人群也逐漸散去。桃樂絲環顧四周，見無人注意自己，便低頭快步踏上離開村莊的道路，心裡估算著趕上最後一支隊伍的時間。\n忽然，有人拉住她的手臂。\n「桃樂絲，妳要做什麼？」是瑪莎的聲音。\n桃樂絲下意識地扭動掙扎：「放開我！」\n瑪莎一眼看出她衣服下的異常，伸手一摸，便從她身上搜出雙刃匕首：「妳想跟搜救隊去找暗鬼？」\n「不關妳的事。」桃樂絲伸手想奪回雙刃匕首，卻被瑪莎輕易躲開，「還給我！」\n「跟我回去。」瑪莎柔聲勸哄，「回去我就還給妳。」\n桃樂絲咬牙，「唰啦」一聲，撕爛袖子，一個踉蹌從瑪莎手裡掙脫，邁開步伐就要逃開，卻被瑪莎攔腰抱住，拖了回來。\n「妳以為暗鬼是什麼有趣的東西嗎？！」\n桃樂絲愣住了，瑪莎從未斥責過她，哪怕她做出再無禮的舉動。她不由自主地回頭看瑪莎的表情，那張臉龐因憤怒而顫抖著，對她而言，是前所未有的陌生。\n「別教訓我。」桃樂絲很快回過神，表情也變得冷冰：「妳以為妳是我的誰？」\n緊攔在腰間的手鬆開了。桃樂絲甩開瑪莎，快步向前跑去，頭也不回。\n「桃樂絲，妳打算丟下妳弟弟不管？」\n長老蘊含怒火的聲音從身後傳來，桃樂絲懊惱地閉上眼睛，停下了腳步。",
  str_dispatch_book_chaptercont_13000_11 = "瑪莎推開門，屋裡如死水般寂靜。桃樂絲姐弟的房門緊閉著，瑪莎走上前想敲門，但手卻懸在半空中，遲遲無法動作。\n「五年前，村莊被暗鬼襲擊，桃樂絲和克魯斯的父親加入搜救隊，但那支隊伍再也沒有回來。後來他們的母親循著蹤跡去找，在途中遇到暗鬼，重傷回到村莊，沒幾天就去世了。」長老的話還在瑪莎耳邊迴響，「別對她太嚴厲，每個人都有無法遺忘的過去。」\n她遲疑著，最終沒有敲響房門，而是沉默地轉過身，望向門外。\n「瑪莎。」黑髮光靈在門廊上等她，「妳下定決心離開了嗎？」\n「走吧。」她的應答如低聲的嘆息。\n忽然，「吱呀」一聲，房門開了，瑪莎的衣角被牽住，回頭時是克魯斯：「瑪莎，妳可以進來嗎？」\n房間裡，桃樂絲沉默地坐在床榻上，瑪莎走進去，她才轉過來，問她：「妳要走了嗎？」\n不等瑪莎開口，她兀自問道：「是因為我嗎？」\n「……今天，對不起。」桃樂絲的嘴唇顫抖著，「是我太莽撞了，我不該說那些話……」\n「不是。」瑪莎蹲下，平視她幾乎要掉淚的眼睛，「我只是不得不走了。」\n「為什麼？」\n「我……是一個逃兵。」瑪莎頓了一下，「我來自啟光聯邦。」\n桃樂絲顯然不理解「啟光聯邦」的意義，但她明白什麼是「逃兵」。\n「我……無法與暗鬼戰鬥了，我的戰友沒有一個存活下來，我再也無法忍受與暗鬼永無止境的戰鬥……我逃了出來，一直逃到北境。」瑪莎垂下眼睛，「我以前的同伴找到了我，如果我不回去……」\n「妳可以不回去。」桃樂絲焦急地說，「妳可以告訴妳的戰友，妳留在這裡很開心，他們一定會理解妳……妳還可以拜託長老，他會幫妳求情……」\n「妳不會離開我們，對吧？」\n「桃樂絲。」瑪莎伸手抹去她臉夾上的淚水，「我聽說了妳父母的事……我很抱歉。」\n桃樂絲呆愣住，半晌，她開口問道：「妳是因為這樣才想離開嗎？」\n「我無法……留在你們身邊，原諒我……」\n桃樂絲感覺自己的牙齒在打顫：「所以，妳每一次都選擇逃開？」\n房內陷入了令人窒息的沉默。瑪莎找不到任何為自己辯護的理由，她習慣性地扮演逃兵的角色，拙劣的表演讓身邊每一個人都能看穿她的本質。\n——令人失望的本質。\n「妳走吧。」桃樂絲洩了氣似的，將身子向後縮，彷彿要躲開她。\n瑪莎起身，看見站在牆角的克魯斯，想要摸摸他的頭，卻被他無聲地躲開。她苦笑一聲，又靜靜站了片刻，輕聲說：「這段時間別出村莊，好好保護自己。」\n說完，瑪莎走出房門，將雙刃匕首放在客廳桌上，走向屋外。",
  str_dispatch_book_chaptercont_13000_12 = "出發時，已經是第二天清晨。瑪莎和黑髮光靈走出村莊，經過石墩時，松木枝上的雪水滴落，在道路上融出一窪一窪泥濘。\n「妳不跟那兩個孩子道別嗎？」\n「已經不用了。」瑪莎蓋上兜帽，躲開頭上滴下的雪水，「他們不會想見我。」\n「不想被找到很簡單。」黑髮光靈神色複雜，「妳只需要一直逃，直到所有追蹤者都失去耐心。啟光不會在一個逃兵身上耗費那麼多成本。」\n瑪莎自嘲般地笑了，說：「你現在就可以放我走。」\n黑髮光靈陷入沉默。\n「你我都知道，那樣的生活沒有意義。」瑪莎聽著遠近的融雪聲，低聲說，「我不是為了活命才離開啟光，我只是厭倦了……被當作武器，厭倦了永無止境的戰鬥。」\n「那妳為什麼選擇跟我回去？」\n「因為——」瑪莎停頓良久才說，「我是逃兵……我無法替別人原諒自己。」\n「聽起來自相矛盾。」\n「是啊。」瑪莎苦笑一聲，「所以，我逃了很久，最終發現自己逃不出去。」\n黑髮光靈忽然停下腳步：「過了這個彎，就再也看不見那個村子了。」\n瑪莎扯動嘴角，笑了一下，輕聲說：「謝謝。」\n她往回望，仍能看見村莊入口的石墩，松木枝上的彩綢吸飽了雪水，動也不動地垂著。再望向裡面，可以看到村莊房屋漆黑高聳的屋頂，時候尚早，所有煙囪都沉寂著。\n瑪莎收回目光，準備轉身，卻發現村口的石墩上冒出一顆腦袋，遠遠地望向她的方向。她一眼就認出那是克魯斯。\n她張開嘴，寒風吹動她的金髮，她的臉頰一片冰涼，只有眼睛在發燙。\n視線中，披著白袍的女孩飛快地衝向她，在離她半臂的距離剎住腳步。\n「桃樂絲？」\n「給妳。」桃樂絲喘著氣，攤開手掌，掌心是那柄雙刃匕首，「我不要。」\n「妳應該帶走，它不值得妳逃避。如果妳想用它道歉，我不接受，它沒有什麼了不起，我毫不在乎。」桃樂絲把雙刃匕首塞進她手裡，揚起倔強的眼睛，大聲告訴她：\n「我只在乎妳什麼時候回來。」\n說完，桃樂絲向她咧開一個笑容：「妳一定會回來，對吧？」\n瑪莎哽住了，握著雙刃匕首的手顫抖著。她說不出話，只是輕輕地點頭。\n「說好了。」桃樂絲踮起腳輕快地後退，向她揮手，「那，瑪莎，再見。」\n說完，她轉身朝村莊跑去，克魯斯從石墩上跳下來，牽住姐姐的手。兩個孩子走進村莊，直到牆壁擋住他們的身影。\n村莊的屋頂上開始升起炊煙，松木枝上的彩綢也被吹動了，融雪聲滴滴答答地響，從樹林到田野，從道路到村莊。\n等到寒冰融化，所有人都知道，石墩上會重新站滿遠眺的孩童。",
  str_dispatch_book_chaptercont_14000_1 = "親愛的馬克斯先生與米妮小姐您好：\n 我是羅砂，居住在紅油沙漠。我在私釀龍舌蘭酒的箱子裡看到了你們的廣告——他們把你們的廣告傳單揉成團，當做緩衝材塞在酒瓶間的空隙裡。貴店的零件價格都很公道，真後悔這麼晚才知道你們。我找了前往影鎮的商隊，將這封訂購信託付給他們，但願路程順利，讓我們能做成這筆生意。\n 我把需要的零件單獨列了一張清單，並繪製了示意圖，附在這封信後面，你們翻到背面就能看到。\n 我根據你們的廣告單估算了價格，你們會收到我的訂金，共一千五白夜幣。請記住這個數目，雖然我已經支付商隊足夠的跑腿費，但無法保證他們不會偷偷剋扣。如果出現訂金數目對不上的情形，務必換個可信的中間人捎送包裹。不夠的話請回信告訴我，我會補齊。\n                  \n羅砂　敬啟\n寫於一個乾燥的午間\n\n\n親愛的羅砂女士您好：\n 很榮幸為您提供服務。我們已將您需要的零件分類包裝完畢，由商隊中間人帶出了影鎮（正好為一千五白夜幣，您可以繼續信任他們）。您支付的訂金多於我們的售價，在此寄還二十一白夜幣。希望這些零件能盡快送達，敬祝您順心如意。\n                   \n M&M 零件店　敬啟\n寫於雨季尾聲\n\n\n附加：\n 嗨，羅砂，我是米妮，我很不喜歡被稱為「小姐」，聽起來像個高高在上的大人物。不過爸爸倒是很高興妳稱他為「先生」，大人們都喜歡假惺惺的尊敬，就像他這次用「親愛的」當作開場白，他以前可從來不會這樣寫信，相較之下，「該死的」才是他常用的開場白。\n 我幫爸爸分揀了妳要的零件，說實話，我想像不到它們會用在哪裡。不過，妳要的許多零件都很特殊，我們都是從倉庫的最裡面挖出來的，一般改裝用不到。方便的話，可以告訴我妳想做什麼嗎？我實在太好奇了！\n 另外，我還要提醒妳，千萬不要把我回覆的內容告訴他。我不是故意要拆開他的信，但誰叫他命令我去送包裹呢～",
  str_dispatch_book_chaptercont_14000_2 = "親愛的馬克斯先生與米妮您好：\n 我昨天才從商隊那裡收到你們寄來的零件。你永遠無法指望商隊成為好的信使，他們的本職是遊蕩在外，坑騙沒有見識的土著，所以我找了真正的信使。我最近才發現，信使公會的驛站就在我們的駐紮地附近，沒幾個小時的車程就到了。把包裹託付給他們絕對是更好的選擇。我聽說，信使公會在影鎮也是值得信賴的對象，這樣一來，你們也不用和商隊的人打交道了。\n 這次，我需要你們幫忙找一些特殊金屬，不用一定要原料，哪怕只是含有這些金屬的零件，也可以寄過來。至於價格，按照零件本身的價格算就好。我把這些金屬的名稱單獨列在一張紙上，你們翻到背面就會看到。\n 我也在信封裡放了一千五白夜幣。以後你們不必寄還剩餘的錢幣了，留著當作下次交易的訂金就好。在紅油沙漠，需要修理與重組的東西太多了，修好後，總會在某天又被撞壞或磨爛。\n 哦，對了，我想修理和改裝的東西叫氣墊車，某位小女孩可能對這個消息很感興趣。\n               \n羅砂　敬啟\n寫於一個漸冷的傍晚\n\n\n親愛的羅砂女士您好：\n 是我，米妮。首先，妳可以從筆跡看出前面的稱呼不是我寫的，我絕對不會用這麼老套的開頭；其次，很高興妳不再稱呼我為「小姐」，這讓我自在多了；最後，妳寫在結尾的話太故意了！爸爸收到訂購信後，馬上朝我投來懷疑的目光——「既然妳這麼喜歡寫信，那麼回覆給羅砂女士的信就由妳來寫好了！」這就是我為什麼會坐在檯燈下，寫這封信給妳的原因。\n 接下來就是妳最關心的事情了，如果是爸爸的話，他一定會寫一堆廢話，比如「您需要的特殊金屬已分裝完畢，由信使公會帶往紅油沙漠了」，他大概無法想像，妳收到這封信的同時，零件也已經遞到妳手上了吧。\n 這次妳寄來的一千五白夜幣不夠用，還需要再補三百二十七白夜幣。我們已經為妳開通了帳戶——紅油沙漠羅砂女士專用帳戶，來記錄妳的存入與支出。爸爸說，這是他想出來最天才的生意手法。\n 另外，我發現，妳這次訂購的特殊金屬都是製作義肢的基礎材料，但願使用的人不是妳。\n\n米妮與馬克斯　敬啟\n寫於新年前夕",
  str_dispatch_book_chaptercont_14000_3 = "親愛的米妮與馬克斯先生您好：\n 上次你們寄來的金屬材料幫了大忙，不過我得很遺憾地告訴某位小女孩，確實是我需要這些材料。幾個月前，駐紮地遭到暗鬼襲擊，我的腿在作戰時受了一點輕傷，雖然不至於截肢，但傷口出於各種原因一直未能癒合，信使公會運來你們的包裹前，我一直都瘸著腿走路，開車更是成了奢望。有了這些金屬，我就能製作腿部支架了。\n 進入紅油沙漠後，我們的遭遇比在祕境時好不了多少。忘了告訴你們，我們先前曾是啟光的一分子，作為先遣隊被派往祕境探索。過去，那曾是一份艱辛但光榮的工作，而現在，我再也不想提起那些刻薄寡恩的上司。在紅油沙漠，我們擁有的只有大把大把的自由，其他時候，這片沙漠就是最精明的商人，我們必須出賣自己的食物、睡眠與安穩，才能從它手裡換到「自由」的門票。\n 在紅油沙漠裡，最令人頭痛的是天氣。如果不居住在綠洲或沙漠邊緣，白天甚至要躲到地底下，才能避開這致命的高溫；到了晚上，又不得不穿上最厚的衣服，來抵禦刺骨凍髓的寒冷。我們最初來到沙漠時沒有經驗，氣墊車的零件被搞壞一堆，到頭來都得由我更換。另外，沙漠裡四處遊蕩的暗鬼也叫人惱火，為了加固營地的防禦系統，我還需要幾個能量元件。與往常一樣，我把清單列在信紙後面。此外，我附上氣墊車的改裝設計圖，希望能給米妮一些啟發。\n 最後，我很慚愧，現在我們手頭拮据，暫時無法支付欠款，不知能否再寬限些時日，等我有了錢，一定及時結清債款。祝你們萬事如意。\n\n羅砂　敬啟\n寫於一個涼爽的清晨",
  str_dispatch_book_chaptercont_14000_4 = "親愛的羅砂女士您好：\n 我們充分體諒您的不便，您下次寄送訂購信時，再支付上次的欠款也不遲。此外，您寄來的氣墊車改裝設計圖非常有參考價值，我認為這可以抵消部分欠款。\n 祝您身體健康，事事順心。\n                \n M&M 零件店　敬啟\n寫於樹木開花的季節\n\n\n附加：\n 羅砂，又是我，米妮。\n 不知道妳收到這封信時，腿傷有沒有痊癒。啊，我真討厭這種膚淺的問候，顯得我一點也不真誠，雖然只是口頭上表達關心，但我的確打從心底希望妳的傷快點好起來。\n 上一封信中妳說妳曾為啟光工作，這可是個爆炸性的消息。我和爸爸之前就猜測過妳的身分。我遇過來自紅油沙漠的人，雖然他們之中也有人對改裝有興趣，但如果把妳比喻為這方面的專家，他們就只是踏了半條腿進門的初學者。後來這個謎團終於解開了，我的心情有點難以言喻，只能不停感嘆「果然如此」。我很高興妳能信任我們，我們絕對不會辜負妳的信任，把妳的身分洩漏出去。\n 妳寄來的改裝設計圖實在太棒了！我猜，妳一定是想增加氣墊車浮空時的穩定性，並確保浮空時砂礫不會跑進內部構造。我也在裡面發現引擎是後期更換的，我決定按照妳的分解圖，和爸爸一起把它複製出來，裝在我們拾取零件的小車上，看看效果如何。說不定，我們很快就能擁有一輛跑得超快的小車了！",
  str_dispatch_book_chaptercont_14000_5 = "親愛的米妮與馬克斯先生您好：\n 這次我一共寄了三千白夜幣，除了支付上次三百二十七白夜幣的欠款之外，我還想再購買一些儀器。我照例把儀器清單列在信紙背面。\n 我想告訴米妮，我收到妳的關心了，我相信妳是真心誠意的。收到妳的信後，我的腿傷逐漸好轉，再過一段時間就可以拆掉金屬支架了。如果不是發自內心的關懷，怎麼會有這種效果呢？哈，不說笑了，但能遇見你們確實是我的奇蹟。\n 我們最近的日子好過一點了，這得益於一次火拼。在紅油沙漠，除了暗鬼，我們還得提防四處遊蕩的幫匪。沙漠裡的幫匪數量之多，到了令人心驚的地步。總有一批又一批厭倦生活的人投身於掠奪，除此之外，家園被暗鬼摧毀的人往往也會被逼上這條路。除了與暗鬼交戰，每隔一段時間，我們還要和竄遊的幫匪交火。事後，一些無家可歸的人會選擇加入我們。\n就在前幾天，一個小女孩加入我們的營地。一群凶殘的匪賊洗劫了她的村莊，只有她逃了出來。我不想描述她經歷了什麼，講述不幸不是我的長處。而且，她一定也不希望我講出她的故事。一開始，女孩並不求我們收留她，而是希望我們替她報仇，為此，她拿出一枚組件作為報酬，那個小玩意能憑空產生蒸餾水——貨真價實的古代科技。她甚至不怕我們收了東西不辦事，她知道哪裡有更多這些玩意，而我們必須用她仇人的屍體和她交換情報。忘了告訴你們，這個女孩叫莎莫，現在她已經是我們的一員了。\n火拼之後，我們在那幫匪賊的營地裡，找到一箱又一箱的白夜幣、整整一座地窖的酒、倉庫裡滿滿的槍支和炸彈，甚至還有五輛改裝過的卡車。不過，這些都不是最重要的——莎莫帶我們找到不少古代科技的造物，現在我迫切希望得到工具拆解它們，或許下次寫信給你們時，我就擁有一枚可以源源不絕流出苦艾酒的組件了。\n\n羅砂　敬啟\n寫於一個熱浪滾滾的下午",
  str_dispatch_book_chaptercont_14000_6 = "親愛的羅砂女士您好：\n 很榮幸又收到您的訂購信，聽聞您腿傷痊癒的消息，我們為您感到非常開心。但很遺憾要告訴您，您需要的儀器我們只找到了零星幾樣，其他好幾種連名字都鮮有人知，因此也很難在一般的市場和廢品區找到，還請您寬限一些時日，運氣好的話，我們或許能在拍賣會上遇到您想要的東西。\n\nM&M 零件店　敬啟\n寫於一個喧鬧的午後\n\n\n附加：\n妳好啊，羅砂！把腿傷的事拋到腦後吧，我寫這封信給妳時，想必妳已經恢復健康了。紅油沙漠裡的生活真夠凶險的，但願妳不要再受傷。\n我迫不及待想和妳分享最近的事情了。妳知道白夜城的建城日慶典嗎？就在我寫這封信的前幾天，爸爸終於允許我一個人去白夜城玩。在建城日，接駁港的安檢較為寬鬆，遊客也不需要提前繳交文件給外交部門審核。我在下城的旅館住了三天，直到昨天所有的狂歡活動結束，才回到家裡。如果妳要來白夜城，務必請我當導遊。這幾天，我已經把白夜城的情況摸得一清二楚了——哪家蛋糕最好吃、哪家水果最新鮮、哪裡可以看到高庭的神殿……沒有我不知道的。慶典時不但有遊行和煙火能看，最重要的是可以免費吃到各式各樣的美食。平時，我總覺得白夜城的光靈傲慢得令人討厭，但在慶典日，他們見誰都露出笑臉，逢人便介紹慶典流程，還會站在路邊，熱情地邀請妳品嚐他們家的菜餚，別提有多親切了，完全沒有平時的討厭模樣。真希望每天都是「慶典日」。\n對了，包裹裡除了有爸爸幫妳找到的儀器，還有我帶回來的白夜城特產，我專挑保存期限比較長的，妳不用擔心會在半路上壞掉。另外還有一隻戴著紅帽子的木偶猴，是旅館老闆的兒子送給我的，我們還一起逛了半天慶典。木偶猴共有兩隻，我留下一隻，這一隻就送給妳了，務必好好保管啊～",
  str_dispatch_book_chaptercont_14000_7 = "親愛的米妮與馬克斯先生您好：\n我收到你們寄來的儀器了，它們讓我的研究便利了許多，有些儀器是我以前在啟光常用的，沒有在市面上流通是意料中的事，我對它們並沒有那麼執著，如果要花大錢才能在拍賣會上買到，那還是算了。\n我這次寫信，是想請你們幫忙找一些破舊的吉他和音響。我們有個隊員來到紅油沙漠後，患上了搖滾樂狂熱症，再過一個月就是她的生日了，我打算為她做一把改裝吉他，以免她總是拆了我的鋼絲繩當吉他彈。\n紅油沙漠裡不缺好樂手，而我們隊伍裡格外多，他們總能用你意想不到的小玩意弄出音樂來。每次進營地，我都能聽到乒乒乓乓的聲響，敲酒瓶的、敲油桶的、用指甲彈車蓋的、吹口哨的，難得有片刻寧靜。他們還會寫歌，牆壁上到處都是他們用噴漆槍寫的歌詞和樂譜。如果你們也喜歡搖滾樂，我可以幫忙燒錄幾首。\n米妮，我收到妳的玩偶猴子了，它現在正蹲在氣墊車的擋風玻璃後面。真叫人驚訝，妳居然會和陌生人一起逛慶典？這一點都不像妳的風格。話說，妳已經到交男朋友的年紀了嗎？哈，開個玩笑，別生我的氣。還有，忘了說，莎莫很喜歡妳寄來的司康和果醬，而我比較喜歡葡萄乾和奶酪。適應紅油沙漠的飲食習慣是件非常艱難的事情，天知道我對著醃製沙蟲乾嘔吐了多少次。妳寄來的零食簡直讓我的味蕾重新活了過來。\n\n羅砂　敬啟\n寫於飽餐過後的午休時間",
  str_dispatch_book_chaptercont_14000_8 = "親愛的米妮與馬克斯先生：\n這次，我需要大量的義肢材料。請原諒我，止痛藥的藥效剛過，我控制不住手的顫抖，如果你們實在看不清我列在信紙背面的材料，那就參考三年前的清單。\n我沒想到他們會做出那種事情，也沒想到自己最終會加入他們。我說不清自己對啟光的感情，我在那裡生活了二十幾年，每個部門都有我的朋友、同僚，我稱迦南城為「母親之城」。我被他們用槍支與冷漠驅逐，但我從未想像過把槍口對準他們。你們可以認為這是一種愚蠢的忠誠。出逃終究是背叛，背叛的兒女怎麼能對母親舉槍？\n我不知道影鎮的牆壁上會不會貼著啟光的通緝令，但如果你們聽到傳言，那是真的——我們搶劫了啟光運輸隊，六名駕駛員，二十名護衛，我們沒留一個活口。我們太害怕了。我為寫下「害怕」一詞感到羞愧，這就像某種無恥的開脫。我難以描述當時的感受，恐懼就像魔鬼附身，我們對那些無辜的臉孔扣下扳機，彈殼像流水一樣傾瀉，噗噗地落進沙地裡，根本止不住。為什麼事態會發展成這樣？\n我不否認，是我們的人先挑釁，一開始不過是個惡作劇，所有人都沒想到會演變成一場屠殺。我想不起第一聲槍響是什麼時候了，回過神時，血流了滿地，緩緩滲入沙裡。我的右手臂皮膚大面積灼傷，左小腿被光能術燒焦，右膝被子彈打得粉碎。再次醒來，是在手術台上，右大腿中段以下及左腿膝蓋以下都被截掉了。這一定是懲罰，對背叛的懲罰，對殺戮的懲罰。我已經為我犯下的過錯付出代價了，但我不願意被殘疾困在病床上，原諒我，如果將我製作義肢的行為視為逃避代價，我並不介意。\n讓這封信到此為止吧，疼痛使我眼前發黑，再寫下去，你們就澈底看不清了。\n\n羅砂",
  str_dispatch_book_chaptercont_14000_9 = "親愛的羅砂：\n妳現在身體還好嗎？過了這麼多年，我終於敢告訴妳，當時收到妳的信後，我偷偷躲在被子裡哭了好久。我甚至一度想勸妳離開紅油沙漠，來影鎮定居，當我們的鄰居。後來妳沒有再寫那樣痛苦的信給我們，而是像往常一樣，談論改裝、音樂與零食，我便假設妳逐漸好轉了，甚至連「身體還好嗎」這種問候都小心翼翼地避開。我今天喝了不少酒，不停胡言亂語，要是寫了什麼愚蠢的話，妳絕對不准笑我。\n我喝酒是因為我訂婚了。妳以前猜我和白夜城那個旅館老闆的兒子有什麼特殊交情，我明明白白地告訴妳——才沒有。雖然我們互留了地址，影鎮與白夜城寄信也很方便，但我們從來沒有寫過一封信給對方。總之，不要再拿他來調侃我了。我和我的未婚夫從小就認識，他外出遊學很久，學了一身奇怪的本事，如今在商會當業務員。用我爸爸的話來說，就是——還算個正經人。\n雖然我看過很多愛情小說，也想像過自己結婚的樣子，但真的要舉辦婚禮時，我又不自在了起來，就像被夾在兩堵牆之間，喘不過氣。在影鎮，很多人的人生是無法預料的，今天裹著破爛的衣裳在巷子裡躲雨，明天就可能戴著滿手寶石戒指，坐在鑲金的皮椅上。但有些人，比如我、比如爸爸，我們的人生很少有出乎意料的事情，不外乎就是吃飯、睡覺、交談、工作、結婚、生子和死去。現在我又要做一件意料之中的事了，我又在既定的軌道上往前邁了一步。\n我好像寫了很多喪氣的話。訂婚不應該這麼惆悵的，這樣不合時宜。我們的婚禮將在兩個月後舉行，喜帖是我設計的，第一張做好後，我便迫不及待填上了妳的名字。妳會拿著它出現在我的婚禮上嗎？\n               \n 米妮　上\n 寫於一個寂靜的黃昏",
  str_dispatch_book_chaptercont_14000_10 = "親愛的米妮：\n聽到妳要結婚的消息，我的心情很複雜。千萬不要以為我對妳的婚禮不滿，我只是有點失落。妳把婚禮比喻為「在既定的軌道上向前邁了一步」，對我來說也是這樣，只不過我是站在遠處，望著妳邁出這一步的人。我在迦南城時，也曾參加過好友的婚禮，我坐在觀眾席上，看著他們從走進禮堂，走進鮮花與彩帶裡，新生活的大門為他們打開，而我被拋在後面，那種滋味真不好受。\n本來，妳邀請我，如果是以前，我一定會去，但現在……很抱歉，我沒有在以前的信裡告訴你們，為了方便開車，我把義肢連接在氣墊車駕駛座上，在地面行走對我來說非常困難。而且，我也不希望妳看到我現在的模樣。請原諒我的自私。\n不過，我為妳做了一束鋼鐵玫瑰，妳會在上面嗅到紅油的味道。擰動花莖，花瓣會緩慢綻開或收攏。也許我已經老到無法理解浪漫了，但我想玫瑰總不會過時吧。希望妳會喜歡這束永不凋零的花。只願妳接下來的人生也像這束玫瑰一樣，沒有意料之外，但至少不懼風雨。\n妳設計的喜帖很漂亮，我很喜歡背面的圖案。告訴我，妳是不是用了我以前寄給妳的改裝設計圖？\n\n羅砂 上\n寫於一個平靜的傍晚",
  str_dispatch_book_chaptercont_14000_11 = "親愛的馬克斯先生與米妮女士您好：\n請允許我向你們致以誠摯的問候。我是羅砂的助手莎莫。我有一個不幸的消息要通知你們：前幾天，我們的車隊出行時遭到暗鬼襲擊，羅砂為了掩護隊友，引爆氣墊車，阻擋暗鬼進攻，但她也在這場意外中，永遠離開我們了。\n羅砂雙腿截肢後，一直是由我幫她去信使公會收發信。我認為我必須把這個消息告訴你們。我不清楚：羅砂有沒有和你們商量，但她確實吩咐過我，如果她遭遇不測，她在M&M零件店帳戶中的剩餘白夜幣將作為遺產留給米妮女士。如果你們需要相關法律文件，我會盡快提供。\n羅砂生前常常和我提起你們，你們的零件為我們帶來許多便利。氣墊車的改裝、隊員們的樂器、羅砂的義肢……營地裡到處都是你們的零件。隊員們大多也都知道，影鎮有一家二手零件店，做生意誠實可靠，和技術員羅砂頗有交情。\n失去羅砂對我們是個沉重的打擊。她總會對別人伸出援手，從不忘記自己的承諾，她是如此天才的技術員，能用鐵板、螺絲和扳手做出任何東西。我從十三歲開始就跟著羅砂，學拆解、學改裝。她沒有結婚，也沒有孩子，但於我而言，她就像我的母親一樣。你們之間的通信維持了這麼多年，我相信她不會讓這段情誼結束於一封潦草的訂購信，所以我補上了最後一封，希望你們不要責怪我唐突的行為。\n\n莎莫　敬啟\n寫於一個風沙逼近的凌晨",
  str_dispatch_book_chaptercont_14000_12 = "親愛的莎莫女士您好：\n非常感謝您告訴我們這個消息。\n我和爸爸都對羅砂的離世感到非常不捨。信是他先收到的，我已經很久沒回M&M零件店了。當年M&M零件店瀕臨倒閉時，多虧羅砂的訂購，才撐過了那段時間。現在我們已經不以販賣二手零件為生了，但爸爸仍執意守著那間小店，畢竟我們有個三不五時就會寄訂購信來的老顧客。\n時間已經過去太久，我已經想不起最初的通信是怎麼開始的了。大概是收到了一封有趣的信，便忍不住回信，之後又得到了善意的回覆。我因此結識了一位了不起的朋友，她會寄設計圖給我，會告訴我發生在紅油沙漠的故事，會向我傾訴生活中的歡樂與苦悶。我結婚後，就離開M&M零件店，也很少再寫信給她了。在我結婚之前，和她的鋼鐵玫瑰一起寄來的信裡，她說，結婚的朋友們走向新生活的大門，把她留在了原地，我曾以為她在抱怨，後來才明白她的感受。她懷抱遺憾地留在原地，而我又何嘗不是被鎖在門後？\n直到現在，她依舊是那位「了不起的朋友」，目睹過死亡，迎接過新生，永遠有力氣向別人伸出援手，總是能做出最勇敢、最出乎意料的選擇，比如她選擇為你們犧牲。\n這麼多年來，我不止一次懷疑過，世界上根本沒有羅砂這個人，一切全是我自己想像出來的，畢竟我們從未見過面，她甚至不肯出席我的婚禮。現在，我寧願一切都是妄想，至少我能在想像中讓她復活。然而這終究只是徒勞，我的床頭櫃上還擺著她送的鋼鐵玫瑰，筆記本裡還夾著她畫的設計圖。\n在寫這封信之前，我已經拜託商隊，他們啟程去紅油沙漠時，我會搭個便車。在您收到這封信後，我大概不久後也會與您見面。敬祝您事事順心。\n\n米妮　敬啟\n寫於安靜的午夜",
  str_dispatch_book_chaptercont_15000_1 = "凡是去影鎮的人，都必免不了踏進百人池的格鬥場，圍觀一場或多場對決。千斤重的鐵鍊咬住擂台邊緣，直直地抻開，把台上的人與物都懸吊進燈光裡。以擂台為圓點，觀眾席一圈圈往上排開去，扣成道道圓弧。貴族們愛養格鬥家，放進場中互鬥。如若一晚上下來未死，且勝場也最多的話，格鬥家便能在腰間扎上「子夜冠軍」的金帶。不過這腰帶照例只許扎一個白天，到了百人池夜裡開場時便要歸還。對戰到激烈處，觀眾也跟隨著嘶喊，還有人往台上擲金幣，錢雨叮啷啷地發出脆響。我曾在場內留到天亮，這時氣氛漸冷，觀眾們懨懨地散走，有人開始清洗場中的血跡，清水澆淋石台，邊緣便有一面面淡紅的水簾掛下來；還有僕從專門為勝者鏟走台上的金幣，用水涮乾淨了血與灰塵，收進鐵皮箱子裡，兩個人一前一後地抬出去。\n我見過最好的一場格鬥是在三年前。其中一方近些天連續奪冠，他破例扎著「子夜冠軍」的腰帶上場，額上挺著兩隻鋥亮的銅角，渾身肌肉黝黑而猙獰，一浪一浪地起伏。他的對手則是個小個子男人，身上裹著髒爛的布條，皮膚上烏青遍布，上場前似乎便受了不輕的傷。兩人一同站上台時，席中噓聲連連。侍者端著盤子在席間遊走，供客人們為心中贏面更大的那一方下注，走到邀我前來的朋友身邊時，朋友把全部注碼押在了小個子男人身上。我十分訝異，問她緣故，朋友倒拿著望遠鏡，指了指場上的小個子，說：「那人是赤汞夫人的手下。」\n雖然不常來影鎮，但赤汞夫人，我多少有些耳聞。影鎮興盛各種走私，其中最凶險的便是武器走私，走得好，黃金匝地，走得不好，人頭落地，但無論是私下交易，還是緘默拍賣，抑或大批收購，這些生意多多少少都收攏在一家商會手裡，而這家商會的首領便是赤汞夫人。我看著台上的兩人相鬥，子夜冠軍出拳沉而重，裹著光能術砸下去，滿場碎石飛濺，小個子則踉蹌著腳步左右躲閃，躲得慢了，被碎石擊中，跌坐在地上，來不及起身，只好勉強滾避開。\n我不禁問朋友：「下屬與人死鬥，赤汞夫人也置之不理？」\n朋友搖頭，飛快地瞥了一眼角落的黑暗處，悄聲說：「她就坐在這附近看著呢。」",
  str_dispatch_book_chaptercont_15000_2 = "熱而乾燥的白色光束全投在擂台上，觀眾席藏在陰影裡，看客們的叫嚷聲如潮湧。我順著朋友那一瞥往黑處看，忽然發覺那一隅黑暗是寂靜的，黑衣的打手們肅立著，最深處確實坐著一個人，但陰影太暗，看不出那人的模樣打扮，只覺那一片黑似是泛著銹紅。擂台上，小個子看准時機，偷送一擊，正中敵手肋下，霎時間場上火光張熾，那冠軍格鬥家的嘶吼全場皆聞，看客們一時沸騰起來。我身後押了格鬥家的人低聲咒罵著，但那一角的黑暗裡仍是安靜的。\n我實在不解，又問朋友：「赤汞夫人為什麼要送自己下屬上擂台？」\n影鎮人沒有豢養格鬥家的習慣，把手下當玩物作踐的商會首領，更是聞所未聞。\n朋友低聲回我：「那人是叛徒，聯和了外人，想劫自家商會的貨物。」\n我於是恍然，想了一想，又向朋友說：「你這注押得不好，瞧台上的陣仗，赤汞夫人擺明了是要這叛徒的命。」\n朋友笑了笑，拈起望遠鏡繼續觀看場上搏鬥。\n中了小個子一擊後，格鬥家發了怒，邁大了步來捉那小個子。剛才那火焰四迸的一擊似是耗光了小個子的力氣，他疲憊地躲閃著，徑直退到了擂台邊緣。格鬥家見狀，掄胳膊橫掃過去，小個子被掃中了胸膛，一個踉蹌跌出了場外。看客們一片驚呼，回過神時，卻見小個子抱住了鐵鍊，並未摔下擂台。格鬥家蓄勢，預備追補一擊，卻不料裁判吹響了中場哨音，格鬥家只好跺著腳退開，而小個子則咳嗽著，慢慢爬回場中。\n白亮的光束從台上撤開，漫漫地照亮靠近場中央的觀眾席。忽然，不遠處那隅黑暗動了，一個渾身血汙的俘虜被推了出來，他垂著頭，雙手被捆束在身後，搖搖晃晃地跪在光與暗的交界處。我一時悚然，又忽聽到台上傳來一聲嘶吼，連忙追著聲音望回去，只見方才還趴在地上喘息的小個子此時已竄了起來，但又馬上被裁判和侍從攔住，一連串不成調的咒罵聲從他血跡斑斑的嘴角滾落。",
  str_dispatch_book_chaptercont_15000_3 = "哨音響起，中場休息結束，光束聚回擂台，新一輪的戰鬥開始了。我忍不住用餘光偷覷跪在觀眾席間的俘虜——他沒有發出任何聲響，只是耷拉著腦袋，任憑髮梢的血與汗水噠噠地滑落。再看台上，情勢居然與上半場大不相同了：\n小個子雙臂上火焰躍閃，伸出的十指如烙鐵般灼紅，他拖著身軀緩慢向對手逼近，場中石塊如雨點般砸落，他雖然依舊在躲，但已不似之前的苟延殘喘，即便被石塊砸中，仍扛著傷往前走著。格鬥家被他逼得不自覺地後退，但終究被他拉近距離。忽然，火焰亮起，那一瞬的亮光過後，小個子已捉住了對方的手腕，頓時焦煙四溢，格鬥家痛而怒號，緊接著，小個子的拳頭如長勾般挑出，正扎中敵手的腹部，看客席中一片驚呼，我身後有人猛然站起，厲聲喝罵，侍從們紛紛撲上擂台，把小個子從格鬥家身上拖開。\n小個子叛徒再次出現在我眼前時，擂台上已另換了一對格鬥家，他穿著禮服，脖頸處打著項圈般的領結，內襯衣本是新換的，然而沒過多久，又被血跡浸透了。我用餘光瞥他，只見他渾身微微打顫，想必還未從剛才的生死搏鬥中緩過神來。\n黑暗中，有人踢了踢跪倒在地的俘虜，沉而柔緩的聲音響起，問那小個子的叛徒：「你知道他的名字嗎？」\n叛徒用手帕揩著嘴角的血跡，沙啞著嗓子報出了一個外號。聲音低低地笑，說出了另外一個名字，她說：「你連他的真實姓名都不知道，就敢相信他的話？」\n叛徒艱難地從牙縫中擠出字句：「夫人，我妹妹她……」\n那聲音低嘆著：「假如你妹妹還活著，他的謊話能維持這麼多天？」叛徒怔了怔，過了片刻，壓抑的哭聲從他喉嚨裡湧起，他慢慢地跪了下去，把頭埋進黑暗裡。\n忽然，一道細而冷銳的銀光從那俘虜的胸膛破出，很快便縮回了，俘虜輕哼一聲，悶然倒地，殷紅的鮮血從他身下漫出。哭聲收住了，叛徒直起身子，呆愣愣地盯著自己腳邊的屍身，似是驚詫，又似是仇恨。簌簌的衣料摩擦聲響起，坐在黑暗中的人，終於把面孔曝露在昏暗的光裡。\n霎時間，四周靜了靜。那人赤色的頭髮順著肩膀與手臂滾落，彷彿一道猩紅的沉默的河，她低頭打量跪在腳邊的叛徒，不曾看別處，但我卻感覺她的目光無處不在，就像極冷的陰天裡白漫漫的日色。我看了一眼，便不敢再看，餘光只能瞥見她別在衣襟上的百合，新鮮嬌嫩，令人疑心那瓣尖會滾落露珠。\n她伸出一隻手，垂在叛徒眼前。叛徒下定了決心似的，輕攥住那隻手的指尖，把額頭緊緊貼在手背上。\n那是一個宣誓效忠的儀式。",
  str_dispatch_book_chaptercont_15000_4 = "朋友靠這一注賺了不少，便邀我去酒館同飲，我和她談起了赤汞夫人。朋友和赤汞夫人的商會打過幾次交道，認得裡面不少人，卻只見過赤汞夫人一面，談到時，朋友笑稱：「夫人生得太惹眼了，要是露面露得太勤，難免會有流言。」\n但影鎮中關於赤汞夫人的流言仍是不少。我聽了些許，大多數都荒謬得叫人發笑。不過，其中確是實情的大概是赤汞夫人的出身。叫人吃驚，她來自白夜城，原本的名字並不叫「赤汞」，似乎尾音有「娜」，總之是標準的白夜貴族名字。從白夜上城到影鎮，堪稱流落，不知她是怎樣度過的。\n「她是下嫁到了影鎮，」朋友的語氣篤定，湊在我耳邊，悄聲道，「總之，就是那一類古怪的愛情故事：她年少時和影鎮的一個武器走私商相識，後來不知怎麼，鐵了心要下嫁，家族裡的長輩攔都攔不住，請了教會的人來，說是要褫奪了她貴族的頭銜，她仍是不肯低頭。」\n「她那時大概很年輕吧。」\n「年輕，不年輕怎麼做得出來這樣的事？」\n「即便年輕，但把原先的生活都顛覆了，去賭一個曖昧不清的未來，這樣的代價，也不是一般人承受得來的，」我搖著頭嘆息，又問，「既然如此，她的丈夫如今在哪裡？」\n「死了。」\n「死了？」我追問，「怎麼死的？」\n「據說是和白夜城的貴族生了過節，荷米斯家族，你知道嗎？也許是生意上的事，也許是某些不能說的事——誰知道上城那些人在做什麼。」朋友哂笑，「然後就被抓住殺掉了。留下的商會，就由赤汞夫人攬在了手裡。」\n「赤汞夫人不去報仇嗎？」\n「荷米斯家族——多麼煊赫，只要你去打聽。即便是赤汞夫人的原先的家族，也萬萬比不上。」\n酒意逐漸升騰到眼前來了，朋友又說了些什麼，我已記不大清楚，只有腦袋裡迴盪著一個猜想：像赤汞夫人那樣的人，這仇恨，大概是無法擱置的。",
  str_dispatch_book_chaptercont_15000_5 = "此事過去了兩年。我的小說很為一位子爵賞識，她邀請了白夜城的書商，想多拓印幾本，方便書友傳閱，書商因此央求我去往白夜城，商量拓印的事宜。我把這看作一次參觀白夜城的好時機，便先於約定的時間，早早地遞交了遊覽的審批文書。在等候審批下發的日子裡，我一直待在中轉的旅館。\n中轉區的旅館樣式有許多，影鎮的風格、白夜城的風格，彼此交錯著，鱗次櫛比。我住的旅館是一位白夜下城的平民家族開的，開張至今，已逾百年。他們選的地段很好，客房一排，陽台全迎著清涼細薄的晨光。我在房間裡寫故事，一寫便是一天，只傍晚的時候偶爾會去大廳裡吃晚餐，翻著報刊或者雜誌直到廳內熄燈，大廳的書架上，甚至還有我的小說。每天與我交流最多的是店裡的侍者，他們會把早餐送到房間裡來，順便把前一天客人換下來的衣裳用布袋裹了，運送去洗衣室，第二天，清洗好的衣裳便會與早餐一道送來。\n那天黃昏時，天氣不算好，遍天都是鉛色的雲翳，中轉區房屋多，冷風在牆壁和欄杆間吹動，我心中壓抑，便去大廳吃晚餐，換換心情。旅店中的客人不算多，我住得久，很多都成了熟面孔。但這次，我瞥見了一道生人的背影。\n很常見的影鎮人打扮，皮靴和厚料的大衣，一條針腳細密的黑色圍巾纏住脖頸，頭髮全裹在古銅色花式的頭巾裡，她倚著櫃檯站著，聲音低柔而語速飛快地向旅店主人詢問著什麼。我聽得不細緻，只零零碎碎地聽到幾個「上城」、「審批」的字眼，想必是在問白夜城相關的事情。她聲音聽著實在耳熟，我忍不住用餘光追著她的身影，直到她轉過身來。\n雖然口鼻被黑色圍巾遮擋了大半，但我絕不會認錯——她一定是赤汞夫人。",
  str_dispatch_book_chaptercont_15000_6 = "她倚靠著櫃檯，看著侍者把她的皮箱送進客房裡去，時不時抬手，把惹眼的紅色髮絲順進頭巾裡去。我一時釘在座位上不敢動，只敢裝作無意地環顧大廳，試圖從人群裡找出她的隨從來。很遺憾，我沒有發現任何隨從的蹤跡。她把圍巾又往上提了提，將鼻樑也整個遮住了，這才低著頭快步向房裡走去。我終於明白，這可能是一趟祕密旅行。\n待她的腳步聲消失，我才緩緩吐出一口氣。這樣一位人物忽然獨身一人出現在中轉區的旅館裡，我心裡有著不好的猜想，打算著早早避回房間，但坐了片刻，忍不住朝她離去的方向看了又看。這樣無知無覺地看了幾回，我忽然回神，意識到自己居然在期待她的現身。想通了這件事，我不知哪裡來了勇氣，索性在大廳坐下等待。\n侍者給我又續了一杯啤酒，喝到一半，她終於從客房走廊的陰影裡慢慢地走出來了。這次，她換掉了頭巾，戴上了一頂軟呢帽，長髮則結成辮子，藏在圍巾和大衣裡。她顯然不願惹人注目，便只在燈光昏暗的地方走動，然後挑了一隅無人問津的角落坐下——她的桌子靠近書架，且恰巧在我十點鐘方向。我很心驚，但又暗暗雀躍。\n等待侍者上菜的間隙裡，她隨手取了一本架上的書，我看得分明，那正是我數年前出版的小說。我感覺自己被推動著站了起來，汗津津的手捧住盛啤酒的木杯，一步一步地向她走過去。\n我終於站在了她的面前。來不及局促，我緊攥著酒杯，俯下身，去指她手中的書，裝作不認識她的樣子：「女士，您喜歡這本書？」\n「我喜歡書名，」她從容地微笑著，仰起頭來看我，指腹在燙金的標題上摩挲，「它讓我想起漂亮的東西。」\n我感覺自己呼吸不暢，迫於美的威壓——就像把臉埋進了冰水裡，或是將頭伸進了迅疾的冷風中。我努力地吸著氣，盡量不讓自己牙齒打顫：「真高興您能喜歡，我是作者……您看，對，這就是我的名字。」",
  str_dispatch_book_chaptercont_15000_7 = "在她對面坐下來時，我才發覺自己的內襯衣的後背部分已經浸滿了冷汗。我們似乎聊了一下小說，如今回想，竟一句話也記不起來，唯一能清晰記起的，僅是一種異樣的感覺，彷彿整個人都浸在湖水里，人在岸上走動著，而熱鬧都隔在另外一個世界中。回過神時，我已坐在她房間的陽台上，與她之間隔了一張小圓桌，桌上擱著點心和酒杯，正中央擎起一隻細頸的花瓶，一支百合插在當中，花萼青綠。\n全然的黑夜還未降臨，四周卻陰沉且昏暗，天光都被擋在雲後。冷風淅淅，我打了個寒戰，這才想起剛才在大廳裡，侍從正擺放餐點，她卻忽然建議我去往陽台上用餐，我應允了，於是一路隨她到了這裡。她摘了帽子和圍巾，隨手從窗戶裡丟進屋中。大衣和軟椅的扶手一圈地擁著她，未經遮掩，直視她簡直叫人惶恐，我只好側轉了臉，去看她逐漸鬆散的、飄飛在風裡的紅髮。\n「我和您一樣，也是去白夜城，」她笑著，把手指在沾濕的紙巾上揩過，我這才想起之前我們在講各自的旅程，「我年少時，是住在白夜城裡的，小時候的玩伴都在白夜城裡。」\n「後來去了影鎮，一切都好，只是臨走時和朋友吵了架。」\n「因為什麼吵呢？」我正襟危坐地聽她講話。\n「時間太久了，記不起來，只記得那時生氣的感覺，整顆心像脹大了一樣，連跳動都既沉又重——現在，連發生了什麼事都忘得乾淨了，回想起來，只覺得幼稚。」她把乾淨的手指插進頭髮裡，慢慢地梳著，辮子打著旋，輕巧地散開了，「我最近又想起那位朋友來——先從夢開始的。」\n「夢？」\n「就是夢。在夢裡，我還是在原先住的房子裡，粉白的牆壁，金棕色的門，面前是以往用過的妝台和鏡子。鏡子裡倒映出朋友的臉來，她正拿著梳子，為我梳頭髮。」她攏著河流般的長髮，目光似在打量我，又似在神遊般地思索，「她的模樣很漂亮，比以往我見到的她要漂亮許多。醒來後，我一連想她想了許多天。」\n「您去白夜城，是為了見朋友？」\n「倒也談不上是『見朋友』，」她嘆息著，「登門去見她，固然很好，可惜就是難辦。若實在見不著，遠遠地望她一眼，也是好的。」\n中轉區的旅館都亮起了燈，大大小小的光暈，在潮濕且稀薄的風煙中閃爍。她扶著酒杯看著我。我一時恍惚，早早落潮的畏懼又逐漸漲起來——那張臉上的表情緩緩退卻了，似乎只剩了一些符號，隱喻著宿命，就像寂靜的毛邊月亮。夜色瀰漫上來了，她的臉也就沉沒進黑暗當中，連帶著她旗幟般的長髮。黑暗深處又泛起冰冷的銹紅。",
  str_dispatch_book_chaptercont_15000_8 = "我醒來時，緊緊地喘了一口氣，發覺自己躺在床上，還是一個完好的人，不由如釋重負。腦內是針扎般的疼痛，宿醉的後遺症，窗簾外天光暗淡，我比以往醒得要早，侍者還未叩響我的房門。扶著腦袋走出客房，向赤汞夫人所在的房間望去時，卻發覺那屋子已然空了。我悵然而呆滯地順著長廊一路走下去，直到大廳裡，望見了店主，才停住腳步。\n「您知道……那位夫人，」我啞著嗓子，指了指身後的空房間，「她離開了麼？」\n「凌晨便走了，」店主停下了手中的活計，饒有興致地打量我，「白夜城裡的人開著浮空艇來接的。我識人不會錯，那位夫人是貴族吧？」\n我不知該點頭還是搖頭，心中有的只是遲滯的悵惘。店主嘆著氣：「她進來時，我就覺察她與眾不同了——那樣的美貌，實在叫人不安，」說著，他把讚許的目光投向我：「你敢上前去和她講話，真是了不起。」\n我搖了搖頭，只覺喉中全是沉甸甸的苦澀，慢慢轉身回到房間裡，在書桌前坐下。過了片刻，侍者送來了早餐和清洗過的衣物。我又在書桌前坐了許久，直到窗外的陽光有些刺眼了，才從位置上離開。\n我照例是要把新洗的衣物收進櫃子裡的，於是走到榻邊，心不在焉地折衣服。不知是疊到了哪一件，或許是輕輕地抖了兩抖，衣裳的褶皺間忽然飄落了一片枯薄的小東西。我拈起來一看，心中頓時受了極大的震動——\n那是一朵枯萎的百合花，被壓製成了書籤的樣子。那是她的象徵。",
  str_dispatch_book_chaptercont_15000_9 = "此後又等了三四天，出人意料的是，我的入城審批仍未下發。我心中奇怪且焦躁，眼見與子爵及書商約定的日子要到了，我只得走出旅店，去四處打聽白夜城裡的消息，或尋找別的路徑，以免耽誤了與人會面。\n這一打聽才知道，白夜城中最新發生了一起謀殺案：荷米斯家族的長男不幸殞命，白夜城因此戒嚴了，出入城的審批迫不得已只能積壓。我抑制不住聯想，一時心中惴惴，回到旅店內，琢磨著赤汞夫人講過的話，總覺得那些話裡隱情綿綿，其中某句可能就暗示了這場謀殺。我想得入了神，連與子爵的會面都忘到了腦後。\n此事傳得沸沸揚揚，旅店裡的洗衣工都能講上幾句傳聞，我卻莫名地被隔在了熱鬧外。我是那個知情者，保守住了祕密。不到風波過去，真情是不堪洩露的。此後又過了兩三天，入城審批漸漸開始發放了，隨著審批文件一同傳發的，還有那件謀殺案的結果——兇手已被抓住，白夜城即將對兇手處以絞刑。\n我心神不寧地與子爵見了面。期間，我多次想打斷她絮絮的讀書感悟，向她問一問謀殺案的詳情——她說話時神情專注而喜悅，彷彿生活著的世界裡失去了兩條人命並不值得驚怪，也無意向我這樣的異鄉人提起。我只好按捺了疑問。會面後，子爵囑咐書商領我遊覽白夜城，便向我們道了別。\n我迫不及待地要求書商引我去參觀刑場，到達時，已經是黃昏時分了。\n「行刑還沒有開始麼？」我抱著希望問。\n書商想了片刻，問我：「是前些天荷米斯家的那件案子？」\n「是。」\n「已經完了。」他大概是看我滿臉迷茫，又補了一句，「處刑已經結束了，就在昨天。」\n刑架平時是不許人靠近的，只能遠遠地觀望，刑場邊行人寥寥，鴿子在地上擺晃著肥身子，笨拙地走著。\n「您去看了？」我問他。\n「當然看了。」\n「您知道兇手的身分嗎？」\n「這您得去問審判庭。」\n我漸漸疑心起來：「兇手是個什麼樣的人？」\n「不知道，」書商搖著頭，「犯人都是要穿囚服的，破爛的布衣一裹，什麼都看不出來。頭上還要套麻袋，犯的事重了，就要改換成鐵頭盔，只露兩隻眼睛出來。絞刑是不許人看罪人的臉的。」\n「為什麼？」\n「不嚇人嗎？」他笑著。\n我只覺搖搖欲墜，聽了這話，勉強笑道：「蒙了面，也未必不嚇人吧？」\n「熱鬧嘛。」他仍笑著。",
  str_dispatch_book_chaptercont_15000_10 = "我逃也似的離開了白夜城，朋友邀我下榻影鎮，我也慌忙拒絕了。再到影鎮，已經是幾個月後的事情了。\n朋友照例邀我去酒館裡喝酒。酒館裡很多人，講話聲又密又碎。朋友已喝得半醉，倒轉了酒杯，拿杯底指著人群裡的某處，說：「看，百人池裡那個叛徒。」\n我轉頭去看，直到目光捉到了那個黑衣的小個子男人，才隱約想起幾年前的那場搏鬥，隨後而來的，全是關於赤汞夫人的記憶。若是幾個月前遇見他，我一定早早地躲開，但過了這些時間，心情畢竟平靜了下來。我擎著酒杯，朝他走去。\n「我記得你，」我向他舉杯，藉著酒勁說，「我在百人池裡見過你。」\n他的神情一時陰晴不定起來，他身邊的同伴則交換著眼神。我早已忘記畏懼，也記不起這些人的兇惡，只顧著講話：「我和你們的主事人——赤汞夫人，有過一面之緣。」\n聽到這話，他們的表情終於柔順了。\n「替我向她問聲好，就說，我是那個作家——中轉區的旅館，她一定記得。」我琢磨著他們的眼神，想從中找出悲傷的痕跡，以印證自己的猜測。但那些年輕的、帶著陳年傷疤的臉上，只有一些寡淡的、模糊的表情。\n「她還好嗎？」我試探著問道。\n「夫人很好，」他們互相看著，有些還微微地嘆息，「只是她已不再是商會的主事人了。」\n「那你們豈不是沒有主事人了？」\n他們大笑起來：「前一位走了，後一位就替上來了，哪有商會缺主事人的！」\n談話就此戛然而止了。此後，我再也沒有見過赤汞夫人，也再未聽聞過她的消息。\n影鎮和白夜城的傳言是不間斷的，絮絮碎碎地在人潮裡湧流，我多多少少地聽說了，但從那些零碎的傳言中，我仍無法判斷，那天去往白夜城的赤汞夫人，到底是為了向仇人捎去死亡的信函，還是僅為了遙遙地望一眼夢裡的好友。",
  str_dispatch_book_chaptercont_15000_11 = "各位親愛的讀者，很榮幸能與你們在伊馮女士的小說集里相遇。我們選用《赤汞夫人》作為小說集的總標題，希望不會冒犯到你們。《赤汞夫人》或許不是伊馮女士最好的作品——畢竟它只是一篇體量極小的短篇小說，但它一定是你們討論最多的那篇。作為伊馮女士忠實的讀者，在讀完這篇人物傳奇後，我的第一個念頭就是：找出那位真實的「赤汞夫人」。想必你們很多人的想法都和我一樣。\n為此，我專程拜訪了影鎮負責武器販賣的商會、參觀了入場費為一千白夜幣的百人池、託人翻閱了白夜城審判庭的捲宗，甚至逐個詢問了荷米斯家族的僕傭，向他們打聽當年那件轟動的謀殺案。接下來，我將會把我的考證與結論分享給你們。\n伊馮女士的傳奇小說以「真實」聞名，你總能從中找到一些「確有其事」的東西。比如影鎮販賣武器的商會。準確來講，影鎮販賣武器的商會並不少，不過有些也兼賣些其他東西。這篇小說是十年前寫出來的，當年的影鎮中是否有一家商會統管全部的武器交易，已經很難考證了。畢竟影鎮的複雜情況不是有毅力就能弄清楚的。\n至於白夜城的謀殺案，倒是能見於卷宗，畢竟它在白夜城廣為人知——荷米斯家族的長男，也就是拉瓊長老最年長的兒子，死於一場謀殺，更巧的是，他身上致命的傷口是由一柄細長的鋼製武器造成的，這讓我們很容易就聯想到了赤汞夫人的武器——在百人池中，殺死俘虜的「細而冷銳的銀光」，是完全符合這個細節的。但是這樁謀殺案的真兇卻不見於卷宗。她或他分明被處以極刑了，白夜城仍不願向世人公佈詳情，甚至不願露出兇手的臉，連荷米斯家族目睹過謀殺現場的僕人，也講不清兇手的樣貌。倒也不必沮喪，這是白夜城和貴族們一貫的做法。不過，真相早晚有一天會浮出水面，畢竟沒有誰是不死的，不是嗎？",
  str_dispatch_book_chaptercont_15000_12 = "各位讀者最關心的，當屬「赤汞夫人到底是誰」，我猜得不錯吧？不過，根據我的考證，赤汞夫人的的確確只是一位虛構的人物。她誇張的美貌便是證明。在十年前，感情小說格外受到歡迎（當然，時至今日，它們依舊暢銷不衰），而那時的女主角們往往都擁有著驚人的美貌。伊馮女士之所以賦予赤汞夫人「令人畏懼」的美貌，純粹是對流行的反諷。而拋棄貴族身分下嫁的噱頭，也是一種不動聲色的諷刺，畢竟，感情小說中，不顧身分的桎梏而結合的愛人們也俯拾皆是。\n那麼在故事裡，伊馮女士到底給予了赤汞夫人怎樣的命運呢：就像她在結尾處提出的問題那樣——她去往白夜城，到底是複仇，還是看望好友？結合近些年白夜城的流言——不少貴族被處死或者流放（我們甚至都不清楚原因），我們完全可以猜測，在伊馮女士的設定裡，愛情不過是幌子，赤汞夫人下嫁影鎮的真實原因其實是避難。畢竟各位讀者都了解伊馮女士的寫作習慣，她擅長用謊言來掩蓋那些「不能說的事情」。\n既然如此，我們是不是就可以認定，赤汞夫人去往白夜城只是為了看望好友？答案是——不能。在旅店邂逅的篇章中，伊馮女士在傳達真實有效的資訊上，堪稱吝嗇，就好像一條河流從她面前奔湧而過，她卻只俯身掬起一捧——一捧水是無法定義整條河流的。在故事中，或許那個可憐的犧牲者確實是她想要手刃的敵人，或許她只是單純地想念年少時的好友，或者，這兩者都是她的目的，她只是把一半的實情告訴了「我」而已。\n各位親愛的讀者，你們一定對我的結論感到十分沮喪。不過，《赤汞夫人》並不是偵探小說，伊馮女士也不想書寫一個關於「真相」的故事，她想為我們提供的是「真實」，那些被傳奇掩蓋的、與真實的生命有關的故事。她將鮮嫩的百合、銳利的刀劍與令人驚嘆的美貌賦予赤汞夫人，其目的不過是讓我們集中精神，不至於錯過與角色萍水相逢之時，那一瞬間的「真實」——就是那吝嗇的一捧水，它比全部的傳奇加起來還要寶貴。",
  str_dispatch_book_chapter_get_des = "完成派遣後，有機率發現此冊書籍。",
